comms.text:
@1 וּמַלִּיל יְיָ עִם משֶׁה בָּתַר דְּמִיתוּ תְּרֵין בְּנֵי אַהֲרֹן בְּקָרוֹבֵיהוֹן אֶשָּׁתָא נוּכְרֵיתָא קֳדָם יְיָ וּמִיתוּ:
@2 וַאֲמַר יְיָ לְמשֶׁה מַלֵּל עִם אַהֲרֹן אָחוּךְ וְלָא יְהֵי עָלֵל בְּכָל עִדָּן לְקוּדְשָׁא מִגָּיו לְפָרֻכְתָּא לָקֳדָם כַּפֻּרְתָּא דִּי עַל אֲרוֹנָא וְלָא יְמוּת אֲרֵי בַּעֲנָנָא אֲנָא מִתְגְּלִי עַל בֵּית כַּפֻּרְתָּא:
@3 בְּדָא יְהֵי עָלֵל אַהֲרֹן לְקוּדְשָׁא בְּתוֹר בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא:
@4 כִּתּוּנָא דְבוּצָא קוּדְשָׁא יִלְבָּשׁ וּמִכְנְסִין דְּבוּץ יְהוֹן עַל בִּסְרֵיהּ וּבְהֶמְיָנָא דְבוּצָא יֵסַר וּבְמִצְנֶפְתָּא דְבוּצָא יָחֵת בְּרֵישֵׁיהּ לְבוּשֵׁי קוּדְשָׁא אִנּוּן וְיַסְחֵי בְמַיָּא יָת בִּסְרֵיהּ וְיַלְבְּשִׁנּוּן:
@5 וּמִין כְּנִשְׁתָּא דִּבְנֵי יִשְׂרָאֵל יִסַּב תְּרֵין צְפִירֵי עִזִּין לְחַטָּאתָא וּדְכַר חַד לַעֲלָתָא:
@6 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָּאתָא דִּי לֵיהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵיהּ:
@7 וְיִסַּב יָת תְּרֵין צְפִירִין וִיקִים יָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@8 וְיִתֵּן אַהֲרֹן עַל תְּרֵין צְפִירִין עַדְבִין עַדְבָא חַד לִשְׁמָא דַיְיָ וְעַדְבָא חַד לַעֲזָאזֵל:
@9 וִיקָרֵב אַהֲרֹן יָת צְפִירָא דִּי סְלִיק עֲלוֹהִי עַדְבָא לִשְׁמָא דַיְיָ וְיַעְבִּדִנֵיהּ חַטָּאתָא:
@10 וּצְפִירָא דִּי סְלִיק עֲלוֹהִי עַדְבָא לַעֲזָאזֵל יִתָּקַם כַּד חַי קֳדָם יְיָ לְכַפָּרָא עֲלוֹהִי לְשַׁלַּח יָתֵיהּ לַעֲזָאזֵל לְמַדְבְּרָא:
@11 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָּאתָא דִּי לֵיהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵיהּ וְיִכּוֹס יָת תּוֹרָא דְחַטָּאתָא דִּי לֵיהּ:
@12 וְיִסַּב מְלֵי מַחְתִּיתָא גּוּמְרִין דְּאֶשָּׁא מֵעִלַּוֵי מַדְבְּחָא מִן קֳדָם יְיָ וּמְלֵי חָפְנוֹהִי קְטוֹרֶת בּוּסְמִין דַּקִּיקִין וְיָעֵל מִגָּיו לְפָרֻכְתָּא:
@13 וְיִתֵּן יָת קְטוֹרֶת בּוּסְמַיָּא עַל אֶשָּׁתָא לָקֳדָם יְיָ וְחָפֵי עֲנָנָא קְטָרְתָּא יָת כַּפֻּרְתָּא דִּי עַל סַהֲדוּתָא וְלָא יְמוּת:
@14 וְיִסַּב מִדְּמָא דְתוֹרָא וְיַדִּי בְאֶצְבְּעֵיהּ עַל אַפֵּי כַּפֻּרְתָּא קִדּוּמָא וְלָקֳדָם כַּפֻּרְתָּא יַדִּי שְׁבַע זִמְנִין מִן דְּמָא בְּאֶצְבְּעֵיהּ:
@15 וְיִכּוֹס יָת צְפִירָא דְחַטָּאתָא דִּי לְעַמָּא וְיָעֵל יָת דְּמֵיהּ לְמִגָּיו לְפָרֻכְתָּא וְיַעְבֵּד לִדְמֵיהּ כְּמָא דִי עֲבַד לִדְמָא דְתוֹרָא וְיַדִּי יָתֵיהּ עַל כַּפֻּרְתָּא וְלָקֳדָם כַּפֻּרְתָּא:
@16 וִיכַפֵּר עַל קוּדְשָׁא מִסּוֹאֲבַת בְּנֵי יִשְׂרָאֵל וּמִמֶּרְדֵּיהוֹן לְכָל חֲטָאֵיהוֹן וְכֵן יַעְבֵּד לְמַשְׁכַּן זִמְנָא דְּשָׁרֵי עִמְּהוֹן בְּגוֹ סוֹאֲבָתְהוֹן:
@17 וְכָל אֱנַשׁ לָא יְהֵי בְּמַשְׁכַּן זִמְנָא בְּמֵעֲלֵיהּ לְכַפָּרָא בְקוּדְשָׁא עַד מִפְּקֵיהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵיהּ וְעַל כָּל קְהָלָא דְיִשְׂרָאֵל:
@18 וְיִפּוֹק לְמַדְבְּחָא דִּי קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי וְיִסַּב מִדְּמָא דְתוֹרָא וּמִדְּמָא דִצְפִירָא וְיִתֵּן עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר:
@19 וְיַדֵּי עֲלוֹהִי מִן דְּמָא בְּאֶצְבְּעֵיהּ שְׁבַע זִמְנִין וִידַכִּנֵּיהּ וִיקַדְּשִׁנֵּיהּ מִסּוֹאֲבַת בְּנֵי יִשְׂרָאֵל:
@20 וִישֵׁצֵי מִלְּכַפָּרָא עַל קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא וִיקָרֵב יָת צְפִירָא חַיָּא:
@21 וְיִסְמוֹךְ אַהֲרֹן יָת תַּרְתֵּין יְדוֹהִי עַל רֵישׁ צְפִירָא חַיָּא וְיִוַדֵּי עֲלוֹהִי יָת כָּל עֲוָיַת בְּנֵי יִשְׂרָאֵל וְיָת כָּל מֶרְדֵּיהוֹן לְכָל חֲטָאֵיהוֹן וְיִתֵּן יָתְהוֹן עַל רֵישׁ צְפִירָא וִישַׁלַּח בְּיַד גְּבַר דִּזְמִין לִמְהַךְ לְמַדְבְּרָא:
@22 וְיִטּוֹל צְפִירָא עֲלוֹהִי יָת כָּל חוֹבֵיהוֹן לְאַרְעָא דְלָא יָתְבָא וִישַׁלַּח יָת צְפִירָא בְּמַדְבְּרָא:
@23 וְיֵיעוֹל אַהֲרֹן לְמַשְׁכַּן זִמְנָא וְיַשְׁלַח יָת לְבוּשֵׁי בוּצָא דִּי לְבַשׁ בְּמֵעֲלֵיהּ לְקוּדְשָׁא וְיַצְנְעִנּוּן תַּמָּן:
@24 וְיַסְחֵי יָת בִּסְרֵיהּ בְּמַיָּא בַּאֲתַר קַדִּישׁ וְיִלְבַּשׁ יָת לְבוּשׁוֹהִי וְיִפּוֹק וְיַעְבֵּד יָת עֲלָתֵיהּ וְיָת עֲלַת עַמָּא וִיכַפַּר עֲלוֹהִי וְעַל עַמָּא:
@25 וְיָת תַּרְבָּא דְחַטָּאתָא יַסֵּק לְמַדְבְּחָא:
@26 וּדְמוֹבִיל יָת צְפִירָא לַעֲזָאזֵל יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵיהּ בְּמַיָּא וּבָתַר כֵּן יֵיעוֹל לְמַשְׁרִיתָא:
@27 וְיָת תּוֹרָא דְחַטָּאתָא וְיָת צְפִירָא דְחַטָּאתָא דִּי אִתָּעַל מִדִּמְהוֹן לְכַפָּרָא בְקוּדְשָׁא יִתַּפְּקוּן לְמִבָּרָא לְמַשְׁרִיתָא וְיוֹקְדוּן בְּנוּרָא יָת מַשְׁכֵּיהוֹן וְיָת בִּסְרְהוֹן וְיָת אָכְלֵיהוֹן:
@28 וּדְמוֹקִיד יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵיהּ בְּמַיָּא וּבָתַר כֵּן יֵיעוֹל לְמַשְׁרִיתָא:
@29 וּתְהֵי לְכוֹן לִקְיַם עָלָם בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא תְּעַנּוּן יָת נַפְשָׁתֵיכוֹן וְכָל עִבִידָא לָא תַעְבְּדוּן יַצִּיבָא וְגִיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן:
@30 אֲרֵי בְיוֹמָא הָדֵין יְכַפֵּר עֲלֵיכוֹן לְדַכָּאָה יָתְכוֹן מִכֹּל חוֹבֵיכוֹן קֳדָם יְיָ תִּדְכּוּן:
@31 שְׁבַת שְׁבָתָא הִיא לְכוֹן וּתְעַנּוּן יָת נַפְשָׁתֵיכוֹן קְיַם עֲלָם:
@32 וִיכַפַּר כַּהֲנָא דִּי רַבִּי יָתֵיהּ וְדִי יְקָרֵב יָת קֻרְבָּנֵיהּ לְשַׁמָּשָׁא תְּחוֹת אֲבוּהִי וְיִלְבַּשׁ יָת לְבוּשֵׁי בוּצָא לְבוּשֵׁי קוּדְשָׁא:
@33 וִיכַפַּר עַל מִקְדַּשׁ קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא יְכַפַּר וְעַל כַּהֲנַיָּא וְעַל כָּל עַמָּא דִקְהָלָא יְכַפַּר:
@34 וּתְהֵי דָא לְכוֹן לִקְיַם עָלָם לְכַפָּרָא עַל בְּנֵי יִשְׂרָאֵל מִכָּל חוֹבֵיהוֹן חֲדָא בְּשַׁתָּא וַעֲבַד כְּמָא דִי פַקֵּיד יְיָ יָת משֶׁה:
@35 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@36 מַלֵּל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן דֵּין פִּתְגָּמָא דִּי פַקִּיד יְיָ לְמֵימָר:
@37 גְּבַר גְּבַר מִבֵּית יִשְׂרָאֵל דִּי יִכּוֹס תּוֹר אוֹ אִמַּר אוֹ עִזָּא בְּמַשְׁרִיתָא אוֹ דִּי יִכּוֹס מִבָּרָא לְמַשְׁרִיתָא:
@38 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתֵיהּ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ קֳדָם מַשְׁכְּנָא דַיְיָ דְּמָא יִתְחַשַּׁב לְגַבְרָא הַהוּא דְּמָא אֲשַׁד וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מִגּוֹ עַמֵּיהּ:
@39 בְּדִיל דִּי יַיְתוּן בְּנֵי יִשְׂרָאֵל יָת דִּבְחֵיהוֹן דִּי אִנּוּן דָּבְחִין עַל אַפֵּי חַקְלָא וְיַיְתֻנּוּן לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא לְוָת כַּהֲנָא וְיִכְּסוּן נִכְסַת קוּדְשִׁין קֳדָם יְיָ יָתְהוֹן:
@40 וְיִזְרוֹק כַּהֲנָא יָת דְּמָא עַל מַדְבְּחָא דַיְיָ בִּתְרַע מַשְׁכַּן זִמְנָא וְיַסֵּק תַּרְבָּא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@41 וְלָא יִדְבְּחוּן עוֹד יָת דִּבְחֵיהוֹן לַשֵּׁדִין דִּי אִנּוּן טָעָן בַּתְרֵיהוֹן קְיַם עָלָם תְּהֵי דָא לְהוֹן לְדָרֵיהוֹן:
@42 וּלְהוֹן תֵּימַר גְּבַר גְּבַר מִבֵּית יִשְׂרָאֵל וּמִן גִּיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן דִּי יַסֵּק עֲלָתָא אוֹ נִכְסַת קוּדְשַׁיָּא:
@43 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתִנֵּיהּ לְמֶעְבַּד יָתֵיהּ קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵּיהּ:
@44 וּגְבַר גְּבַר מִבֵּית יִשְׂרָאֵל וּמִן גִּיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן דִּי יֵיכוּל כָּל דְּמָא וְאֶתֵּן רוּגְזִי בַּאֲנָשָׁא דְּיֵכוּל יָת דְּמָא וֶאֱשֵׁיצֵי יָתֵיהּ מִגּוֹ עַמֵּיהּ:
@45 אֲרֵי נְפַשׁ בִּסְרָא בִּדְמָא הִיא וַאֲנָא יְהָבִתֵּיהּ לְכוֹן עַל מַדְבְּחָא לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן אֲרֵי דְמָא הוּא עַל נַפְשָׁא מְכַפֵּר:
@46 עַל כֵּן אֲמָרִית לִבְנֵי יִשְׂרָאֵל כָּל אֱנַשׁ מִנְּכוֹן לָא יֵיכוּל דְּמָא וְגִיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן לָא יֵיכוּל דְּמָא:
@47 וּגְבַר גְּבַר מִן בְּנֵי יִשְׂרָאֵל וּמִין גִּיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן דִּי יְצוּד צֵידָא חַיְתָא אוֹ עוֹפָא דִּי מִתְאֲכֵל וְיֵישׁוֹד יָת דְּמֵיהּ וִיכַסִּנֵּיהּ בְּעַפְרָא:
@48 אֲרֵי נְפַשׁ כָּל בִּסְרָא דְּמֵיהּ בְּנַפְשֵׁיהּ הוּא וַאֲמָרִית לִבְנֵי יִשְׂרָאֵל דַּם כָּל בִּסְרָא לָא תֵיכְלוּן אֲרֵי נְפַשׁ כָּל בִּסְרָא דְּמֵיהּ הִיא כָּל דְּיֵכְלִנֵּיהּ יִשְׁתֵּיצֵי:
@49 וְכָל אֱנַשׁ דִּי יֵיכוּל נְבִילָא וּתְבִירָא בְּיַצִּיבָא וּבְגִיּוֹרָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@50 וְאִם לָא יְצַבַּע וּבִסְרֵיהּ לָא יַסְחֵי וִיקַבֵּל חוֹבֵיהּ:
@51 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@52 מַלֵּל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@53 כְּעוֹבָדֵי עַמָּא דְאַרְעָא דְמִצְרַיִם דִּי יְתֶבְתּוּן בַּהּ לָא תַעְבְּדוּן וּכְעוֹבָדֵי עַמָּא דְאַרְעָא דִכְנַעַן דִּי אֲנָא מָעֵל יָתְכוֹן תַּמָּן לָא תַעְבְּדוּן וּבְנִימוֹסֵיהוֹן לָא תְהָכוּן:
@54 יָת דִּינַי תַּעְבְּדוּן וְיָת קְיָמַי תִּטְּרוּן לְהַלָּכָא בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@55 וְתִטְּרוּן יָת קְיָמַי וְיָת דִּינַי דִּי יַעְבֵּד יָתְהוֹן אֲנָשָׁא וְיֵחֵי בְהוֹן לְחַיֵּי עָלְמָא אֲנָא יְיָ:
@56 גְּבַר גְּבַר לְכָל קָרִיב בִּסְרֵיהּ לָא תִקְרְבוּן לְגַלָּאָה עֶרְיָא אֲנָא יְיָ:
@57 עֶרְיַת אֲבוּךְ וְעֶרְיַת אִמָּךְ לָא תְגַלֵּי אִמָּךְ הִיא לָא תְגַלֵּי עֶרְיְתַהּ:
@58 עֶרְיַת אִתַּת אָבוּךְ לָא תְגַלֵּי עֶרְיַת אֲבוּךְ הִיא:
@59 עֶרְיַת אֲחָתָךְ בַּת אֲבוּךְ אוֹ בַת אִמָּךְ דִּילִידָא מִן אֲבוּךְ מִן אִתַּת אָחֳרִי אוֹ מִן אִמָּךְ לִגְבַר אָחֳרָן לָא תְגַלֵּי עֶרְיַתְהֶן:
@60 עֶרְיַת בַּת בְּרָךְ אוֹ בַת בְּרַתָּךְ לָא תְגַלֵּי עֶרְיַתְהֵן אֲרֵי עֶרְיְתָךְ אִנּוּן:
@61 עֶרְיַת בַּת אִתַּת אֲבוּךְ דִּילִידָא מִן אֲבוּךְ אֲחָתָךְ הִיא לָא תְגַלֵּי עֶרְיְתַהּ:
@62 עֶרְיַת אֲחַת אֲבוּךְ לָא תְגַלֵּי קָרִיבַת אֲבוּךְ הִיא:
@63 עֶרְיַת אֲחַת אִמָּךְ לָא תְגַלֵּי אֲרֵי קָרִיבַת אִמָּךְ הִיא:
@64 עֶרְיַת אַח אֲבוּךְ לָא תְגַלֵּי לְאִתְּתֵיהּ לָא תִקְרַב אִתַּת אַח אֲבוּךְ הִיא:
@65 עֶרְיַת כַּלְּתָךְ לָא תְגַלֵּי אִתַּת בְּרָךְ הִיא לָא תְגַלֵּי עֶרְיְתַהּ:
@66 עֶרְיַת אִתַּת אֲחוּךְ לָא תְגַלֵּי עֶרְיַת אֲחוּךְ הִיא:
@67 עֶרְיַת אִתְּתָא וּבְרַתַּהּ לָא תְגַלֵּי יָת בַּת בְּרַהּ וְיָת בַּת בְּרַתַּהּ לָא תִסַּב לְגַלָּאָה עֶרְיְתַהּ קָרִיבָן אִנּוּן עֵצַת חִטְאִין הִיא:
@68 וְאִתְּתָא עִם אֲחָתַהּ לָא תִסָּב לְעָקָאָה לְגַלָּאָה עֶרְיְתַהּ עֲלַהּ בְּחַיָּיהָא:
@69 וּלְאִתְּתָא בְּרִחוּק סוֹבְתַהּ לָא תִקְרַב לְגַלָּאָה עֶרְיְתַהּ:
@70 וּבְאִתַּת חַבְרָךְ לָא תִתֵּן שְׁכֻבְתָּךְ לְזַרְעָא לְאִסְתָּאָבָא בַהּ:
@71 וּמִבְּנָיךְ לָא תִתֵּן לְאַעְבָּרָא לְמוֹלֶךְ וְלָא תַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@72 וְעִם דְּכוּרָא לָא תִשְׁכּוּב מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא הִיא:
@73 וּבְכָל בְּעִירָא לָא תִתֵּן שְׁכֻבְתָּךְ לְאִסְתָּאָבָא בַהּ וְאִתְּתָא לָא תְקוּם קֳדָם בְּעִירָא לְמִשְׁלַט בַּהּ תִּבְלָא הוּא:
@74 לָא תִסְתַּאֲבוּן בְּכָל אִלֵּין אֲרֵי בְכָל אִלֵּין אִסְתָּאָבוּ עַמְמַיָּא דִּי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן:
@75 וְאִסְתָּאָבַת אַרְעָא וְאַסְעָרִית חוֹבַהּ עֲלַהּ וְרוֹקֵינַת אַרְעָא יָת יָתְבָהָא:
@76 וְתִטְּרוּן אַתּוּן יָת קְיָמַי וְיָת דִּינַי וְלָא תַעְבְּדוּן מִכֹּל תּוֹעֶבְתָּא הָאִלֵּין יַצִּיבָא וְגִיּוֹרָא דְּיִתְגַּיְּרוּן בֵּינֵיכוֹן:
@77 אֲרֵי יָת כָּל תּוֹעֶבְתָּא הָאִלֵּין עֲבָדוּ אֱנָשֵׁי אַרְעָא דִּי קֳדָמֵיכוֹן וְאִסְתָּאָבַת אַרְעָא:
@78 וְלָא תְרוֹקֵן אַרְעָא יָתְכוֹן בְּסָאֳבֵיכוֹן יָתַהּ כְּמָא דְרוֹקֵינַת יָת עַמְמַיָּא דִּי קֳדָמֵיכוֹן:
@79 אֲרֵי כָּל דִּי יַעְבֵּד מִכֹּל תּוֹעֶבְתָּא הָאִלֵּין וְיִשְׁתֵּיצוּן נַפְשָׁתָא דִיַעְבְּדוּן מִגּוֹ עַמְּהוֹן:
@80 וְתִטְּרוּן יָת מַטְּרַת מֵימְרִי בְּדִיל דְּלָא לְמֶעְבַּד מִנִּימוֹסֵי תוֹעֶבְתָּא דְּאִתְעֲבָדָא קֳדָמֵיכוֹן וְלָא תִסְתַּאֲבוּן בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:

@1 **וידבר ה' אל משה אחרי מות שני בני אהרן וגו'.** מַה תַּ"ל? הָיָה רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה מוֹשְׁלוֹ מָשָׁל לְחוֹלֶה שֶׁנִּכְנָס אֶצְלוֹ רוֹפֵא, אָמַר לוֹ אַל תֹּאכַל צוֹנֵן וְאַל תִּשְׁכַּב בְּטַחַב; בָּא אַחֵר וְאָמַר לוֹ אַל תֹּאכַל צוֹנֵן וְאַל תִּשְׁכַּב בְּטַחַב שֶׁלֹּא תָמוּת כְּדֶרֶךְ שֶׁמֵּת פְּלוֹנִי, זֶה זֵרְזוֹ יוֹתֵר מִן הָרִאשׁוֹן, לְכָךְ נֶאֱמַר אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן:
@2 **ויאמר ה' אל משה דבר אל אהרן אחיך ואל יבא.** שֶׁלֹּא יָמוּת כְּדֶרֶךְ שֶׁמֵּתוּ בָנָיו:
@2 **ולא ימות.** שֶׁאִם בָּא הוּא מֵת (ספרא):
@2 **כי בענן אראה.** כִּי תָמִיד אֲנִי נִרְאֶה שָׁם עִם עַמּוּד עֲנָנִי, וּלְפִי שֶׁגִּלּוּי שְׁכִינָתִי שָׁם, יִזָּהֵר שֶׁלֹּא יַרְגִּיל לָבֹא, זֶהוּ פְשׁוּטוֹ; וּמִדְרָשׁוֹ: לֹא יָבֹא כִּי אִם בַּעֲנַן הַקְּטֹרֶת בְּיוֹם הַכִּפּוּרִים (יומא נ"ג):
@3 **בזאת.** גִּימַטְרִיָּא שֶׁלּוֹ אַרְבַּע מֵאוֹת וְעֶשֶׂר, רֶמֶז לְבַיִת רִאשׁוֹן (ויקרא רבה כ"א):
@3 **בזאת יבא אהרן וגומר.** וְאַף זוֹ לֹא בְכָל עֵת, כִּי אִם בְּיוֹם הַכִּפּוּרִים, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסוֹף הַפָּרָשָׁה "בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ" (שם):
@4 **כתנת בד וגו'.** מַגִּיד שֶׁאֵינוֹ מְשַׁמֵּשׁ לִפְנִים בִּשְׁמוֹנָה בְגָדִים שֶׁהוּא מְשַׁמֵּשׁ בָּהֶן בַּחוּץ, שֶׁיֵּשׁ בָּהֶם זָהָב, לְפִי שֶׁאֵין קָטֵגוֹר נַעֲשֶׂה סָנֵגוֹר, אֶלָּא בְּאַרְבָּעָה כְּכֹהֵן הֶדְיוֹט — וְכֻלָּן שֶׁל בּוּץ (ראש השנה כ"ו):
@4 **קדש ילבש.** שֶׁיִּהְיוּ מִשֶּׁל הֶקְדֵּשׁ (ספרא):
@4 **יצנף.** כְּתַרְגּוּמוֹ, יָחֵת בְּרֵישֵׁיהּ — יַנִּיחַ בְּרֹאשׁוֹ, כְּמוֹ וַתַּנַּח בִּגְדוֹ (בראשית ל"ט) — וַאֲחִתְּתֵהּ:
@4 **ורחץ במים.** אוֹתוֹ הַיּוֹם טָעוּן טְבִילָה בְּכָל חֲלִיפוֹתָיו; וְחָמֵשׁ פְּעָמִים הָיָה מַחֲלִיף מֵעֲבוֹדַת פְּנִים לַעֲבוֹדַת חוּץ, וּמִחוּץ לִפְנִים, וּמְשַׁנֶּה מִבִּגְדֵי זָהָב לְבִגְדֵי לָבָן וּמִבִּגְדֵי לָבָן לְבִגְדֵי זָהָב, וּבְכָל חֲלִיפָה טָעוּן טְבִילָה וּשְׁנֵי קִדּוּשֵׁי יָדַיִם וְרַגְלַיִם מִן הַכִּיּוֹר (יומא ל"א):
@6 **את פר החטאת אשר לו.** הָאָמוּר לְמַעְלָה, וְלִמֶּדְךָ כָּאן שֶׁמִּשֶּׁלּוֹ הוּא בָא וְלֹא מִשֶּׁל צִבּוּר (שם ג'):
@6 **וכפר בעדו ובעד ביתו.** מִתְוַדֶּה עָלָיו עֲוֹנוֹתָיו וַעֲוֹנוֹת בֵּיתוֹ (שם ל"ו):
@8 **ונתן אהרן על שני השעירם גרלות.** מַעֲמִיד אֶחָד לְיָמִין וְאֶחָד לִשְׂמֹאל, וְנוֹתֵן שְׁתֵּי יָדָיו בַּקַּלְפִּי, וְנוֹטֵל גּוֹרָל בְּיָמִין וַחֲבֵרוֹ בִּשְׂמֹאל וְנוֹתֵן עֲלֵיהֶם, אֶת שֶׁכָּתוּב בּוֹ "לַשֵּׁם" הוּא לַשֵּׁם, וְאֶת שֶׁכָּתוּב בּוֹ "לַעֲזָאזֵל" מִשְׁתַּלֵּחַ לַעֲזָאזֵל (יומא ל"ט):
@8 **עזאזל.** הוּא הַר עַז וְקָשֶׁה, צוּק גָּבוֹהַּ, שֶׁנֶּאֱמַר אֶרֶץ גְזֵרָה — חֲתוּכָה:
@9 **ועשהו חטאת.** כְּשֶׁמַּנִיחַ הַגּוֹרָל עָלָיו קוֹרֵא לוֹ שֵׁם וְאוֹמֵר "לַה' חַטָּאת":
@10 **יעמד חי.** כְּמוֹ יֻעֲמַד חַי — עַל יְדֵי אֲחֵרִים, וְתַרְגּוּמוֹ יִתָּקַם כַּד חַי; מַה תַּ"ל? לְפִי שֶׁנֶּאֱמַר לְשַׁלֵּחַ אֹתוֹ לַעֲזָאזֵל וְאֵינִי יוֹדֵעַ שִׁלּוּחוֹ אִם לְמִיתָה אִם לְחַיִּים, לְכָךְ נֶאֱמַר יָעֳמַד חַי, עֲמִידָתוֹ חַי עַד שֶׁיִּשְׁתַּלֵּחַ, מִכָּאן שֶׁשִּׁלּוּחוֹ לְמִיתָה (ספרא):
@10 **לכפר עליו.** שֶׁיִּתְוַדֶּה עָלָיו, כְּדִכְתִיב "וְהִתְוַדָּה עָלָיו" וְגוֹ':
@11 **וכפר בעדו וגו'.** וִדּוּי שֵׁנִי, עָלָיו וְעַל אֶחָיו הַכֹּהֲנִים, שֶׁהֵם כֻּלָּם קְרוּיִים בֵּיתוֹ, שֶׁנֶּאֱמַר "בֵּית אַהֲרֹן בָּרֲכוּ אֶת ה'" וְגוֹ' (תהילים קל"ה), מִכָּאן שֶׁהַכֹּהֲנִים מִתְכַּפְּרִין בּוֹ, וְכָל כַּפָּרָתָן אֵינָהּ אֶלָּא עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו, כְּמוֹ שֶׁנֶּאֱמַר (פסוק ט"ז), "וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאֹת" וְגוֹ' (ספרא; שבועות ז'):
@12 **מעל המזבח.** הַחִיצוֹן:
@12 **מלפני ה'.** מִצַּד שֶׁלִּפְנֵי הַפֶּתַח, וְהוּא צַד מַעֲרָבִי:
@12 **דקה.** מַה תַּ"ל דַּקָּה? וַהֲלֹא כָל הַקְּטֹרֶת דַּקָּה הִיא, שֶׁנֶּאֱמַר וְשָׁחַקְתָּ מִמֶּנָּה הָדֵק (שמות ל"ו), אֶלָּא שֶׁתְּהֵא דַּקָּה מִן הַדַּקָּה, שֶׁבְּעֶרֶב יֹהַ"כִּ הָיָה מַחֲזִירָהּ לַמַּכְתֶּשֶׁת (כריתות ו'):
@13 **על האש.** שֶׁבְּתוֹךְ הַמַּחְתָּה:
@13 **ולא ימות.** הָא אִם לֹא עֲשָֹאָהּ כְּתִקְנָהּ חַיָּב מִיתָה (ספרא):
@14 **והזה באצבעו.** הַזָּאָה אַחַת בְּמַשְׁמָע:
@14 **ולפני הכפרת יזה שבע.** הֲרֵי אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה (שם):
@15 **אשר לעם.** מַה שֶּׁהַפָּר מְכַפֵּר עַל הַכֹּהֲנִים מְכַפֵּר הַשָּׂעִיר עַל יִשְׂרָאֵל, וְהוּא הַשָּׂעִיר שֶׁעָלָה עָלָיו הַגּוֹרָל לַשֵּׁם (שבועות ב'):
@15 **כאשר עשה לדם הפר.** אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה:
@16 **מטמאת בני ישראל.** עַל הַנִּכְנָסִין לַמִּקְדָּשׁ בְּטֻמְאָה וְלֹא נוֹדַע לָהֶם בַּסּוֹף, שֶׁנֶּאֱמַר **לכל חטאתם** , וְחַטָּאת הִיא שׁוֹגֵג.
@16 **ומפשעיהם.** אַף הַנִּכְנָסִין מֵזִיד בְּטֻמְאָה (שם ז'):
@16 **וכן יעשה לאהל מועד.** כְּשֵׁם שֶׁהִזָּה מִשְּׁנֵיהֶם בִּפְנִים אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה, כָּךְ מַזֶּה עַל הַפָּרֹכֶת מִבַּחוּץ מִשְּׁנֵיהֶם אַחַת לְמַעְלָה וְשֶׁבַע לְמַטָּה (ספרא; יומא נ"ו):
@16 **השכן אתם בתוך טמאתם.** אַעַ"פִּי שֶׁהֵם טְמֵאִים שְׁכִינָה בֵינֵיהֶם (שם):
@18 **אל המזבח אשר לפני ה'.** זֶה מִזְבַּח הַזָּהָב שֶׁהוּא לִפְנֵי ה' — בַּהֵיכָל, וּמַה תַּ"ל וְיָצָא? לְפִי שֶׁהִזָּה הַהַזָּאוֹת עַל הַפָּרֹכֶת וְעָמַד מִן הַמִּזְבֵּחַ וְלִפְנִים וְהִזָּה, וּבְמַתְּנוֹת הַמִּזְבֵּחַ הִזְקִיקוֹ לָצֵאת מִן הַמִּזְבֵּחַ וְלַחוּץ וְיַתְחִיל מִקֶּרֶן מִזְרָחִית צְפוֹנִית (יומא נ"ח):
@18 **וכפר עליו.** מַה הִיא כַפָּרָתוֹ? **ולקח מדם הפר ומדם השעיר** מְעֹרָבִין זֶה לְתוֹךְ זֶה (שם נ"ז):
@19 **והזה עליו מן הדם.** אַחַר שֶׁנָּתַן מַתָּנוֹת בְּאֶצְבָּעוֹ עַל קַרְנוֹתָיו מַזֶּה שֶׁבַע הַזָּאוֹת עַל גַּגּוֹ:
@19 **וטהרו.** מִמַּה שֶּׁעָבָר:
@19 **וקדשו.** לֶעָתִיד לָבֹא (ספרא):
@21 **איש עתי.** הַמּוּכָן לְכָךְ מִיּוֹם אֶתְמוֹל:
@23 **ובא אהרן אל אהל מועד.** אָמְרוּ רַבּוֹתֵינוּ שֶׁאֵין זֶה מְקוֹמוֹ שֶׁל מִקְרָא זֶה וְנָתְנוּ טַעַם לְדִבְרֵיהֶם בְּמַסֶּכֶת יוֹמָא (דף ל"ב), וְאָמְרוּ: כָּל הַפָּרָשָׁה כֻּלָּהּ נֶאֶמְרָה עַל הַסֵּדֶר חוּץ מִבִּיאָה זוֹ שֶׁהִיא אַחַר עֲשִֹיַּת עוֹלָתוֹ וְעוֹלַת הָעָם, וְהַקְטָרַת אֵמוּרֵי פַּר וְשָֹעִיר, שֶׁנַּעֲשִֹים בַּחוּץ בְּבִגְדֵי זָהָב, וְטוֹבֵל וּמְקַדֵּשׁ וּפוֹשְׁטָן וְלוֹבֵשׁ בִּגְדֵי לָבָן, **ובא אל אהל מועד** לְהוֹצִיא אֶת הַכַּף וְאֶת הַמַּחְתָּה שֶׁהִקְטִיר בָּהּ הַקְּטֹרֶת לִפְנַי וְלִפְנִים:
@23 **ופשט את בגדי הבד.** אַחַר שֶׁהוֹצִיאָהּ, וְלוֹבֵשׁ בִּגְדֵי זָהָב לְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם; וְזֶהוּ סֵדֶר הָעֲבוֹדוֹת: תָּמִיד שֶׁל שַׁחַר בְּבִגְדֵי זָהָב, וַעֲבוֹדַת פַּר וְשָׂעִיר הַפְּנִימִיִּים וּקְטֹרֶת שֶׁל מַחְתָּה בְּבִגְדֵי לָבָן, וְאֵילוֹ וְאֵיל הָעָם וּמִקְצַת הַמּוּסָפִין בְּבִגְדֵי זָהָב, וְהוֹצָאַת כַּף וּמַחְתָּה בְּבִגְדֵי לָבָן, וּשְׁיָרֵי הַמּוּסָפִין וְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם וּקְטֹרֶת הַהֵיכָל שֶׁעַל מִזְבֵּחַ הַפְּנִימִי בְּבִגְדֵי זָהָב; וְסֵדֶר הַמִּקְרָאוֹת לְפִי הָעֲבוֹדוֹת כָּךְ הוּא: וְשִׁלַּח אֶת הַשָּׂעִיר בַּמִּדְבָּר, וְרָחַץ אֶת בְּשָׂרוֹ בַמַּיִם וְגוֹ', וְיָצָא וְעָשָׂה אֶת עֹלָתוֹ וְגוֹ', וְאֵת חֵלֶב הַחַטָּאת וְגוֹ', וְכָל הַפָּרָשָׁה עַד וְאַחֲרֵי כֵן יָבוֹא אֶל הַמַּחֲנֶה — וְאַחַר כָּךְ וּבָא אַהֲרֹן:
@23 **והניחם שם.** מְלַמֵּד שֶׁטְּעוּנִין גְּנִיזָה וְלֹא יִשְׁתַּמֵּשׁ בְּאוֹתָן ד' בְגָדִים לְיוֹם הַכִּפּוּרִים אַחֵר (יומא י"ב):
@24 **ורחץ את בשרו וגו'.** לְמַעְלָה לָמַדְנוּ מִ"וְרָחַץ אֶת בְּשָֹרוֹ וּלְבֵשָׁם" שֶׁכְּשֶׁהוּא מְשַׁנֶּה מִבִּגְדֵי זָהָב לְבִגְדֵי לָבָן טָעוּן טְבִילָה, — שֶׁבְּאוֹתָהּ טְבִילָה פָשַׁט בִּגְדֵי זָהָב שֶׁעָבַד בָּהֶן עֲבוֹדַת תָּמִיד שֶׁל שַׁחַר וְלוֹבֵשׁ בִּגְדֵי לָבָן לַעֲבוֹדַת הַיּוֹם, — וְכָאן לָמַדְנוּ שֶׁכְּשֶׁהוּא מְשַׁנֶּה מִבִּגְדֵי לָבָן לְבִגְדֵי זָהָב טָעוּן טְבִילָה (שם ל"ב):
@24 **במקום קדוש.** הַמְקֻדָּשׁ בִּקְדֻשַּׁת עֲזָרָה; וְהִיא הָיְתָה בְגַג בֵּית הַפַּרְוָה, וְכֵן אַרְבַּע טְבִילוֹת הַבָּאוֹת חוֹבָה לַיּוֹם, אֲבָל הָרִאשׁוֹנָה הָיְתָה בַחֹל (שם י"ט):
@24 **ולבש את בגדיו.** שְׁמוֹנָה בְגָדִים שֶׁהוּא עוֹבֵד בָּהֶן כָּל יְמוֹת הַשָּׁנָה:
@24 **ויצא.** מִן הַהֵיכָל אֶל הֶחָצֵר שֶׁמִּזְבַּח הָעוֹלָה שָׁם:
@24 **ועשה את עלתו.** אַיִל לְעוֹלָה הָאָמוּר לְמַעְלָה:
@24 **ואת עלת העם.** וְאַיִל אֶחָד לְעוֹלָה הָאָמוּר לְמַעְלָה "וּמֵאֵת עַדַת בְּנֵי יִשְֹרָאֵל" וְגוֹ':
@25 **ואת חלב החטאת.** אֵמוּרֵי פַּר וְשָׂעִיר:
@25 **יקטיר המזבחה.** עַל מִזְבֵּחַ הַחִיצוֹן, דְּאִלּוּ בַּפְּנִימִי כְתִיב לֹא תַעֲלוּ עָלָיו קְטֹרֶת זָרָה וְעֹלָה וּמִנְחָה (שמות ל'):
@27 **אשר הובא את דמם.** לַהֵיכָל וְלִפְנַי וְלִפְנִים:
@32 **וכפר הכהן אשר ימשח וגו'.** כַּפָּרָה זוֹ שֶׁל יוֹם הַכִּפּוּרִים אֵינָהּ כְּשֵׁרָה אֶלָּא בְּכֹהֵן גָּדוֹל (יומא ע"ג); לְפִי שֶׁנֶּאֶמְרָה כָל הַפָּרָשָׁה בְּאַהֲרֹן, הֻצְרַךְ לוֹמַר בְּכֹהֵן גָּדוֹל הַבָּא אַחֲרָיו שֶׁיְּהֵא כָמוֹהוּ:
@32 **ואשר ימלא את ידו.** אֵין לִי אֶלָּא הַמָּשׁוּחַ בְּשֶׁמֶן הַמִּשְׁחָה, מְרֻבֵּה בְגָדִים מִנַּיִן? תַּ"ל וַאֲשֶׁר יְמַלֵּא אֶת יָדוֹ וְגוֹמֵר; וְהֵם כָּל הַכֹּהֲנִים גְּדוֹלִים שֶׁעָמְדוּ מִיֹּאשִׁיָּהוּ וָאֵילָךְ, שֶׁבְּיָמָיו נִגְנְזָה צְלוֹחִית שֶׁל שֶׁמֶן הַמִּשְׁחָה (הוריות י"ב):
@32 **לכהן תחת אביו.** לְלַמֵּד שֶׁאִם בְּנוֹ מְמַלֵּא אֶת מְקוֹמוֹ, הוּא קוֹדֵם לְכָל אָדָם (ספרא):
@34 **ויעש כאשר צוה וגו'.** כְּשֶׁהִגִּיעַ יוֹם הַכִּפּוּרִים עָשָֹה כַּסֵּדֶר הַזֶּה; וּלְהַגִּיד שִׁבְחוֹ שֶׁל אַהֲרֹן, שֶׁלֹּא הָיָה לוֹבְשָׁן לִגְדֻלָּתוֹ אֶלָּא כִּמְקַיֵּם גְּזֵרַת הַמֶּלֶךְ (שם):
@37 **אשר ישחט שור או כשב.** בַּמֻּקְדָּשִׁין הַכָּתוּב מְדַבֵּר, שֶׁנֶּאֱמַר "לְהַקְרִיב קָרְבָּן" (זבחים ק"ז):
@37 **במחנה.** חוּץ לָעֲזָרָה:
@38 **דם יחשב.** כְּשׁוֹפֵךְ דַּם הָאָדָם שֶׁמִּתְחַיֵּב בְּנַפְשׁוֹ:
@38 **דם שפך.** לְרַבּוֹת אֶת הַזּוֹרֵק דָּמִים בַּחוּץ (שם):
@39 **אשר הם זבחים.** אֲשֶׁר הֵם רְגִילִים לִזְבֹּחַ:
@41 **לשעירם.** לַשֵּׁדִים, כְּמוֹ וּשְֹעִירִים יְרַקְּדוּ שָׁם (ישעיהו י"ג):
@42 **אשר יעלה עלה.** לְחַיֵּב עַל הַמַּקְטִיר אֵבָרִים בַּחוּץ כְּשׁוֹחֵט בַּחוּץ, שֶׁאִם שָׁחַט אֶחָד וְהֶעֱלָה חֲבֵרוֹ שְׁנֵיהֶם חַיָּבִין (זבחים ק"ו):
@43 **ונכרת.** זַרְעוֹ נִכְרָת וְיָמָיו נִכְרָתִין:
@44 **כל דם.** לְפִי שֶׁנֶּאֱמַר "בַּנֶּפֶשׁ יְכַפֵּר", יָכוֹל לֹא יְהֵא חַיָּב אֶלָּא עַל דַּם הַמֻּקְדָּשִׁים, תַּ"ל "כָּל דָּם":
@44 **ונתתי פני.** פְּנַאי שֶׁלִּי — פּוֹנֶה אֲנִי מִכָּל עֲסָקַי וְעוֹסֵק בּוֹ (ספרא):
@45 **כי נפש הבשר.** שֶׁל כָּל בְּרִיָּה בַּדָּם הִיא תְלוּיָה, וּלְפִיכָךְ נְתַתִּיו (עַל הַמִּזְבֵּחַ) לְכַפֵּר עַל נֶפֶשׁ הָאָדָם — תָּבֹא נֶפֶשׁ וּתְכַפֵּר עַל הַנֶּפֶשׁ:
@46 **כל נפש מכם.** לְהַזְהִיר גְּדוֹלִים עַל הַקְּטַנִּים:
@47 **אשר יצוד.** אֵין לִי אֶלָּא צַיִד, אֲוָזִין וְתַרְנְגוֹלִין מִנַּיִן? תַּ"ל "צֵיד" מִכָּל מָקוֹם; אִם כֵּן לָמָּה נֶאֱמַר "אֲשֶׁר יָצוּד"? שֶׁלֹּא יֹאכַל בָּשָׂר אֶלָּא בַּהַזְמָנָה הַזֹּאת (חולין פ"ד):
@47 **אשר יאכל.** פְּרָט לִטְמֵאִים (שם פ"ה):
@48 **דמו בנפשו הוא.** דָּמוֹ הוּא לוֹ בִּמְקוֹם הַנֶּפֶשׁ, שֶׁהַנֶּפֶשׁ תְּלוּיָה בוֹ:
@48 **כי נפש כל בשר דמו הוא.** הַנֶּפֶשׁ הִיא הַדָּם. דָּם וּבָשָׂר לְשׁוֹן זָכָר, נֶפֶשׁ לְשׁוֹן נְקֵבָה:
@49 **אשר תאכל נבלה וטרפה.** בְּנִבְלַת עוֹף טָהוֹר דִּבֵּר הַכָּתוּב, שֶׁאֵין לָהּ טֻמְאָה אֶלָּא בְשָׁעָה שֶׁנִּבְלַעַת בְּבֵית הַבְּלִיעָה, וְלִמֶּדְךָ כָּאן שֶׁמְּטַמְּאָה בַאֲכִילָתָהּ (וְאֵינָהּ מְטַמְּאָה בְמַגָּע); וּטְרֵפָה הָאֲמוּרָה כָּאן לֹא נִכְתַּב אֶלָּא לִדְרֹשׁ, וְכֵן שָׁנִינוּ: יָכוֹל תְּהֵא נִבְלַת עוֹף טָמֵא מְטַמְּאָה בְּבֵית הַבְּלִיעָה, תַּ"ל טְרֵפָה — מִי שֶׁיֵּשׁ בְּמִינוֹ טְרֵפָה, יָצָא עוֹף טָמֵא שֶׁאֵין בְּמִינוֹ טְרֵפָה (ספרא; זבחים ע'):
@50 **ונשא עונו.** אִם יֹאכַל קֹדֶשׁ אוֹ יִכָּנֵס לַמִּקְדָּשׁ חַיָּב עַל טֻמְאָה זוֹ כְּכָל שְׁאָר טֻמְאוֹת (ספרא):
@50 **ובשרו לא ירחץ ונשא עונו.** עַל רְחִיצַת גּוּפוֹ עָנוּשׁ כָּרֵת וְעַל כִּבּוּס בְּגָדִים בְּמַלְקוּת (שם):
@52 **אני ה' אלהיכם.** אֲנִי הוּא שֶׁאָמַרְתִּי בְסִינַי אָנֹכִי ה' אֱלֹהֶיךָ וְקִבַּלְתֶּם עֲלֵיכֶם מַלְכוּתִי, מֵעַתָּה קַבְּלוּ גְזֵרוֹתָי; רַבִּי אוֹמֵר גָּלוּי וְיָדוּעַ לְפָנָיו שֶׁסּוֹפָן לִנָּתֵק בַּעֲרָיוֹת בִּימֵי עֶזְרָא, לְפִיכָךְ בָּא עֲלֵיהֶם בִּגְזֵרָה **אני ה' אלהיכם** — דְּעוּ מִי גוֹזֵר עֲלֵיכֶם, דַּיָּן לִפָּרַע וְנֶאֱמָן לְשַׁלֵּם שָׂכָר (עי' ספרא):
@53 **כמעשה ארץ מצרים.** מַגִּיד שֶׁמַּעֲשֵׂיהֶם שֶׁל מִצְרִיִּים וְשֶׁל כְּנַעֲנִיִּים מְקֻלְקָלִים מִכָּל הָאֻמּוֹת, וְאוֹתוֹ מָקוֹם שֶׁיָּשְׁבוּ בוֹ יִשְׂרָאֵל מְקֻלְקָל מִן הַכֹּל:
@53 **אשר אני מביא אתכם שמה.** מַגִּיד שֶׁאוֹתָן עֲמָמִין שֶׁכִּבְּשׁוּ יִשְֹרָאֵל מְקֻלְקָלִים מִכֻּלָּם (שם):
@53 **ובחקתיהם לא תלכו.** מַה הִנִּיחַ הַכָּתוּב שֶׁלֹּא אָמַר? אֶלָּא אֵלּוּ נִימוֹסוֹת שֶׁלָּהֶן — דְּבָרִים הַחֲקוּקִין לָהֶם — כְּגוֹן טַרְטִיָּאוֹת וְאִצְטַדִיָּאוֹת, רַבִּי מֵאִיר אוֹמֵר, אֵלּוּ דַּרְכֵי הָאֱמוֹרִי שֶׁמָּנוּ חֲכָמִים (שם):
@54 **את משפטי תעשו.** אֵלּוּ דְּבָרִים הָאֲמוּרִים בַּתּוֹרָה בְּמִשְׁפָּט, שֶׁאִלּוּ לֹא נֶאֶמְרוּ הָיוּ כְדַאי לְאָמְרָן:
@54 **ואת חקתי תשמרו.** דְּבָרִים שֶׁהֵן גְּזֵרַת הַמֶּלֶךְ, שֶׁיֵּצֶר הָרַע מֵשִׁיב עֲלֵיהֶם לָמָּה לָנוּ לְשָׁמְרָן? וְאֻמּוֹת הָעוֹלָם מְשִׁיבִין עֲלֵיהֶם, כְּגוֹן אֲכִילַת חֲזִיר וּלְבִישַׁת שַׁעַטְנֵז וְטָהֳרַת מֵי חַטָּאת, לְכָךְ נֶאֱמַר **אני ה'** , גָּזַרְתִּי עֲלֵיכֶם, אֵי אַתָּה רַשַּׁאי לִפָּטֵר (יומא ס"ז):
@54 **ללכת בהם.** אַל תִּפָּטֵר מִתּוֹכָם, שֶׁלֹּא תֹאמַר לָמַדְתִּי חָכְמַת יִשְׂרָאֵל אֵלֵךְ וְאֶלְמַד חָכְמַת הָאֻמּוֹת (ספרא):
@55 **ושמרתם את חקתי וגו'.** לְרַבּוֹת שְׁאָר דִּקְדּוּקֵי הַפָּרָשָׁה, שֶׁלֹּא פֵּרֵט הַכָּתוּב בָּהֶם; דָּבָר אַחֵר לִתֵּן שְׁמִירָה וַעֲשִׂיָּה לַחֻקִּים וּשְׁמִירָה וַעֲשִׂיָּה לַמִּשְׁפָּטִים, לְפִי שֶׁלֹּא נָתַן אֶלָּא עֲשִׂיָּה לַמִּשְׁפָּטִים וּשְׁמִירָה לַחֻקִּים (ספרא):
@55 **וחי בהם.** לָעוֹלָם הַבָּא, שֶׁאִם תֹּאמַר בָּעוֹלָם הַזֶּה וַהֲלֹא סוֹפוֹ הוּא מֵת (שם):
@55 **אני ה'.** נֶאֱמָן לְשַׁלֵּם שָׂכָר (שם):
@56 **לא תקרבו.** לְהַזְהִיר הַנְּקֵבָה כַּזָּכָר, לְכָךְ נֶאֱמַר לְשׁוֹן רַבִּים:
@56 **אני ה'.** נֶאֱמָן לְשַׁלֵּם שָׂכָר:
@57 **ערות אביך.** זוֹ אֵשֶׁת אָבִיךָ, אוֹ אֵינוֹ אֶלָּא כְמַשְׁמָעוֹ? נֶאֱמַר כָּאן עֶרְוַת אָבִיךָ וְנֶאֱמַר לְהַלָּן עֶרְוַת אָבִיו גִּלָּה, מַה לְּהַלָּן אֵשֶׁת אָבִיו אַף כָּאן אֵשֶׁת אָבִיו (סנהדרין נ"ד):
@57 **וערות אמך.** לְהָבִיא אִמּוֹ שֶׁאֵינָהּ אֵשֶׁת אָבִיו (שם):
@58 **ערות אשת אביך.** לְרַבּוֹת אַחַר מִיתָה (שם):
@59 **בת אביך.** אַף בַּת אֲנוּסָה בְמַשְׁמָע:
@59 **מולדת בית או מולדת חוץ.** בֵּין שֶׁאוֹמְרִים לוֹ לְאָבִיךָ קַיֵּם אֶת אִמָּהּ, וּבֵין שֶׁאוֹמְרִים לוֹ הוֹצֵא אֶת אִמָּהּ, כְּגוֹן מַמְזֶרֶת אוֹ נְתִינָה (יבמות כ"ג):
@60 **ערות בת בנך וגו'.** בְּבִתּוֹ מֵאֲנוּסָתוֹ הַכָּתוּב מְדַבֵּר, וּבִתּוֹ וּבַת בִּתּוֹ מֵאִשְׁתּוֹ אָנוּ לְמֵדִין מֵ"עֶרְוַת אִשָּׁה וּבִתָּהּ", שֶׁנֶּאֱמַר בָּהֶן "לֹא תְגַלֵּה", בֵּין שֶׁהִיא מִמֶּנּוּ וּבֵין שֶׁהִיא מֵאִישׁ אַחֵר (שם כב):
@60 **ערות בת בנך.** קַל וָחֹמֶר לְבִתְּךָ, אֶלָּא לְפִי שֶׁאֵין מַזְהִירִין מִן הַדִּין, לְמָדוּהָ מִגְּזֵרָה שָׁוָה בְּמַסֶּכֶת יְבָמוֹת (דף ג'):
@61 **ערות בת אשת אביך.** לִמֵּד שֶׁאֵינוֹ חַיָּב עַל אֲחוֹתוֹ מִשִּׁפְחָה וְנָכְרִית, לְכָךְ נֶאֱמַר "בַּת אֵשֶׁת אָבִיךָ" — בִּרְאוּיָה לְקִדּוּשִׁין (שם כ"ג):
@64 **ערות אחי אביך לא תגלה.** וּמַה הִיא עֶרְוָתוֹ? **אל אשתו לא תקרב** :
@65 **אשת בנך.** לֹא אָמַרְתִּי אֶלָּא בְּשֶׁיֵּשׁ לְבִנְךָ אִישׁוּת בָּהּ, פְּרָט לַאֲנוּסָה וְשִׁפְחָה וְנָכְרִית (עי' ספרא):
@67 **ערות אשה ובתה.** לֹא אָסַר הַכָּתוּב אֶלָּא עַל יְדֵי נִשּׂוּאֵי הָרִאשׁוֹנָה, לְכָךְ נֶאֱמַר לֹא "תִקַּח" — לְשׁוֹן קִיחָה, וְכֵן לְעִנְיַן הָעֹנֶשׁ, אֲשֶׁר "יִקַּח" אֶת אִשָּׁה וְאֶת אִמָּה — לְשׁוֹן קִיחָה, אֲבָל אָנַס אִשָּׁה מֻתָּר לִשָּׂא בִּתָּהּ (יבמות צ"ז):
@67 **שארה הנה.** קְרוֹבוֹת זוֹ לָזוֹ:
@67 **זמה.** עֵצָה, כְּתַרְגּוּמוֹ עֲצַת חֶטְאִין, שֶׁיִּצְרְךָ יוֹעֶצְךָ לַחֲטֹא:
@68 **אל אחתה.** שְׁתֵּיהֶן כְּאַחַת (קידושין נ'):
@68 **לצרר.** לְשׁוֹן צָרָה — לַעֲשׂוֹת אֶת זוֹ צָרָה לָזוֹ:
@68 **בחייה.** לִמֶּדְךָ שֶׁאִם גֵרְשָׁהּ לֹא יִשָּׂא אֶת אֲחוֹתָהּ כָּל זְמַן שֶׁהִיא בַחַיִּים (יבמות ח'):
@71 **למלך.** עֲ"זָ הִיא שֶׁשְּׁמָהּ מֹלֶךְ, וְזוֹ הִיא עֲבוֹדָתָהּ, שֶׁמּוֹסֵר בְּנוֹ לַכּוֹמְרִים וְעוֹשִׂין שְׁתֵּי מְדוּרוֹת גְּדוֹלוֹת וּמַעֲבִירִין אֶת הַבֵּן בְּרַגְלָיו בֵּין שְׁתֵּי מְדוּרוֹת הָאֵשׁ (סנהדרין ס"ד):
@71 **לא תתן.** זוֹ הִיא מְסִירָתוֹ לַכּוֹמְרִים:
@71 **להעביר למלך.** זוֹ הַעֲבָרַת הָאֵשׁ:
@73 **תבל הוא.** לְשׁוֹן קָדֵשׁ וְעֶרְוָה וְנִאוּף, וְכֵן וְאַפִּי עַל תַּבְלִיתָם (ישעיהו י'); דָּבָר אַחֵר תֶּבֶל הוּא לְשׁוֹן בְּלִילָה וְעִרְבּוּב זֶרַע אָדָם וְזֶרַע בְּהֵמָה:
@78 **ולא תקיא הארץ אתכם.** מָשָׁל לְבֶן מֶלֶךְ שֶׁהֶאֱכִילוּהוּ דָּבָר מָאוּס, שֶׁאֵין עוֹמֵד בְּמֵעָיו אֶלָּא מְקִיאוֹ, כָּךְ אֶרֶץ יִשְׂרָאֵל אֵינָהּ מְקַיֶּמֶת עוֹבְרֵי עֲבֵרָה (ספרא סוף קדושים), וְתַרְגּוּמוֹ וְלָא תְרוֹקֵן, לְשׁוֹן רִקּוּן — מְרִיקָה עַצְמָהּ מֵהֶם:
@79 **הנפשות העשת.** הַזָּכָר וְהַנְּקֵבָה בְמַשְׁמָע (ספרא):
@80 **ושמרתם את משמרתי.** לְהַזְהִיר בֵּית דִּין עַל כָּךְ (שם):
@80 **ולא תטמאו בהם אני ה' אלהיכם.** הָא אִם תִּטַּמְּאוּ אֵינִי אֱלֹהֵיכֶם, וְאַתֶּם נִפְסָלִים מֵאַחֲרַי, וּמַה הֲנָאָה יֵשׁ לִי בָּכֶם וְאַתֶּם מִתְחַיְּבִים כְּלָיָה? לְכָךְ נֶאֱמַר אֲנִי ה' אֱלֹהֵיכֶם (שם):

@1 טַעַם **אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן** כִּי מִיָּד כַּאֲשֶׁר מֵתוּ בָּנָיו הִזְהִיר אֶת אַהֲרֹן מִן הַיַּיִן וּמִן הַשֵּׁכָר שֶׁלֹּא יָמוּת (לעיל י ח ט), וְאָמַר עוֹד לְמֹשֶׁה שֶׁיַּזְהִיר אוֹתוֹ שֶׁלֹּא יָמוּת בְּקָרְבָתוֹ לִפְנֵי ה'. וְהַקָּרוֹב שֶׁהָיוּ שְׁתֵּי הַמִּצְוֹת הָאֵלֶּה בְּיוֹם הַמָּחֳרָת לְמִיתָתָם, כִּי בּוֹ בַּיּוֹם אוֹנֵן הָיָה וְאֵין רוּחַ הַקֹּדֶשׁ שׁוֹרָה מִתּוֹךְ עַצְבוּת (שבת ל), וְאַזְהָרַת הַיַּיִן הַדִּבּוּר לְאַהֲרֹן הָיָה, וּבְאוֹתוֹ הַיּוֹם הָיְתָה גַּם זֹאת הַמִּצְוָה לְמֹשֶׁה, אֲבָל הִקְדִּים הַכָּתוּב הָאַזְהָרוֹת שֶׁהִזְהִיר אֶת יִשְׂרָאֵל שֶׁלֹּא יָמֻתוּ בְּטֻמְאָתָם בְּטַמְּאָם אֶת מִשְׁכָּנִי אֲשֶׁר בְּתוֹכָם (ויקרא ט"ו:ל"א) וְאַחֲרֵי כֵן כָּתַב אַזְהָרַת הַיָּחִיד. וְעַל דַּעְתִּי כָּל הַתּוֹרָה כַּסֵּדֶר, שֶׁכָּל הַמְּקוֹמוֹת אֲשֶׁר בָּהֶם יְאַחֵר הַמֻּקְדָּם יְפָרֵשׁ בּוֹ, כְּגוֹן "וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּהַר סִינַי" (ויקרא כ"ה:א') בַּסֵּפֶר הַזֶּה, וּכְגוֹן "וַיְהִי בְּיוֹם כַּלּוֹת מֹשֶׁה לְהָקִים אֶת הַמִּשְׁכָּן" (במדבר ז א) בַּסֵּפֶר הַשֵּׁנִי, וְכַיּוֹצֵא בָּהֶן. וּלְכָךְ אָמַר בְּכָאן "אַחֲרֵי מוֹת", לְהוֹדִיעַ כִּי הָיָה זֶה אַחֲרֵי מוֹתָם מִיָּד. וְעַל דִּבְרֵי רַבּוֹתֵינוּ (תו"כ פרשה א ג) שֶׁאָמְרוּ, שֶׁלֹּא תָּמוּת כְּדֶרֶךְ שֶׁמֵּת פְּלוֹנִי, זֶה זֵרְזוֹ יוֹתֵר מִן הָרִאשׁוֹן, יִהְיֶה טַעַם הַכָּתוּב שֶׁאָמַר הַשֵּׁם לְמֹשֶׁה בַּלָּשׁוֹן הַזֶּה אַחֲרֵי שֶׁמֵּתוּ שְׁנֵי בְּנֵי אַהֲרֹן בְּקָרְבָתָם לִפְנֵי ה', אֱמֹר אֵלָיו שֶׁלֹּא יָבֹא בְּכָל עֵת אֶל הַקֹּדֶשׁ וְלֹא יָמוּת:
@2 וְטַעַם **אָחִיךָ** שֶׁתַּזְהִירֶנּוּ כִּי אָחִיךָ הוּא, וְאע"פ שֶׁאַתָּה אֵינְךָ בְּבַל יָבֹא אַהֲרֹן אָחִיךָ בְּבַל יָבֹא. וְאָמַר ר"א (אבן עזרא על ויקרא ט"ז:א') שֶׁזֹּאת הַפָּרָשָׁה לְאוֹת כִּי בְּנֵי אַהֲרֹן הִכְנִיסוּ אֵשׁ הַקְּטֹרֶת לִפְנִים. וְאֵינוֹ כֵן עַל דַּעְתִּי, כִּי הַכָּתוּב שֶׁמַּזְכִּיר תָּמִיד הֶעָוֹן אוֹמֵר (במדבר ג ד) "בְּהַקְרִיבָם אֵשׁ זָרָה", וְאִם תִּהְיֶה רְאָיָה שֶׁנִּכְנְסוּ לִפְנִים בַּעֲבוּר הָאַזְהָרָה שֶׁהִזְהִיר לְמֹשֶׁה עַל אֲבִיהֶם שֶׁלֹּא יָמוּת, כָּל שֶׁכֵּן שֶׁתִּהְיֶה רְאָיָה שֶׁנִּכְנְסוּ שְׁתוּיֵי יַיִן בַּעֲבוּר הָאַזְהָרָה שֶׁנֶּאֶמְרָה לְאַהֲרֹן עַצְמוֹ מִיָּד. וְעוֹד כִּי אֵיךְ יַעֲלֶה עַל דַּעְתָּם לָבֹא הַיּוֹם אֶל הַמָּקוֹם אֲשֶׁר לֹא נִכְנַס שָׁם אֲבִיהֶם, כִּי אַהֲרֹן הִקְטִיר הַקְּטֹרֶת עַל הַמִּזְבֵּחַ הַפְּנִימִי, וְלָמָּה יַכְנִיסוּ הֵם הַקְּטֹרֶת שֶׁלָּהֶם לִפְנִים מִשֶּׁלּוֹ. וּכְבָר רָמַזְתִּי (רמב"ן על ויקרא י':ב') עַל חֶטְאָם, וּלְשׁוֹן הַכְּתוּבִים יוֹרֶה עָלָיו. אֲבָל מִלַּת "בְּקָרְבָתָם" כְּפִי הַפְּשָׁט כְּמוֹ "אוֹ בְּקָרְבָתָם אֶל הַמִּזְבֵּחַ לְשָׁרֵת" (שמות מ לב; ל, כ) יֹאמַר כִּי בְּשָׁרְתָם לִפְנֵי ה' מֵתוּ. אִם כֵּן יַזְהִיר אַהֲרֹן שֶׁלֹּא יְשָׁרֵת אֶלָּא בְּמָקוֹם אֲשֶׁר יְצֻוֶּה וּבְעֵת אֲשֶׁר יְצֻוֶּה. וְיִתָּכֵן שֶׁיִּהְיֶה טַעְמוֹ כְּטַעַם שֶׁאָמְרוּ רַבּוֹתֵינוּ (מכילתא בשלח ויסע ו) שֶׁהָיוּ מַלִּיזִין אַחֲרֵי הַקְּטֹרֶת, שֶׁעַל יָדוֹ מֵתוּ נָדָב וַאֲבִיהוּא וכו', וְיֹאמַר הַכָּתוּב כִּי אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן בְּקָרְבָתָם לִפְנֵי ה' בַּקְּטֹרֶת, אָמַר ה' לְאַהֲרֹן כִּי הוּא יִקְרַב יוֹתֵר מֵהֶם אֶל ה' בַּקְּטֹרֶת וְיָמוּת אִם יָבֹא אֶל הַקֹּדֶשׁ זוּלָתִי הַקְּטֹרֶת, כִּי בּוֹ יִכָּנֵס תְּחִלָּה, כְּמוֹ שֶׁאָמַר "וְהֵבִיא מִבֵּית לַפָּרֹכֶת" (ויקרא ט"ז:י"ב) "וְכִסָּה עֲנַן הַקְּטֹרֶת אֶת הַכַּפֹּרֶת אֲשֶׁר עַל הָעֵדוּת וְלֹא יָמוּת" (ויקרא ט"ז:י"ג). וְזֶה טַעַם "כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת", שֶׁלֹּא יִכָּנֵס רַק בַּקְּטֹרֶת שֶׁיַּעֲלֶה עֲנָנוֹ שָׁם, כְּמוֹ שֶׁאָמַר (ויקרא ט"ז:י"ב) "וְכִסָּה עֲנַן הַקְּטֹרֶת אֶת הַכַּפֹּרֶת":
@2 וְטַעַם **בְּכָל עֵת** בַּעֲבוּר שֶׁכְּבָר הִזְכִּיר יוֹם הַכִּפּוּרִים, שֶׁאָמַר (שמות ל י) "וְכִפֶּר אַהֲרֹן עַל קַרְנֹתָיו אַחַת בַּשָּׁנָה" אָמַר בְּכָאן לֹא יָבֹא בְּשׁוּם עֵת אֶל הַקֹּדֶשׁ רַק בְּזֹאת, כְּלוֹמַר בַּיּוֹם אֲשֶׁר יַקְרִיב הַקָּרְבָּנוֹת הָאֵלֶּה לְכִפּוּרִים, וְאַחֲרֵי כֵן יְפָרֵשׁ בַּפָּרָשָׁה בַּמֶּה יִכָּנֵס, כְּמוֹ שֶׁאָמַר (ויקרא ט"ז:י"ב) "וְהֵבִיא מִבֵּית לַפָּרֹכֶת", וִיפָרֵשׁ הַיּוֹם, שֶׁיִּהְיֶה בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי (ויקרא ט"ז:כ"ט), וְיַחְזֹר וְיֹאמַר כִּי יִהְיֶה אַחַת בַּשָּׁנָה (ויקרא ט"ז:ל"ד):
@3 וְסוֹד **בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ** כְּסוֹד "זֹאת אוֹת הַבְּרִית אֲשֶׁר הֲקִמֹתִי" (בראשית ט יז), וּכְבָר פֵּרַשְׁתִּיו (שמות לא יג). וְרַבּוֹתֵינוּ רָמְזוּ בּוֹ, אָמְרוּ בְּוַיִּקְרָא רַבָּה (כא ו), רַבִּי יוּדָן פָּתַר קְרָאֵי בְּכֹהֵן גָּדוֹל, בִּכְנִיסָתוֹ לְבֵית קָדְשֵׁי הַקֳּדָשִׁים חֲבִילוֹת חֲבִילוֹת שֶׁל מִצְוֹת בְּיָדוֹ, בִּזְכוּת הַתּוֹרָה - "וְזֹאת הַתּוֹרָה" (דברים ד מד), וּבִזְכוּת מִילָה - "זֹאת בְּרִיתִי אֲשֶׁר תִּשְׁמְרוּ" (בראשית יז י), בִּזְכוּת שַׁבָּת - "אַשְׁרֵי אֱנוֹשׁ יַעֲשֶׂה זֹּאת" (ישעיהו נו ב), בִּזְכוּת יְרוּשָׁלַיִם - "זֹאת יְרוּשָׁלַיִם" (יחזקאל ה ה), בִּזְכוּת שְׁבָטִים - "וְזֹאת אֲשֶׁר דִּבֶּר לָהֶם אֲבִיהֶם" (בראשית מט כח), בִּזְכוּת יְהוּדָה - "וְזֹאת לִיהוּדָה" (דברים לג ז), בִּזְכוּת כְּנֶסֶת יִשְׂרָאֵל - "זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר" (שיר השירים ז ח), בִּזְכוּת הַתְּרוּמָה - "וְזֹאת הַתְּרוּמָה" (שמות כה ג), בִּזְכוּת הַמַּעַשְׂרוֹת - "וּבְחָנוּנִי נָא בָּזֹאת" (מלאכי ג י), בִּזְכוּת הַקָּרְבָּנוֹת - "בְּזֹאת יָבֹא אַהֲרֹן". וְזֶה צָרִיךְ פֵּרוּשׁ אָרֹךְ, אֲבָל כְּבָר הַכֹּל מְבֹאָר בִּדְבָרֵינוּ:
@4 **כְּתֹנֶת בַּד קֹדֶשׁ יִלְבָּשׁ** שֶׁיִּהְיוּ מִשֶּׁל קוֹדֶשׁ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ט"ז:ד'). וְיֹאמַר "בִּגְדֵי קֹדֶשׁ הֵם", שֶׁיִּהְיוּ כֵן כֻּלָּם שֶׁל קוֹדֶשׁ. וּבְת"כ (פרק א י), "קֹדֶשׁ יִלְבָּשׁ" שֶׁיִּהְיוּ מִשֶּׁל קוֹדֶשׁ, אֵין לִי אֶלָּא אֵלּוּ בִּלְבַד, מִנַּיִן לְרַבּוֹת שְׁאָר בִּגְדֵי כְּהֻנָּה גְּדוֹלָה וּבִגְדֵי אֶחָיו הַכֹּהֲנִים, תַּלְמוּד לוֹמַר "בִּגְדֵי קוֹדֶשׁ הֵם", בִּנְיַן אָב לְכָל הַבְּגָדִים שֶׁיִּהְיוּ מִשֶּׁל קוֹדֶשׁ. וְעַל דֶּרֶךְ הַפְּשָׁט כַּאֲשֶׁר אָמַר (שמות כח ד) "וְעָשׂוּ בִגְדֵי קֹדֶשׁ לְאַהֲרֹן אָחִיךָ" בִּשְׁמוֹנָה הַבְּגָדִים, יֹאמַר שֶׁגַּם אֵלֶּה בִּגְדֵי קוֹדֶשׁ, וְסוֹדָם כְּמוֹ "הָאִישׁ לְבֻשׁ הַבַּדִּים" (יחזקאל ט ג דניאל י ה). וּלְכָךְ הוֹדִיעוֹ כִּי בִּגְדֵי קוֹדֶשׁ הֵם. וּבְוַיִּקְרָא רַבָּה (כא יא), כְּשֵׁרוּת שֶׁל מַעֲלָן כָּךְ שֵׁרוּת שֶׁל מַטָּן, מַה שֵׁרוּת שֶׁל מַעֲלָן אִישׁ אֶחָד בְּתוֹכָם לָבֻשׁ בַּדִּים, כָּךְ שֵׁרוּת שֶׁל מַטָּן "כְּתֹנֶת בַּד קֹדֶשׁ":
@4 **יִלְבָּשׁ יַחְגֹּר יִצְנֹף** נִדְרָשׁ בְּתוֹרַת כֹּהֲנִים (אחרי א יד), לְפִי שֶׁסּוֹפֵנוּ לְרַבּוֹת לוֹ כֵּלִים אֲחֵרִים בֵּין הָעַרְבַּיִם, אֵין לוֹ יָכוֹל לֹא יִלְבַּשׁ שֶׁל שַׁחֲרִית, תַּלְמוּד לוֹמַר "יִלְבָּשׁ יַחְגֹּר יִצְנֹף". וְכָתַב רַשִׁ"י (רש"י על ויקרא ט"ז:ד') זַ"ל, "יִצְנֹף" - "יַחֵת בְּרֵישֵׁהּ", יַנִּיחַ בְּרֹאשׁוֹ, כְּמוֹ "וַתַּנַּח בִּגְדוֹ אֶצְלָהּ" (בראשית לט טז) - "וְאַחֵתְתֵּהּ". וְלֹא נִתְבָּרֵר לִי דַּעַת אוּנְקְלוֹס (תרגום אונקלוס על ויקרא ט"ז:ד') בָּזֶה, כִּי הַצְּנִיפָה סִבּוּב שֶׁיְּגַלְגְּלֶנָּה בְּרֹאשׁוֹ כְּצָנִיף, וְלָמָּה יְתַרְגֵּם אוֹתָהּ בְּהַנָּחָה בִּלְבַד וְלֹא יְתַרְגֵּם בָּהּ הַלָּשׁוֹן שֶׁמְּיֻחָד לוֹ לִצְנִיפָה מַמָּשׁ. וְאוּלַי אֵינֶנּוּ בַּלָּשׁוֹן הָאֲרָמִית, כִּי גַּם "הַצְּנִיפוֹת וְהָרְדִידִים" שֶׁבִּישַׁעְיָה (ג כג), תִּרְגֵּם יוֹנָתָן בֶּן עֻזִּיאֵל "כִּתְרַיָּא", וְאֵין לִשְׁנֵיהֶם לָשׁוֹן בְּצָנִיף וּבְמִצְנֶפֶת, רַק לְשׁוֹן הַקֹּדֶשׁ "מַצְנַפְתָּא":
@8 **וְגוֹרָל אֶחָד לַעֲזָאזֵל** הַר גָּבוֹהַּ, צוּק קָשֶׁה, שֶׁנֶּאֱמַר (ויקרא ט"ז:כ"ב) "אֶרֶץ גְּזֵרָה", לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ט"ז:ח'). וּבְתוֹרַת כֹּהֲנִים (פרק ב ח), "לַעֲזָאזֵל" - לַמָּקוֹם הַקָּשֶׁה שֶׁבֶּהָרִים. יָכוֹל בַּיִּשּׁוּב, תַּלְמוּד לוֹמַר "הַמִּדְבָּרָה" (ויקרא ט"ז:כ"א). וּמִנַּיִן שֶׁיְּהֵא צוּק (שם פסוק כב), תַּלְמוּד לוֹמַר "אֶל אֶרֶץ גְּזֵרָה". וּלְפִי זֶה יִהְיֶה פֵּרוּשׁ מִלַּת "לַעֲזָאזֵל" - לַקָּשֶׁה, וְהוּא כָּפוּל הַזַּיִ"ן, כְּמוֹ "עִזּוּז וְגִבּוֹר" (תהלים כד ח). וְר"א כָּתַב, אָמַר רַב שְׁמוּאֵל, אע"פ שֶׁכָּתוּב בִּשְׂעִיר הַחַטָּאת שֶׁהוּא לַשֵּׁם, גַּם הַשָּׂעִיר הַמִּשְׁתַּלֵּחַ הוּא לַשֵּׁם. וְאֵין צֹרֶךְ, כִּי הַמִּשְׁתַּלֵּחַ אֵינֶנּוּ קָרְבָּן, שֶׁלֹּא יִשָּׁחֵט, וְאִם יָכֹלְתָּ לְהָבִין הַסּוֹד שֶׁהוּא אַחַר מִלַּת עֲזָאזֵל תֵּדַע סוֹדוֹ וְסוֹד שְׁמוֹ, כִּי יֵשׁ לוֹ חֲבֵרִים בַּמִּקְרָא, וַאֲנִי אֲגַלֶּה לְךָ קְצָת הַסּוֹד בְּרֶמֶז, בִּהְיוֹתְךָ בֶּן שְׁלֹשִׁים וְשָׁלֹשׁ (אחרי ל"ג פסוקים יז ז) תֵּדָעֶנּוּ. וְהִנֵּה ר"א נֶאֱמַן רוּחַ מְכַסֶּה דָבָר וַאֲנִי הָרָכִיל מְגַלֶּה סוֹדוֹ, שֶׁכְּבָר גִּלּוּ אוֹתוֹ רַבּוֹתֵינוּ זַ"ל בִּמְקוֹמוֹת רַבִּים. אָמְרוּ בִּבְרֵאשִׁית רַבָּה (בראשית רבה ס"ה:י'), "וְנָשָׂא הַשָּׂעִיר עָלָיו" (ויקרא ט"ז:כ"ב) זֶה עֵשָׂו, שֶׁנֶּאֱמַר (בראשית כז יא) "הֵן עֵשָׂו אָחִי אִישׁ שָׂעִר". "אֶת כָּל עֲוֹנֹתָם" עֲוֹנוֹת תָּם, שֶׁנֶּאֱמַר "וְיַעֲקֹב אִישׁ תָּם" (שם כה כז). וּמְפֹרָשׁ מִזֶּה בְּפִרְקֵי רַבִּי אֱלִיעֶזֶר הַגָּדוֹל (פרק מו), לְפִיכָךְ הָיוּ נוֹתְנִין לוֹ לְסַמָּאֵל שֹׁחַד בְּיוֹם הַכִּפּוּרִים שֶׁלֹּא לְבַטֵּל אֶת קָרְבָּנָם, שֶׁנֶּאֱמַר "גּוֹרָל אֶחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל", גּוֹרָלוֹ שֶׁל הקב"ה לְקָרְבַּן עוֹלֶה, וְגוֹרָלוֹ שֶׁל עֲזָאזֵל שְׂעִיר הַחַטָּאת, וְכָל עֲוֹנוֹתֵיהֶם שֶׁל יִשְׂרָאֵל עָלָיו, שֶׁנֶּאֱמַר "וְנָשָׂא הַשָּׂעִיר עָלָיו". רָאָה סַמָּאֵל שֶׁלֹּא נִמְצָא בָּהֶם חֵטְא בְּיוֹם הַכִּפּוּרִים, אָמַר לִפְנֵי הקב"ה, רִבּוֹן כָּל הָעוֹלָמִים יֵשׁ לְךָ עַם אֶחָד בָּאָרֶץ כְּמַלְאֲכֵי הַשָּׁרֵת שֶׁבַּשָּׁמַיִם, מָה מַלְאֲכֵי הַשָּׁרֵת יְחֵפֵי רֶגֶל כָּךְ הֵן יִשְׂרָאֵל יְחֵפֵי רֶגֶל בְּיוֹם הַכִּפּוּרִים, מָה מַלְאֲכֵי הַשָּׁרֵת אֵין בָּהֶם אֲכִילָה וּשְׁתִיָּה כָּךְ יִשְׂרָאֵל אֵין בָּהֶם אֲכִילָה וּשְׁתִיָּה בְּיוֹם הַכִּפּוּרִים, מָה מַלְאֲכֵי הַשָּׁרֵת אֵין לָהֶם קְפִיצָה כָּךְ יִשְׂרָאֵל עוֹמְדִין עַל רַגְלֵיהֶם בְּיוֹם הַכִּפּוּרִים, מָה מַלְאֲכֵי הַשָּׁרֵת שָׁלוֹם מְתַוֵּךְ בֵּינֵיהֶם כָּךְ הֵן יִשְׂרָאֵל שָׁלוֹם מְתַוֵּךְ בֵּינֵיהֶם בְּיוֹם הַכִּפּוּרִים, מָה מַלְאֲכֵי הַשָּׁרֵת נְקִיִּים מִכָּל חֵטְא כָּךְ הֵן יִשְׂרָאֵל נְקִיִּים מִכָּל חֵטְא בְּיוֹם הַכִּפּוּרִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ עֵדוּתָן שֶׁל יִשְׂרָאֵל מִן הַקָּטֵגוֹר שֶׁלָּהֶם וּמְכַפֵּר עַל הַמִּזְבֵּחַ וְעַל הַמִּקְדָּשׁ וְעַל הַכֹּהֲנִים וְעַל כָּל עַם הַקָּהָל, שֶׁנֶּאֱמַר (ויקרא ט"ז:ל"ג) "וְכִפֶּר אֶת מִקְדַּשׁ הַקֹּדֶשׁ" וְגוֹ', ע"כ אַגָּדָה זוֹ. וְהִנֵּה הוֹדִיעָנוּ שְׁמוֹ וּמַעֲשֵׂהוּ, וְזֶה סוֹד הָעִנְיָן, כִּי הָיוּ עוֹבְדִים לֵאלֹהִים אֲחֵרִים, הֵם הַמַּלְאָכִים עוֹשִׂים לָהֶם קָרְבָּנוֹת וְהֵם לָהֶם לְרֵיחַ נִיחוֹחַ, כְּעִנְיָן שֶׁנֶּאֱמַר (יחזקאל טז יח יט) "וְשַׁמְנִי וּקְטָרְתִּי נָתַתְּ לִפְנֵיהֶם וְלַחְמִי אֲשֶׁר נָתַתִּי לָךְ סֹלֶת וָשֶׁמֶן וּדְבַשׁ הֶאֱכַלְתִּיךְ וּנְתַתִּיהוּ לִפְנֵיהֶם לְרֵיחַ נִיחֹחַ וַיֶּהִי נְאֻם ה' אֱלֹהִים". וְאַתָּה צָרִיךְ לְהִתְבּוֹנֵן בַּכָּתוּב בַּמִּקְרָא וּבַמָּסֹרֶת. וְהִנֵּה הַתּוֹרָה אָסְרָה לְגַמְרֵי קַבָּלַת אֱלֹהוּתָם וְכָל עֲבוֹדָה לָהֶם, אֲבָל צִוָּה הקב"ה בְּיוֹם הַכִּפּוּרִים שֶׁנִּשְׁלַח שָׂעִיר בַּמִּדְבָּר לַשַּׂר הַמּוֹשֵׁל בִּמְקוֹמוֹת הַחֻרְבָּן, וְהוּא הָרָאוּי לוֹ מִפְּנֵי שֶׁהוּא בְּעָלָיו, וּמֵאֲצִילוּת כֹּחוֹ יָבֹא חֹרֶב וְשִׁמָּמוֹן, כִּי הוּא הָעִלָּה לְכוֹכְבֵי הַחֶרֶב וְהַדָּמִים וְהַמִּלְחָמוֹת וְהַמְּרִיבוֹת וְהַפְּצָעִים וְהַמַּכּוֹת וְהַפֵּרוּד וְהַחֻרְבָּן, וְהַכְּלָל נֶפֶשׁ לְגַלְגַּל מַאְדִּים, וְחֶלְקוֹ מִן הָאֻמּוֹת הוּא עֵשָׂו, שֶׁהוּא עַם הַיּוֹרֵשׁ הַחֶרֶב וְהַמִּלְחָמוֹת, וּמִן הַבְּהֵמוֹת הַשְּׂעִירִים וְהָעִזִּים, וּבְחֶלְקוֹ עוֹד הַשֵּׁדִים הַנִּקְרָאִים מַזִּיקִין בִּלְשׁוֹן רַבּוֹתֵינוּ, וּבִלְשׁוֹן הַכָּתוּב (ויקרא י"ז:ז') "שְׂעִירִים", כִּי כֵן יִקָּרֵא הוּא וְאֻמָּתוֹ "שֵׂעִיר". וְאֵין הַכַּוָּנָה בַּשָּׂעִיר הַמִּשְׁתַּלֵּחַ שֶׁיִּהְיֶה קָרְבָּן מֵאִתָּנוּ אֵלָיו חָלִילָה, אֲבָל שֶׁתִּהְיֶה כַּוָּנָתֵנוּ לַעֲשׂוֹת רְצוֹן בּוֹרְאֵנוּ שֶׁצִּוָּנוּ כָּךְ. וְהַמָּשָׁל בָּזֶה כְּמִי שֶׁעָשָׂה סְעוּדָה לְאָדוֹן וְצִוָּה הָאָדוֹן אֶת הָאִישׁ הָעוֹשֶׂה הַסְּעוּדָה תֵּן מָנֶה אַחַת לְעַבְדִּי פְּלוֹנִי, שֶׁאֵין הָעוֹשֶׂה הַסְּעוּדָה נוֹתֵן כְּלוּם לָעֶבֶד הַהוּא וְלֹא לִכְבוֹדוֹ יַעֲשֶׂה עִמּוֹ, רַק הַכֹּל נָתַן לָאָדוֹן וְהָאָדוֹן נוֹתֵן פְּרָס לְעַבְדּוֹ, וְשָׁמַר זֶה מִצְוָתוֹ וְעָשָׂה לִכְבוֹד הָאָדוֹן כָּל אֲשֶׁר צִוָּהוּ. וְאָמְנָם הָאָדוֹן לְחֶמְלָתוֹ עַל בַּעַל הַסְּעוּדָה רָצָה שֶׁיִּהְיוּ כָּל עֲבָדָיו נֶהֱנִין מִמֶּנָּה, שֶׁיְּסַפֵּר בְּשִׁבְחוֹ וְלֹא בִּגְנוּתוֹ. וְזֶה טַעַם הַגּוֹרָלוֹת, כִּי אִלּוּ הָיָה הַכֹּהֵן מַקְדִּישׁ אוֹתָם בַּפֶּה לַה' וְלַעֲזָאזֵל הָיָה כְּעוֹבֵד אֵלָיו וְנוֹדֵר לִשְׁמוֹ, אֲבָל הָיָה מַעֲמִיד אֹתָם לִפְנֵי ה' פֶּתַח אֹהֶל מוֹעֵד (ויקרא ט"ז:ז'), כִּי שְׁנֵיהֶם מַתָּנָה לַה', וְהוּא נָתַן מֵהֶם לְעַבְדּוֹ הַחֵלֶק אֲשֶׁר יָבֹא לוֹ מֵאֵת הַשֵּׁם, הוּא הִפִּיל לָהֶם גּוֹרָל וְיָדוֹ חָלַק לָהֶם, כְּעִנְיָן שֶׁנֶּאֱמַר (משלי טז לג) "בַּחֵיק יוּטַל אֶת הַגּוֹרָל וּמֵה' כָּל מִשְׁפָּטוֹ", וְגַם אַחֲרֵי הַגּוֹרָל הָיָה מַעֲמִידוֹ לִפְנֵי ה', לוֹמַר שֶׁהוּא שֶׁלּוֹ וְאֵין אֲנַחְנוּ מְכַוְּנִים בְּשִׁלּוּחוֹ אֶלָּא לְרָצוֹן לַשֵּׁם, כְּמוֹ שֶׁאָמַר (ויקרא ט"ז:י') "יָעֳמַד חַי לִפְנֵי ה' לְכַפֵּר עָלָיו לְשַׁלַּח אֹתוֹ" וְגוֹ', וּלְכָךְ לֹא נִשְׁחוֹט אוֹתוֹ אֲנַחְנוּ כְּלָל. וְתִרְגֵּם אוּנְקְלוֹס (תרגום אונקלוס על ויקרא ט"ז:ח') (כאן) "לִשְׁמָא דַּה'" וְ"לַעֲזָאזֵל" כִּי הָאֶחָד לְשֵׁם ה' וְלֹא לוֹ, וְהַשֵּׁנִי לַעֲזָאזֵל וְלֹא לִשְׁמוֹ שֶׁל עֲזָאזֵל, וּמִפְּנֵי זֶה אָמְרוּ רַבּוֹתֵינוּ (ת"כ פרק יג ט) "וְאֶת חֻקֹּתַי" (ויקרא י"ח:ד') - דְּבָרִים שֶׁיֵּצֶר הָרַע מְקַטְרֵג בָּהֶם וְאֻמּוֹת הָעוֹלָם מְשִׁיבִין עֲלֵיהֶם, לְבִישַׁת שַׁעַטְנֵז וּפָרָה אֲדֻמָּה וְשָׂעִיר הַמִּשְׁתַּלֵּחַ; וְלֹא מָצְאוּ בַּקָּרְבָּנוֹת תְּשׁוּבָה לְאוּמוֹת הָעוֹלָם עָלֵינוּ, כִּי הֵם עַל אִשֵּׁי ה', אֲבָל בְּשָׂעִיר הַמִּשְׁתַּלֵּחַ יָשִׁיבוּ עָלֵינוּ, כִּי יַחְשְׁבוּ שֶׁאָנוּ עוֹשִׂים כְּמַעֲשֵׂיהֶם, וְכֵן בְּפָרָה אֲדֻמָּה מִפְּנֵי שֶׁהִיא נַעֲשֵׂית מִחוּץ לַמַּחֲנֶה וְעִנְיָנָהּ דּוֹמֶה לְעִנְיַן שָׂעִיר הַמִּשְׁתַּלֵּחַ, לְהַעֲבִיר רוּחַ הַטֻּמְאָה, כְּעִנְיָן שֶׁנֶּאֱמַר בֶּעָתִיד (זכריה יג ב) "אֶת הַנְּבִיאִים וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ". וּמִזֶּה תָּבִין טַעַם כִּבּוּס בִּגְדֵי הַמְּשַׁלֵּחַ אֶת הַשָּׂעִיר לַעֲזָאזֵל וְהַשּׂוֹרֵף אֶת הַפָּרָה, וּמַה שֶׁהִזְכִּירוּ רַבּוֹתֵינוּ (זבחים קד) בְּכִבּוּס הַבְּגָדִים שֶׁל פָּרִים הַנִּשְׂרָפִים וּשְׂעִירִים הַנִּשְׂרָפִים. וְהִנֵּה רָמַז לְךָ ר"א שֶׁתֵּדַע סוֹדוֹ כְּשֶׁתַּגִּיעַ לַפָּסוּק "וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִם", וְהַמִּלָּה מֻרְכֶּבֶת, וַחֲבֵרֶיהָ רַבִּים. וְהִנֵּה הָעִנְיָן מְבֹאָר, זוּלָתִי אִם תַּחְקֹר מַה עִנְיָן לַשְּׂכָלִים הַנִּבְדָּלִים וְלָרוּחוֹת בְּקָרְבָּן, וְזֶה יִוָּדַע בָּרוּחוֹת בְּחָכְמַת נגרומנסי"א, וְיִוָּדַע גַּם בַּשְּׂכָלִים בְּרִמְזֵי הַתּוֹרָה לַמֵּבִין סוֹדָם. וְלֹא אוּכַל לְפָרֵשׁ כִּי הָיִינוּ צְרִיכִים לַחְסֹם פִּי הַמִּתְחַכְּמִים בַּטֶּבַע, הַנִּמְשָׁכִים אַחֲרֵי הַיְּוָנִי אֲשֶׁר הִכְחִישׁ כָּל דָּבָר זוּלָתִי הַמֻּרְגָּשׁ לוֹ, וְהֵגִיס דַּעְתּוֹ לַחְשֹׁב הוּא וְתַלְמִידָיו הָרְשָׁעִים כִּי כָּל עִנְיָן שֶׁלֹּא הִשִּׂיג אֵלָיו הוּא בִּסְבָרָתוֹ אֵינֶנּוּ אֱמֶת:
@18 **וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי ה' וגו'** הַזָּאוֹת שֶׁלִּפְנֵי הַכַּפֹּרֶת מְכַפְּרוֹת עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו; שֶׁל לִפְנַי לִפְנִים וְהַזָּאוֹת שֶׁעַל הַפָּרֹכֶת בְּאֹהֶל מוֹעֵד מְכַפְּרוֹת עַל טֻמְאַת הֵיכָל וְקָדָשָׁיו, כְּגוֹן מְנוֹרָה וְשֻׁלְחָן וְלֶחֶם הַפָּנִים וּפָרֹכֶת עַצְמָהּ; וּמַתְּנוֹת מִזְבֵּחַ הַפְּנִימִי וְהַזָּאוֹת שֶׁעָלָיו מְכַפְּרוֹת עַל טֻמְאַת מִזְבֵּחַ עַצְמוֹ וְקָדָשָׁיו, כְּגוֹן הַקְּטֹרֶת. וְלָכֵן הַכָּתוּב מְחַלֵּק בָּהֶן וּמַזְכִּיר כָּל כַּפָּרָה לְבַדָּהּ. וּבְתוֹרַת כֹּהֲנִים (פרשה ד א ב) דּוֹרֵשׁ זֶה מִן הַכָּתוּב בַּסּוֹף (ויקרא ט"ז:כ') "וְכִלָּה מִכַּפֵּר אֶת הַקֹּדֶשׁ" וְגוֹ', וְאָמְרוּ, "מִכַּפֵּר אֶת הַקֹּדֶשׁ" זֶה לִפְנַי לִפְנִים, "אֹהֶל מוֹעֵד" זֶה הֵיכָל, "הַמִּזְבֵּחַ" זֶה מִזְבֵּחַ הַפְּנִימִי, מְלַמֵּד שֶׁכָּל אֶחָד כַּפָּרָה בִּפְנֵי עַצְמוֹ. מִכָּאן אָמְרוּ, נָתַן מִקְצַת מַתָּנוֹת שֶׁבִּפְנִים וְנִשְׁפַּךְ הַדָּם, יָבִיא דָּם אַחֵר וְיַתְחִיל בַּתְּחִלָּה בַּמַּתָּנוֹת שֶׁבִּפְנִים. גָּמַר אֶת הַמַּתָּנוֹת מִבִּפְנִים וְנִשְׁפַּךְ הַדָּם, יָבִיא דָּם אַחֵר וְיַתְחִיל בַּתְּחִלָּה בַּמַּתָּנוֹת שֶׁבַּחוּץ. גָּמַר מַתָּנוֹת שֶׁבַּחוּץ וְנִשְׁפַּךְ הַדָּם, יָבִיא דָּם אַחֵר וְיַתְחִיל בַּתְּחִלָּה בְּמַתְּנוֹת הַמִּזְבֵּחַ וכו':
@21 **וְנָתַן אֹתָם עַל רֹאשׁ הַשָּׂעִיר** לֹא נֶאֱמַר בְּפָרוֹ שֶׁל אַהֲרֹן וְלֹא בִּשְׂעִיר הַחַטָּאת שֶׁל שֵׁם וְלֹא בְּשׁוּם סְמִיכָה שֶׁבַּקָּרְבָּנוֹת כַּלָּשׁוֹן הַזֶּה, מִפְּנֵי שֶׁהַקָּרְבָּנוֹת לְרָצוֹן עַל אִשֵּׁי ה' וְהִנָּם מְרַצִּים וּמְכַפְּרִים, אֲבָל זֶה שֶׁאֵינוֹ לַשֵּׁם וְהַמְּקַבְּלוֹ אֵינוֹ מְכַפֵּר וְלֹא מְרַצֶּה, אֵינוֹ אֶלָּא נוֹשֵׂא עֲוֹנֹתָם וְעוֹנֶה אָמֵן בְּעַל כָּרְחוֹ. וּבִהְיוֹת יִשְׂרָאֵל נְקִיִּים מִכָּל חֵטְא וָפֶשַׁע הוּא יִשָּׂא חַטָּאתָם, כַּאֲשֶׁר בִּפְסוּקִים רַבִּים בַּתּוֹרָה וּבַנְּבִיאִים. וְזֶהוּ "וְנָשָׂא הַשָּׂעִיר עָלָיו". וּלְכָךְ לָשׁוֹן שֶׁל זְהוֹרִית מַלְבִּין בִּשְׁעַת שִׁלּוּחוֹ שֶׁל שָׂעִיר בִּדְחִיָּתוֹ לַצּוּק כְּשֶׁנַּעֲשָׂה אֵבָרִים אֵבָרִים, כְּמוֹ שֶׁמֻּזְכָּר בְּדִבְרֵי חֲכָמִים (יומא סז):
@23 **וּבָא אַהֲרֹן אֶל אֹהֶל מוֹעֵד** אָמְרוּ רַבּוֹתֵינוּ שֶׁאֵין זֶה מְקוֹמוֹ שֶׁל מִקְרָא זֶה, וְנָתְנוּ טַעַם לְדִבְרֵיהֶם בְּמַסֶּכֶת יוֹמָא (יומא ל"ב) וְאָמְרוּ, כָּל הַפָּרָשָׁה כֻּלָּהּ נֶאֶמְרָה עַל הַסֵּדֶר חוּץ מִבִּיאָה זוֹ, שֶׁהִיא אַחַר עֲשִֹיַּת עוֹלָתוֹ וְעוֹלַת הָעָם וְהַקְטָרַת אֵמוּרֵי פַּר וְשָֹעִיר שֶׁנַּעֲשִׂין בַּחוּץ בְּבִגְדֵי זָהָב, וְטוֹבֵל וּמְקַדֵּשׁ וּפוֹשְׁטָן וְלוֹבֵשׁ בִּגְדֵי לָבָן, וּבָא אֶל אֹהֶל מוֹעֵד לְהוֹצִיא אֶת הַכַּף וְאֶת הַמַּחְתָּה שֶׁהִקְטִיר בָּהּ אֶת הַקְּטֹרֶת לִפְנַי לִפְנִים, וּפָשַׁט אֶת בִּגְדֵי הַבָּד אַחַר שֶׁהוֹצִיאָם וְלוֹבֵשׁ בִּגְדֵי זָהָב לְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ט"ז:כ"ג). וּבֶאֱמֶת שֶׁהַכָּתוּב הַזֶּה אוֹמֵר לָנוּ דָּרְשֵׁנִי, שֶׁלֹּא יִתָּכֵן בְּשׁוּם פָּנִים שֶׁיְּצַוֶּה שֶׁיָּבֹא אַהֲרֹן אֶל אֹהֶל מוֹעֵד לְלֹא דָּבָר, רַק לִפְשֹׁט שָׁם בְּגָדָיו וְלִהְיוֹתוֹ עָרֹם בְּהֵיכַל ה' וּלְהַנִּיחָם שָׁם לְרִקָּבוֹן. אֲבָל עַל כָּרְחֵנוּ "וּבָא אַהֲרֹן אֶל אֹהֶל מוֹעֵד" לַעֲבֹד עֲבוֹדָה לֹא הֻצְרַךְ הַכָּתוּב לְהַזְכִּירָהּ, וְהִיא הוֹצָאַת הַכַּף וְהַמַּחְתָּה. וְטַעַם הַכָּתוּב כִּי הִזְכִּיר בַּתְּחִלָּה "וְנָתַן אֶת הַקְּטֹרֶת עַל הָאֵשׁ לִפְנֵי ה' וְכִסָּה עֲנַן הַקְּטֹרֶת אֶת הַכַּפֹּרֶת אֲשֶׁר עַל הָעֵדוּת וְלֹא יָמוּת" (ויקרא ט"ז:י"ג), לוֹמַר שֶׁיִּתֵּן הַקְּטֹרֶת עַל הָאֵשׁ עַד שֶׁיַּעֲלֶה עֲנַן הַקְּטֹרֶת וְיֵצֵא מִיָּד, וְהִנִּיחַ הַכַּף וְהַמַּחְתָּה שָׁם, וְעַל כָּל פָּנִים יִצְטָרֵךְ לְהוֹצִיא. וּלְכָךְ אָמַר "וּבָא אַהֲרֹן אֶל אֹהֶל מוֹעֵד", לָבֹא מִבֵּית לַפָּרֹכֶת לְמָה שֶׁהִנִּיחַ שָׁם. וְהִנֵּה הַפָּרָשָׁה לֹא הִזְכִּירָה כָּל מַה שֶׁיַּעֲשֶׂה הַכֹּהֵן בַּתְּחִלָּה בְּבִגְדֵי זָהָב, כְּגוֹן תָּמִיד שֶׁל שַׁחַר, אֲבָל הִתְחִילָה בַּעֲבוֹדַת הַיּוֹם בְּבִגְדֵי לָבָן, וְסִדְרָה הַפָּרָשָׁה שֶׁיַּעֲשֶׂה בָּהֶם קְטֹרֶת שֶׁלִּפְנַי לִפְנִים וּפַר שָׂעִיר הַפְּנִימִי וְעִנְיַן הַשָּׂעִיר הַמִּשְׁתַּלֵּחַ, וְכָל זֶה עָשׂוּי בְּסֵדֶר אֶחָד, וְלֹא נִשְׁאַר לַעֲשׂוֹת בַּבְּגָדִים הָאֵלּוּ לְבַד הוֹצָאַת הַכַּף וְהַמַּחְתָּה. וְדֶרֶךְ הַכְּתוּבִים בְּכָל מָקוֹם לְהַשְׁלִים הָעִנְיָן אֲשֶׁר הִתְחִיל בּוֹ, אע"פ שֶׁיֵּשׁ בּוֹ קְצָת עִנְיָן מְאֻחָר לְמָה שֶׁיַּזְכִּיר אַחַר כֵּן. וּלְכָךְ אָמַר "וּבָא אַהֲרֹן אֶל אֹהֶל מוֹעֵד" בַּבְּגָדִים הָאֵלֶּה, לְהַשְׁלִים עֲבוֹדוֹתָיו בָּהֶם, וְהִיא הוֹצָאַת הַכַּף וְהַמַּחְתָּה שֶׁהוּא צָרִיךְ לְהוֹצִיאָם מִשָּׁם. וּפָשַׁט אַחֲרֵי צֵאתוֹ אֶת בְּגָדָיו אֲשֶׁר לָבַשׁ בַּבֹּקֶר בָּעֵת בֹּאוֹ אֶל הַקֹּדֶשׁ, וְהִנִּיחָם שָׁם בַּמָּקוֹם אֲשֶׁר יַפְשִׁיטֵם, לְלַמֵּד שֶׁלֹּא יִלְבַּשׁ אוֹתָם בְּיוֹם הַכִּפּוּרִים אַחֵר. וְהִנֵּה נִשְׁלַם כָּל הַנַּעֲשֶׂה בְּבִגְדֵי לָבָן בְּכָל הַיּוֹם בְּסֵדֶר אֶחָד. וְחָזַר וְאָמַר "וְרָחַץ אֶת בְּשָׂרוֹ בַמַּיִם וְגוֹ' וְלָבַשׁ אֶת בְּגָדָיו" הַיְּדוּעִים לוֹ, שֶׁבָּהֶם יַעֲבֹד כָּל הַשָּׁנָה, לְלַמֵּד שֶׁהוּא טָעוּן טְבִילָה בֵּין בְּגָדִים לִבְגָדִים, וְאָמַר "וְיָצָא וְעָשָׂה אֶת עֹלָתוֹ", כִּי כָל הַנַּעֲשֶׂה קֹדֶם לָזֶה בְּבִגְדֵי הַלָּבָן הַכֹּל מַעֲשֵׂה פְּנִים, וְאֵילוֹ וְאֵיל הָעָם שֶׁיַּזְכִּיר הֵם נַעֲשִׂים עַל הַמִּזְבֵּחַ הַחִיצוֹן. וְהִנֵּה הִזְכִּירָה הַפָּרָשָׁה (ויקרא ט"ז:ד') הַלְּבִישָׁה הָרִאשׁוֹנָה שֶׁל בִּגְדֵי הַלָּבָן וְהִצְרִיךְ בָּהּ טְבִילָה, וְהִזְכִּירָה (ויקרא ט"ז:כ"ד) הַפְּשִׁיטָה הָאַחֲרוֹנָה וְהִצְרִיךְ בָּהּ טְבִילָה, וְלָמַדְנוּ שֶׁהוּא טָעוּן טְבִילָה בְּכָל חֲלִיפוֹת בְּגָדִים. וְעַל דַּעַת רַשִׁ"י תִּהְיֶה הַטְּבִילָה הַזֹּאת שֶׁל הוֹצָאַת כַּף וּמַחְתָּה אַחֲרֵי אֵילוֹ וְאֵיל הָעָם, בֵּין הַמּוּסָפִין לְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְכֵן דַּעַת כָּל הַגְּאוֹנִים, וְכֵן יֵרָאֶה מִן הַבָּרַיְתָא הַשְּׁנוּיָה בְּתוֹרַת כֹּהֲנִים (פרק ו ה) כִּפְשׁוּטָהּ. אֲבָל אָנוּ מָצָאנוּ בַּיְּרוּשַׁלְמִי (יומא פ"ז ה"ב), אָמַר רַבִּי יוֹחָנָן, הַכֹּל מוֹדִים בְּהוֹצָאַת הַכַּף וְהַמַּחְתָּה שֶׁהִיא לְאַחַר תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְכֵן כָּתַב הָרַב ר' מֹשֶׁה (הל' עבודת יום הכפורים פ"ב ה"ב), וְכֵן הַסֵּדֶר הַשָּׁנוּי בְּמִשְׁנָתֵנוּ (יומא ע), קִדֵּשׁ וּפָשַׁט וְיָרַד וְטָבַל, הֵבִיאוּ לוֹ בִּגְדֵי זָהָב, נִכְנַס לְהַקְטִיר אֶת הַקְּטֹרֶת. אֶלָּא כָּךְ הוּא הַסֵּדֶר: סֵדֶר הַיּוֹם בְּבִגְדֵי לָבָן, וְאֵילוֹ וְאֵיל הָעָם וְהַמּוּסָפִין וְאֵמוּרֵי הַחַטָּאת וְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם בְּבִגְדֵי זָהָב בִּטְבִילָה שְׁלִישִׁית, וְהוֹצָאַת כַּף וּמַחְתָּה בְּבִגְדֵי לָבָן בִּטְבִילָה רְבִיעִית, קְטֹרֶת חֲבִתִּים וּנְסָכִים וְנֵרוֹת בְּבִגְדֵי זָהָב בִּטְבִילָה חֲמִישִׁית. וְהַטַּעַם בָּזֶה, לְפִי שֶׁאֵינָהּ עֲבוֹדָה, וְאִחֲרוּ אוֹתָהּ לְאַחַר כָּל מַעֲשֵׂה הַיּוֹם וּבִלְבַד שֶׁנְּקַיֵּם בָּהּ חָמֵשׁ טְבִילוֹת. וּלְכָךְ הִפְסִיק בְּסֵדֶר הַתָּמִיד שֶׁל בֵּין הָעַרְבַּיִם, וּמוֹצִיאִין כַּף וּמַחְתָּה בֵּין הַתָּמִיד לִקְטֹרֶת:
@27 **יוֹצִיא אֶל מִחוּץ לַמַּחֲנֶה** יוֹצִיא אַהֲרֹן הַנִּזְכָּר (בפסוקים כג כה) בְּצִוּוּי, עַל דַּעַת ר"א (אבן עזרא על ויקרא ט"ז:כ"ז). וְהַנָּכוֹן, "יוֹצִיא" הַמּוֹצִיא. וְכֵן "וְשָׂרְפוּ" הַשּׂוֹרְפִים. וְאָמַר הַכָּתוּב "וְשָׂרְפוּ" בִּלְשׁוֹן רַבִּים, לְלַמֵּד שֶׁאִם נִתְעַסְּקוּ רַבִּים בַּשְּׂרֵפָה, אֶחָד מֵבִיא אֶת הָאוּר וְאֶחָד מְסַדֵּר עֲצֵי הַמַּעֲרָכָה וְאֶחָד מַבְעִיר אֶת הָאֵשׁ, לֹא יְטַמְּאוּ בְּגָדִים אֶלָּא הַמַּצִּית אֶת הָאוּר בַּפָּרִים עַצְמָם מִשֶּׁיַּצִּיתֶנּוּ בְּרֻבּוֹ. וּלְכָךְ חָזַר וְאָמַר בִּלְשׁוֹן יָחִיד "וְהַשּׂוֹרֵף אוֹתָם":
@29 **תְּעַנּוּ אֶת נַפְשֹׁתֵיכֶם** כְּבָר בֵּאֵר רַבִּי אַבְרָהָם כִּי כָל עִנּוּי שֶׁיִּמָּצֵא בַּמִּקְרָא דָּבֵק עִם הַנֶּפֶשׁ הוּא הַצּוֹם, לִסְתֹּם פִּיהֶם שֶׁל הַקָּרָאִים מְחוּקֵי שֵׁם:
@32 **וַאֲשֶׁר יְמַלֵּא אֶת יָדוֹ** שֶׁיָּכוֹל אֵין לִי אֶלָּא הַמָּשׁוּחַ בְּשֶׁמֶן הַמִּשְׁחָה, מְרֻבֶּה בִּבְגָדִים מִנַּיִן, תַּלְמוּד לוֹמַר "וַאֲשֶׁר יְמַלֵּא אֶת יָדוֹ (ללבוש את הבגדים)", וְהֵן כָּל הַכֹּהֲנִים הַגְּדוֹלִים שֶׁעָמְדוּ מִיֹּאשִׁיָּהוּ וְאֵילָךְ, שֶׁבְּיָמָיו נִגְנְזָה הַצְּלוֹחִית שֶׁל שֶׁמֶן הַמִּשְׁחָה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ט"ז:ל"ב). וְאֵין הַכַּוָּנָה לָרַב שֶׁלֹּא יְהֵא בַּמִּקְדָּשׁ כֹּהֵן גָּדוֹל מְרֻבֶּה בִּבְגָדִים אֶלָּא מִיֹּאשִׁיָּהוּ וְאֵילָךְ, שֶׁהֲרֵי בַּגְּמָרָא (הוריות יג) אָמְרוּ מָשׁוּחַ בְּשֶׁמֶן הַמִּשְׁחָה וּמְרֻבֶּה בִּבְגָדִים אֵיזֶה מֵהֶן קוֹדֵם, וְאָמְרוּ (מכות יא), בְּמִיתַת כֻּלָּן הוּא חוֹזֵר אוֹ בְּמִיתַת אֶחָד מֵהֶן הוּא חוֹזֵר - שֶׁכֻּלָּן נִמְצָאִים בִּזְמַן אֶחָד. אֲבָל בְּכָל הַזְּמַנִּים אִם נִתְרַבָּה בִּבְגָדִים כָּשֵׁר לַעֲבוֹדַת יוֹם הַכִּפּוּרִים, שֶׁהֲרֵי לְעוֹלָם מְתַקְּנִין כֹּהֵן אַחֵר בְּיוֹם הַכִּפּוּרִים (יומא ב) וְאֵין מוֹשְׁחִין אוֹתוֹ, וְאִם אֵרַע פְּסוּל בְּכֹהֵן גָּדוֹל מְשַׁמֵּשׁ זֶה תַּחְתָּיו, שֶׁהוּא כָּשֵׁר בְּרִבּוּי הַבְּגָדִים בְּלֹא מְשִׁיחָה:
@34 וְטַעַם **וַיַּעַשׂ כַּאֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה** שֶׁקִּיֵּם אַהֲרֹן כָּל מַה שֶׁנִּצְטַוָּה, וְנִזְהַר כָּל יָמָיו שֶׁלֹּא יָבֹא אֶל מִבֵּית לַפָּרֹכֶת זוּלָתִי בְּיוֹם הַכִּפּוּרִים, וְעָשָׂה בְּיוֹם הַכִּפּוּרִים קָרְבְּנוֹתָיו כְּכָל אֲשֶׁר צִוָּה הַשֵּׁם אֶת מֹשֶׁה:
@36 **אֶל אַהֲרֹן וְאֶל בָּנָיו וְאֶל כָּל בְּנֵי יִשְׂרָאֵל** בַּעֲבוּר הֱיוֹת הַפָּרָשָׁה אַזְהָרָה לְהַקְרִיב כָּל הַקָּרְבָּנוֹת בְּאֹהֶל מוֹעֵד, יַזְהִיר הַכֹּהֲנִים שֶׁהֵם הַמַּקְרִיבִים הַקָּרְבָּן שֶׁלֹּא יַקְרִיבוּם בַּחוּץ, וְיַזְהִיר גַּם יִשְׂרָאֵל שֶׁיְּבִיאוּם לַה' שָׁם וְלֹא יַקְרִיבוּ אוֹתָם בַּחוּץ עַל יְדֵי עַצְמָם. וְהַנָּכוֹן בַּפָּרָשָׁה מַה שֶׁהִזְכִּירוּ רַבּוֹתֵינוּ (חולין טז), שֶׁאָסַר בְּשַׂר תַּאֲוָה לְיִשְׂרָאֵל בַּמִּדְבָּר, וְלֹא יֹאכְלוּ רַק שְׁלָמִים שֶׁיַּעֲשׂוּ עַל מִזְבַּח ה'. וּלְכָךְ אָמַר שֶׁכָּל מִי שֶׁיִּשְׁחֹט מִשְּׁלֹשֶׁת מִינֵי הַבְּהֵמוֹת אֲשֶׁר מֵהֶן יָבִיאוּ כָּל הַקָּרְבָּנוֹת, שֶׁהֵם שׁוֹר וְכֶשֶׂב וָעֵז, שֶׁיְּבִיאוּם כֻּלָּם אֶל פֶּתַח אֹהֶל מוֹעֵד וְיַעֲשׂוּ אוֹתָם זִבְחֵי שְׁלָמִים, לְהַקְרִיב הַחֵלֶב וְהַדָּם עַל מִזְבַּח ה', וְאָז יֹאכַל הוּא הַבָּשָׂר כַּמִּשְׁפָּט. וְאָמַר שֶׁאִם יִשְׁחָטֵם בְּמָקוֹם אַחֵר יִהְיֶה חַיָּב כָּרֵת. וְהַקָּרוֹב בִּלְשׁוֹן הַכָּתוּב, כִּי מִתְּחִלָּה חִיֵּב כָּרֵת בְּכָל שׁוֹחֵט בַּחוּץ, אֲפִלּוּ הַחֻלִּין, וְהוּא הָאִסּוּר בִּבְשַׂר הַתַּאֲוָה, וְנָתַן הַטַּעַם בַּעֲבוּר שֶׁיַּקְדִּישׁוּם לַה' וְיִזְרֹק הַכֹּהֵן הַדָּם עַל מִזְבַּח ה' וְיַקְטִיר עָלָיו הַחֵלֶב, וְאַחֲרֵי כֵן (בפסוקים ח-ט) הִזְהִיר שֶׁלֹּא יַעֲשֶׂה מִזְבֵּחַ לַה' בַּחוּץ וְיַקְרִיב עָלָיו הַשְּׁלָמִים הַנִּזְכָּרִים אוֹ עוֹלָה, כָּעִנְיָן הַנַּעֲשֶׂה בַּמֻּקְדָּשִׁין בִּשְׁעַת הֶתֵּר הַבָּמוֹת, רַק בְּפֶתַח אֹהֶל מוֹעֵד יַעֲלֶה אוֹתָם לַשֵּׁם. וְהִנֵּה רִקֵּן כָּל הַשְּׁחִיטוֹת בְּחֻלִּין וּבְמֻקְדָּשִׁין לִהְיוֹת כֻּלָּן בִּפְנִים. וּלְכָךְ אָמַר בְּמִשְׁנֵה תּוֹרָה (דברים יב י יא) "וַעֲבַרְתֶּם אֶת הַיַּרְדֵּן וִישַׁבְתֶּם בָּאָרֶץ וגו' וְהָיָה הַמָּקוֹם אֲשֶׁר יִבְחַר ה' שָׁמָּה תָּבִיאוּ עוֹלוֹתֵיכֶם וְזִבְחֵיכֶם", וְאָמַר (שם פסוקים יג יד) "הִשָּׁמֶר לְךָ פֶּן תַּעֲלֶה עֹלֹתֶיךָ בְּכָל מָקוֹם אֲשֶׁר תִּרְאֶה כִּי אִם בַּמָּקוֹם" וגו', לִהְיוֹת אִסּוּר שְׁחוּטֵי חוּץ בְּמֻקְדָּשִׁין עוֹמֵד בִּמְקוֹמוֹ בִּשְׁעַת בֵּית הַבְּחִירָה, אֲבָל הִתִּיר אוֹתוֹ בְּחֻלִּין. זֶהוּ שֶׁאָמַר (שם פסוק טו), "רַק בְּכָל אַוַּת נַפְשְׁךָ תִּזְבַּח וְאָכַלְתָּ בָשָׂר" וגו', לוֹמַר שֶׁלֹּא תִּתְנַהֵג בָּאָרֶץ הַמְּנִיעָה הַנֶּאֱמֶרֶת כָּאן שֶׁלֹּא יִשְׁחֹט חֻלִּין כְּלָל וְשֶׁיַּעֲשֶׂה הַכֹּל זִבְחֵי שְׁלָמִים עַל מִזְבַּח ה'. וּפֵרֵשׁ שָׁם (דברים י"ב:כ') הַטַּעַם, "כִּי יַרְחִיב ה' אֱלֹהֶיךָ אֶת גְּבוּלְךָ" וגו', לוֹמַר כִּי הָיָה הָאִסּוּר מִתְּחִלָּה בִּהְיוֹתָם בַּמִּדְבָּר שֶׁיֵּקַל עֲלֵיהֶם לְהָבִיא כָּל זִבְחֵיהֶם אֶל פֶּתַח אֹהֶל מוֹעֵד, אֲבָל אַחֲרֵי שֶׁיַּרְחִיב גְּבוּלָם יֹאכְלוּ בְּשַׂר תַּאֲוָה וְיִשְׁחֲטוּ בְּשַׁעֲרֵיהֶם, אַךְ לֹא הַמֻּקְדָּשִׁין. וְזֶה טַעַם מַה שֶׁהִזְכִּיר בְּכָאן "אֲשֶׁר יִשְׁחַט בַּמַּחֲנֶה אוֹ אֲשֶׁר יִשְׁחַט מִחוּץ לַמַּחֲנֶה", יַזְכִּיר גַּם הַשּׁוֹחֲטִים מִחוּץ לַמַּחֲנֶה שֶׁיִּהְיוּ חַיָּבִים לְהָבִיא אוֹתָם אֶל פֶּתַח אֹהֶל מוֹעֵד, כִּי אע"פ שֶׁיַּתִּיר בְּשַׂר תַּאֲוָה כְּשֶׁיַּרְחִיב הַשֵּׁם גְּבוּלָם מִפְּנֵי שֶׁאֵינָם בִּמְקוֹם הַמִּקְדָּשׁ, לֹא יַתִּיר כֵּן בַּמִּדְבָּר אֲפִלּוּ חוּץ לַמַּחֲנֶה, לְפִי שֶׁאֵינָם רְחוֹקִים מִן הַמִּזְבֵּחַ כַּאֲשֶׁר יִהְיוּ בָּאָרֶץ שֶׁיַּרְחִיב הַשֵּׁם גְּבוּלָם, כִּי אָז יַתִּיר לָהֶם בְּשַׂר תַּאֲוָה. וְזֶהוּ דַּעְתּוֹ שֶׁל רַבִּי יִשְׁמָעֵאל (חולין טז) בַּפָּרָשִׁיּוֹת הַלָּלוּ, וּמִכָּאן אָמַר דְּמֵעִקָּרָא אִתְּסַר לְהוּ בְּשַׂר תַּאֲוָה, וְהוּא הַנָּאוֹת בַּכָּתוּב עַל דֶּרֶךְ הַפְּשָׁט. וְזֶהוּ מַאֲמָרָם בַּהַגָּדָה (דב"ר ד ו), רַבָּנִין אָמְרִין, הַרְבֵּה דְּבָרִים אָסַר אוֹתָם הקב"ה וְחָזַר וְהִתִּירָם בְּמָקוֹם אַחֵר. תֵּדַע לְךָ, אָסַר הקב"ה לִשְׁחֹט וְלֶאֱכֹל לְיִשְׂרָאֵל עַד שֶׁיְּבִיאֶנּוּ פֶּתַח אֹהֶל מוֹעֵד, מִנַּיִן, שֶׁנֶּאֱמַר (ויקרא י"ז:ד') "וְאֶל פֶּתַח אֹהֶל מוֹעֵד" וְגוֹ', מַה כְּתִיב שָׁם, "דָּם יֵחָשֵׁב לָאִישׁ הַהוּא" וְגוֹ', וְכָאן חָזַר וְהִתִּירוֹ לָהֶם, שֶׁנֶּאֱמַר (דברים יב כ) "בְּכָל אַוַּת נַפְשְׁךָ תֹּאכַל בָּשָׂר", מִנַּיִן, מִמַּה שֶׁקָּרְאוּ בְּעִנְיָן "כִּי יַרְחִיב ה' אֱלֹהֶיךָ". וּמַה שֶׁכָּתַב רַשִׁ"י (רש"י על ויקרא י"ז:ג') בְּמֻקְדָּשִׁין הַכָּתוּב מְדַבֵּר וכו', הוּא מִדְרָשׁוֹ שֶׁל הָאוֹמֵר (חולין טז) בְּשַׂר תַּאֲוָה לָא אִתְּסַר כְּלָל, וְעַל דַּעְתּוֹ נִשְׁנֵית הַבָּרַיְתָא שֶׁבְּתוֹרַת כֹּהֲנִים (כאן). אֲבָל דֶּרֶךְ יִשּׁוּב הַמִּקְרָאוֹת עַל אוֹפַנֵּיהֶם וְדֶרֶךְ חֲכָמִים בַּהַגָּדוֹת וּבְרוֹב הַמְּקוֹמוֹת כְּמוֹ שֶׁפֵּרַשְׁנוּ:
@38 וְטַעַם **דָּם יֵחָשֵׁב** מִמַּעֲשֵׂה בְּרֵאשִׁית (בראשית א כט ל), יֹאמַר הִנֵּה בְּכָל בַּעֲלֵי חַיִּים זוּלָתִי אָדָם עָשִׂיתִי דָּמָם כַּמַּיִם וּלְחֻמָם כַּגְּלָלִים, כְּמוֹ שֶׁאָמַר (שם ט ג), "כְּיֶרֶק עֵשֶׂב נָתַתִּי לָכֶם אֶת כֹּל", אֲבָל אִם יִשְׁחַט מִחוּץ לַמַּחֲנֶה יֵחָשֵׁב כְּשׁוֹפֵךְ דָּמִים:
@41 **לַשְּׂעִירִם** לַשֵּׁדִים, וְכֵן הוּא אוֹמֵר (ישעיהו יג כא) "וּשְׂעִירִים יְרַקְּדוּ שָׁם", לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ז:ז') מִתּוֹרַת כֹּהֲנִים (פרק ט ח). וְאָמַר ר"א (אבן עזרא על ויקרא י"ז:ז') שֶׁנִּקְרְאוּ הַשֵּׁדִים כֵּן בַּעֲבוּר שֶׁיִּשְׂתָּעֵר הַגּוּף הָרוֹאֶה אוֹתָם. וְהַקָּרוֹב, בַּעֲבוּר שֶׁיִּרְאוּ אוֹתָם הַמְּשֻׁגָּעִים כִּדְמוּת שְׂעִירִים. וּמִלַּת "עוֹד" תּוֹרֶה שֶׁכֵּן הָיוּ יִשְׂרָאֵל עוֹשִׂים בְּמִצְרַיִם. **אֲשֶׁר הֵם זֹנִים** כִּי כָל מְבַקֵּשׁ אוֹתָם וּמַאֲמִין בָּהֶם הוּא זוֹנֶה מִתַּחַת אֱלֹהָיו, שֶׁיַּחְשֹׁב כִּי יֵשׁ מִי שֶׁמֵּטִיב אוֹ יָרַע חוּץ מֵהַשֵּׁם הַנִּכְבָּד וְהַנּוֹרָא. וּכְבָר רָמַז רַבִּי אַבְרָהָם בְּמִלַּת "עוֹד" הָאֱמֶת כַּאֲשֶׁר כָּתַבְתִּי לְמַעְלָה (רמב"ן על ויקרא ט"ז:ח'). וְכֵן שֵׁם הַשְּׂעִירִים יִתְבָּרֵר לְךָ מִשָּׁם. וְיִקָּרְאוּ "שֵׁדִים" בַּעֲבוּר שֶׁמִּשְׁכְּנָם בְּמָקוֹם שָׁדוּד, כְּגוֹן הַמִּדְבָּר, וְעִקַּר מְצִיאוּתָם בַּקְּצָווֹת, כְּגוֹן פְּאַת צָפוֹן הֶחָרֵב מִפְּנֵי הַקֹּר. וְדַע כִּי כַּאֲשֶׁר הַבְּרִיאָה מִתְּחִלָּה בְּמַעֲשֵׂה בְּרֵאשִׁית בְּגוּף הָאָדָם וּבְכָל בַּעֲלֵי הַנֶּפֶשׁ וְהַצְּמָחִים וְהַמַּתָּכוֹת מֵאַרְבַּע יְסוֹדוֹת, וְנִתְחַבְּרוּ אַרְבַּעְתָּם בְּכֹחַ אֱלֹהִי לִהְיוֹת מֵהֶן גּוּף גַּס מֻרְגָּשׁ לְכָל חֲמֵשׁ הַהַרְגָּשׁוֹת לְעָבְיוֹ וּלְגַסּוּתוֹ, כָּךְ הָיְתָה יְצִירָה מִשְּׁנֵי יְסוֹדוֹת, מִן הָאֵשׁ וְהָאֲוִיר, וְהָיָה מֵהֶם גּוּף אֵינוֹ נִרְגָּשׁ וְלֹא מֻשָּׂג לְאַחַת מִן הַהַרְגָּשׁוֹת, כַּאֲשֶׁר נֶפֶשׁ הַבְּהֵמָה אֵינֶנָּה מֻשֶּׂגֶת לַהַרְגָּשׁוֹת לְדַקּוּתָהּ, וְהַגּוּף הַזֶּה הוּא רוּחָנִי, יָטוּס לְדַקּוּתוֹ וְקַלּוּתוֹ בָּאֵשׁ וּבַאֲוִיר, וְכַאֲשֶׁר הַהַרְכָּבָה בְּכָל דָּבָר סִבַּת הַהֲוָיָה וְהַהֶפְסֵד בַּמֻּרְכָּב מֵאַרְבַּע יְסוֹדוֹת, כָּךְ הִיא בַּמֻּרְכָּבִים הָאֵלּוּ מִשְּׁנֵי הַיְּסוֹדוֹת, כִּי בְּהִתְחַבְּרוּתָם יִהְיֶה בַּעַל הַגּוּף חַי וּבְהִתְפָּרְדָם יִהְיֶה כַּמֵּת. וּלְכָךְ אָמְרוּ רַבּוֹתֵינוּ (חגיגה טז), שִׁשָּׁה דְּבָרִים נֶאֶמְרוּ בַּשֵּׁדִים, שְׁלֹשָׁה כְּמַלְאֲכֵי הַשָּׁרֵת וּשְׁלֹשָׁה כִּבְנֵי אָדָם, שְׁלֹשָׁה כְּמַלְאֲכֵי הַשָּׁרֵת - יֵשׁ לָהֶם כְּנָפַיִם כְּמַלְאֲכֵי הַשָּׁרֵת, וְטָסִים כְּמַלְאֲכֵי הַשָּׁרֵת, וְיוֹדְעִין מַה שֶׁעָתִיד לָבֹא כְּמַלְאֲכֵי הַשָּׁרֵת, יוֹדְעִין סָלְקָא דַעְתָּךְ, אֶלָּא אֵימָא שׁוֹמְעִין מַה שֶׁעָתִיד לִהְיוֹת; שְׁלֹשָׁה כִּבְנֵי אָדָם - אוֹכְלִין וְשׁוֹתִין כִּבְנֵי אָדָם, פָּרִין וְרָבִין כִּבְנֵי אָדָם, וּמֵתִים כִּבְנֵי אָדָם. וְסִבַּת הַמִּיתָה פֵּרוּד הַחִבּוּר, הִיא הַסִּבָּה בְּכָל הַמֻּרְכָּבִים, וְסִבַּת הַטִּיסָה בְּקַלּוּת יְסוֹדוֹתָם, כַּאֲשֶׁר נִרְאֶה גַּם בָּעוֹף, כִּי מִפְּנֵי שֶׁגָּבְרוּ עָלָיו הָאֵשׁ וְהָאֲוִיר, וְהַיְּסוֹדוֹת הָאֲחֵרִים בּוֹ מְעַטִּים, הוּא טַס וּפוֹרֵחַ, וְכָל שֶׁכֵּן אֵלּוּ שֶׁאֵין בָּהֶם מִן הַיְּסוֹדוֹת הַכְּבֵדִים כְּלוּם, שֶׁטִּיסָתָן גְּדוֹלָה, יָעוּפוּ וְלֹא יִיגָעוּ. וְעִנְיַן הָאֲכִילָה, לִלְחֹךְ מִן הַמַּיִם וְהָאֵשׁ הָרֵיחוֹת וְהַלֵּחוֹת, כְּעִנְיַן הָאֵשׁ שֶׁתִּלְחוֹךְ הַמַּיִם אֲשֶׁר בַּתְּעָלָה (מלכים א יח לח). וְהוּא עִנְיַן הַהַקְטָרוֹת שֶׁיַּעֲשׂוּ בַּעֲלֵי נגרומנסיא"ה לַשֵּׁדִים, וְסִבָּתָהּ הַיֹּבֶשׁ אֲשֶׁר תִּיבַשׁ הָאֵשׁ אֲשֶׁר בַּאֲוִיר בְּגוּפָן וְצָרִיךְ לְהַחְזִירָהּ, כַּאֲשֶׁר הִיא הָאֲכִילָה בָּאָדָם לְצֹרֶךְ מָה שֶׁהוּא נִתָּךְ מִמֶּנּוּ. וְעִנְיַן מַה שֶׁאָמְרוּ שׁוֹמְעִין מַה שֶׁעָתִיד לִהְיוֹת, כִּי בְּטִיסָתָן בַּאֲוִיר הַשָּׁמַיִם יְקַבְּלוּ הָעֲתִידוֹת מִשָּׂרֵי הַמַּזָּלוֹת הַשּׁוֹכְנִים בָּאֲוִיר, וְהֵם נְגִידֵי הַתְּלִי, וּמִשָּׁם יַגִּידוּ גַּם בַּעֲלֵי הַכְּנָפַיִם הָעֲתִידוֹת, כַּאֲשֶׁר הוּא מְנֻסֶּה בַּנְּחָשִׁים וְכַאֲשֶׁר אֲפָרֵשׁ בִּמְקוֹמוֹ (דברים יח ט) בע"ה. וְאֵלּוּ וְאֵלּוּ אֵינָם יוֹדְעִים בַּמֶּה שֶׁעָתִיד לִהְיוֹת לְיָמִים רַבִּים וּלְעִתִּים רְחוֹקוֹת, רַק יוֹדִיעוּ בֶּעָתִיד לִהְיוֹת בְּקָרוֹב, כִּי יָדַעְנוּ בְּנִסְיוֹנוֹתָם שֶׁיְּקַבְּלוּ מִן הַשֵּׁדִים בַּנִּגְזָר לָבֹא. וּלְכָךְ תִּרְגֵּם אוּנְקְלוֹס (תרגום אונקלוס על ויקרא י"ז:ז') "יִזְבְּחוּ לַשֵּׁדִים לֹא אֱלֹהַּ" (דברים לב יז) - "דַּבַּחוּ לְשֵׁדִין דְּלֵית בְּהוֹן צְרוֹךְ", יֹאמַר שֶׁאֵין בָּהֶם שׁוּם צֹרֶךְ, כִּי לֹא יִמְנְעוּ הַנֶּזֶק הֶעָתִיד וְלֹא יַעֲשׂוּ שׁוּם תּוֹעֶלֶת, וְגַם לֹא יוֹדִיעוּ בָּרָחוֹק שֶׁיִּשְׁתַּמֵּר מִמֶּנּוּ הָאָדָם בְּדַעְתּוֹ. וְהוּא לְשׁוֹן הַכָּתוּב גַּם כֵּן "לֹא אֱלוֹהַּ", כְּאִלּוּ אָמַר "לֹא כֹּחַ וּמֶמְשָׁלָה", כִּי אֱלֹהִים לְשׁוֹן אֱיָלוּת וְכֹחַ, אֵל הֵם, יֹאמַר שֶׁאֵין בַּשֵּׁדִים אֱיָלוּת וְשׁוּם כֹּחַ וּלְכָךְ אֵין צֹרֶךְ בָּהֶם, כִּי לֹא יָרֵעוּ וְגַם הֵיטֵב אֵין אוֹתָם:
@45 **כִּי נֶפֶשׁ הַבָּשָׂר בַּדָּם הִוא וַאֲנִי נְתַתִּיו לָכֶם עַל הַמִּזְבֵּחַ** מַשְׁמָעוּת הַכָּתוּב הַזֶּה שֶׁיֹּאמַר שֶׁיֵּאָסֵר לָנוּ הַדָּם מִפְּנֵי שֶׁנְּתָנוֹ לָנוּ לִהְיוֹת עַל הַמִּזְבֵּחַ לְכַפֵּר עַל נַפְשׁוֹתֵינוּ וְהוּא חֵלֶק הַשֵּׁם, כְּטַעַם הַחֵלֶב. וְאִם נַקְשֶׁה, לָמָּה אָסַר דַּם הַחַיָּה וְהָעוֹף אֲשֶׁר לֹא יִקְרַב, נִדְחֶה אֶת הַשּׁוֹאֵל שֶׁרָצָה לְהַרְחִיקֵנוּ מִכָּל דָּם שֶׁלֹּא נִשְׁגֶּה בּוֹ, אע"פ שֶׁלֹּא עָשָׂה כֵן בַּחֵלֶב, כִּי נִכָּר הוּא. וְהָרַב כָּתַב בְּמוֹרֶה הַנְּבֻכִים (ג מו) כִּי הָיוּ הַכַּשְׂדִּים מוֹאֲסִים הַדָּם וְיַחְשְׁבוּהוּ לָהֶם לְטֻמְאָה, אֲבָל יֹאכְלוּ מִמֶּנּוּ הָרוֹצִים לְהִתְחַבֵּר לַשֵּׁדִים וּלְהִנָּבֵא מֵהֶם הָעֲתִידוֹת, וְהַתּוֹרָה תְּכַוֵּן לְעוֹלָם לַהֲרֹס בִּנְיְנֵי סִכְלוּתָם בְּהִפּוּךְ מַחְשְׁבוֹתֵיהֶם, וּלְכָךְ אָסְרָה הַדָּם בַּאֲכִילָה וּבָחֲרָה בּוֹ לְהִטַּהֵר בַּהַזָּאוֹת וּלְזָרְקוֹ עַל הַמִּזְבֵּחַ לְכַפָּרָה. וּלְכָךְ אָמַר (ויקרא י"ז:י') "וְנָתַתִּי פָנַי בַּנֶּפֶשׁ הָאֹכֶלֶת אֶת הַדָּם" כְּמוֹ שֶׁאָמַר בְּנוֹתֵן מִזַּרְעוֹ לַמֹּלֶךְ (ויקרא כ':ו') שֶׁהוּא מֵבִיא לְמִין מִמִּינֵי ע"ז, כִּי לֹא נֶאֱמַר כֵּן בְּמִצְוָה אַחֶרֶת. וְאֵלּוּ דְּבָרִים מְיֻשָּׁבִים, אֲבָל הַכְּתוּבִים לֹא יוֹרוּ כֵן, שֶׁהֵם יֹאמְרוּ תָּמִיד בְּטַעַם הָאִסּוּר "כִּי נֶפֶשׁ כָּל בָּשָׂר דָּמוֹ בְנַפְשׁוֹ" (ויקרא י"ז:י"ד), "כִּי נֶפֶשׁ הַבָּשָׂר בַּדָּם הִוא" (ויקרא י"ז:י"א), וְהֶחְזִיר בְּמִשְׁנֵה תּוֹרָה (דברים יב כג) "רַק חֲזַק לְבִלְתִּי אֲכֹל הַדָּם כִּי הַדָּם הוּא הַנָּפֶשׁ וְלֹא תֹאכַל הַנֶּפֶשׁ עִם הַבָּשָׂר". וְהָרָאוּי שֶׁנְּפָרֵשׁ בְּטַעַם אִסּוּרוֹ, כִּי הַשֵּׁם בָּרָא כָּל הַנִּבְרָאִים הַתַּחְתּוֹנִים לְצֹרֶךְ הָאָדָם, כִּי הוּא לְבַדּוֹ בָּהֶם מַכִּיר אֶת בּוֹרְאוֹ, וְאַף ע"פ כֵן לֹא הִתִּיר לָהֶם בַּאֲכִילָה מִתְּחִלָּה רַק הַצּוֹמֵחַ, לֹא בַּעֲלֵי הַנֶּפֶשׁ, כַּאֲשֶׁר בָּא בְּפָרָשַׁת בְּרֵאשִׁית, שֶׁנֶּאֱמַר (בראשית א כט) "הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זֹרֵעַ זֶרַע" וגו'. וְכַאֲשֶׁר הָיָה בַּמַּבּוּל שֶׁנִּצּוֹלוֹ בִּזְכוּתוֹ שֶׁל נֹחַ וְהִקְרִיב מֵהֶם קָרְבָּן וְהָיָה לְרָצוֹן לוֹ, הִתִּיר לָהֶם הַשְּׁחִיטָה, כְּמוֹ שֶׁאָמַר (שם ט ג) "כָּל רֶמֶשׂ אֲשֶׁר הוּא חַי לָכֶם יִהְיֶה לְאָכְלָה כְּיֶרֶק עֵשֶׂב נָתַתִּי לָכֶם אֶת כֹּל", כִּי חַיּוּתָם בַּעֲבוּר הָאָדָם. וְהִנֵּה הִתִּיר גּוּפָם אֲשֶׁר הוּא חַי בַּעֲבוּר הָאָדָם, שֶׁיִּהְיֶה לַהֲנָאָתוֹ וּלְצָרְכּוֹ שֶׁל אָדָם, וְשֶׁתִּהְיֶה הַנֶּפֶשׁ שֶׁבָּהֶם לְכַפָּרָה לָאָדָם בַּקְּרֵבִים לְפָנָיו יִתְבָּרַךְ, לֹא שֶׁיֹּאכְלוּהוּ, כִּי אֵין רָאוּי לְבַעַל נֶפֶשׁ שֶׁיֹּאכַל נֶפֶשׁ, כִּי הַנְּפָשׁוֹת כֻּלָּן לָאֵל הֵנָּה, כְּנֶפֶשׁ הָאָדָם וּכְנֶפֶשׁ הַבְּהֵמָה לוֹ הֵנָּה, וּמִקְרֶה אֶחָד לָהֶם, כְּמוֹת זֶה כֵּן מוֹת זֶה, וְרוּחַ אֶחָד לַכֹּל (קהלת ג יט). וְעַל הַדֶּרֶךְ שֶׁיִּרְאוּהוּ חוֹקְרֵי הַיְּוָנִים, מִן הַשֵּׂכֶל הַפּוֹעֵל הִתְנוֹצֵץ זִיו וְזֹהַר צַח מְאֹד וּבָהִיר, וּמִמֶּנּוּ יָצָא נִיצוֹץ נֶפֶשׁ הַבְּהֵמָה, וְהִנֵּה הִיא נֶפֶשׁ גְּמוּרָה בְּצַד מִן הַפָּנִים, וּלְכָךְ יֵשׁ בָּהּ דַּעַת לִבְרֹחַ מִן הַנֶּזֶק וְלָלֶכֶת אַחֲרֵי הַנָּאוֹת לָהּ, וְהֶכֵּר בָּרְגִילִים וְאַהֲבָה לָהֶם, כְּאַהֲבַת הַכְּלָבִים לְבַעֲלֵיהֶן וְהֶכֵּר מֻפְלָא בְּאַנְשֵׁי בֵּית בַּעֲלֵיהֶם, וְכֵן לַיּוֹנִים דַּעַת וְהַכָּרָה. מִן הַיָּדוּעַ עוֹד כִּי הַנֶּאֱכָל יָשׁוּב בְּגוּף הָאוֹכֵל וְהָיוּ לְבָשָׂר אֶחָד, וְאִם יֹאכַל אָדָם נֶפֶשׁ כָּל בָּשָׂר וְהוּא יִתְחַבֵּר בְּדָמוֹ וְהָיוּ לַאֲחָדִים בַּלֵּב, תִּהְיֶה עֹבִי וְגַסּוּת בְּנֶפֶשׁ הָאָדָם וְתָשׁוּב קָרוֹב לְטֶבַע הַנֶּפֶשׁ הַבַּהֲמִית אֲשֶׁר בַּנֶּאֱכָל, כִּי הַדָּם לֹא יִצְטָרֵךְ עִכּוּל כִּשְׁאָר הַנֶּאֱכָלִים שֶׁיִּשְׁתַּנּוּ בְּעִכּוּלָם, וְיִתָּלֶה בּוֹ נֶפֶשׁ הָאָדָם בְּדַם בְּהֵמָה, וְהַכָּתוּב אוֹמֵר (שם שם כא) "מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ". וּלְכָךְ אָמַר (ויקרא י"ז:י"ד) "כִּי נֶפֶשׁ כָּל בָּשָׂר דָּמוֹ בְנַפְשׁוֹ הוּא", כִּי לְכָל בָּשָׂר בָּאָדָם וּבַבְּהֵמָה נֶפֶשׁ בַּדָּם, וְאֵין רָאוּי לְעָרֵב הַנֶּפֶשׁ הַנִּכְרֶתֶת בַּנֶּפֶשׁ הַקַּיֶּמֶת, אֲבָל תִּהְיֶה לָהּ כַּפָּרָה עַל הַמִּזְבֵּחַ לְרָצוֹן לִפְנֵי ה'. וְזֶה טַעַם "עַל כֵּן אָמַרְתִּי לִבְנֵי יִשְׂרָאֵל", בַּעֲבוּר שֶׁהַדָּם הוּא הַנֶּפֶשׁ וְאֵין רָאוּי שֶׁתֹּאכַל הַנֶּפֶשׁ אֶת הַנֶּפֶשׁ, וַאֲנִי חָמַלְתִּי עַל נֶפֶשׁ הָאָדָם וּנְתַתִּיו לָהֶם עַל הַמִּזְבֵּחַ שֶׁתִּהְיֶה נֶפֶשׁ הַבְּהֵמָה מְכַפֶּרֶת עַל נַפְשׁוֹ. וְשָׁנוּ בְּסִפְרֵי (ראה עו), "רַק חֲזַק לְבִלְתִּי אֲכֹל הַדָּם" (דברים יב כג), רַבִּי יְהוּדָה אוֹמֵר, מַגִּיד שֶׁהָיוּ שְׁטוּפִים בַּדָּם וכו', "כִּי הַדָּם הוּא הַנָּפֶשׁ" (שם), לְהַגִּיד מָה גָּרַם, "וְלֹא תֹאכַל הַנֶּפֶשׁ עִם הַבָּשָׂר" (שם) זֶה אֵבֶר מִן הַחַי. זֶה רֶמֶז וּרְאָיָה לְמָה שֶׁפֵּרַשְׁנוּ. וּלְכָךְ צִוָּה עוֹד (ויקרא י"ז:י"ג) לְכַסּוֹת כָּל דָּם בַּחַיָּה וּבָעוֹף, כִּי לֹא יִתְקָרֵב דָּמָם עַל הַמִּזְבֵּחַ, כִּי גַּם בָּעוֹפוֹת לֹא יִקְרַב מֵהֶם רַק שְׁנֵי מִינִין בִּלְבַד, וְגַם הֵם אֵינָם נִשְׁחָטִים, אֲבָל בַּבְּהֵמוֹת רֹב הַמְּצוּיִים נִשְׁחָטִים לַשֵּׁם הַנִּכְבָּד וְדָמָם לְכַפֵּר, וְאֵין רָאוּי לְכַסּוֹתוֹ. וְלֹא חָשַׁשׁ לְכַסּוֹת דַּם הַחֻלִּין בִּבְהֵמָה כִּי אֵין חֻלִּין בַּמִּדְבָּר, וְגַם אַחֲרֵי כֵן עַל הָרֹב יְצַוֶּה:
@48 **דָּמוֹ בְנַפְשׁוֹ הוּא** דָּמוֹ לוֹ בִּמְקוֹם נֶפֶשׁ, כִּי הַנֶּפֶשׁ תְּלוּיָה בּוֹ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ז:י"ד). וְאֵינֶנּוּ נָכוֹן, אֲבָל אֶפְשָׁר לְפָרֵשׁ שֶׁיִּהְיֶה "בְנַפְשׁוֹ" בְּכָאן - בְּגוּפוֹ, יֹאמַר כִּי נֶפֶשׁ כָּל בָּשָׂר דָּמוֹ בְּגוּפוֹ הוּא. וְכֵן "בַּרְזֶל בָּאָה נַפְשׁוֹ" (תהלים קה יח), "שִׁבְעִים נָפֶשׁ" (שמות א ה), "עַל נֶפֶשׁ מֵת לֹא יָבֹא" (במדבר ו ו), הַגּוּף, כִּי גּוּף בַּעַל נֶפֶשׁ יִקָּרֵא נֶפֶשׁ. וְעַל דַּעְתִּי הִזְכִּיר הַכָּתוּב בַּדָּם שְׁלֹשָׁה דְּבָרִים וְהֵם טַעַם אֶחָד: אָמַר תְּחִלָּה (ויקרא י"ז:י"א) "כִּי נֶפֶשׁ הַבָּשָׂר בַּדָּם הִיא"; אַחַר כָּךְ הָפַךְ וְאָמַר "כִּי נֶפֶשׁ כָּל בָּשָׂר דָּמוֹ בְנַפְשׁוֹ הוּא", לוֹמַר כִּי הַדָּם הוּא הַנָּפֶשׁ וְהַנֶּפֶשׁ הִיא בַּדָּם שֶׁשְּׁנֵיהֶם מְעֹרָבִין יַחַד, וְיִהְיֶה זֶה כְּעִנְיַן יַיִן הַמָּזוּג בְּמַיִם, שֶׁהַמַּיִם בַּיַּיִן וְהַיַּיִן בַּמַּיִם כָּל אֶחָד בַּחֲבֵרוֹ; וְאח"כ פֵּרֵשׁ "כִּי הַדָּם הוּא הַנָּפֶשׁ" עַצְמוֹ, לוֹמַר שֶׁהָיוּ לְבָשָׂר אֶחָד לֹא יִתְפָּרְדוּ, לֹא יִמָּצֵא דָּם בְּלֹא נֶפֶשׁ וְלֹא נֶפֶשׁ בְּלֹא דָּם, כַּיָּדוּעַ בָּרוּחַ אֲשֶׁר תְּחִלָּתוֹ מִן הַלֵּב שֶׁהוּא הִיּוּלִי לָרוּחוֹת כֻּלָּן, וּמִמֶּנּוּ יָבֹא הַזָּן שֶׁעוֹשֶׂה הַדָּם, וְהַדָּם הוּא הַמּוֹלִידוֹ וְהַמְּקַיְּמוֹ, כְּעִנְיַן הַגֹּלֶם וְהַצּוּרָה בְּכָל בַּעֲלֵי הַגּוּף, שֶׁלֹּא יִמָּצֵא הָאֶחָד בִּלְתִּי הָאַחֵר. וְרַבּוֹתֵינוּ דָּרְשׁוּ (כריתות ד), שְׁלֹשָׁה כְּרֵיתוֹת בַּדָּם, אַחַת לְדַם הַנֶּפֶשׁ וְאַחַת לְדַם שְׁחִיטָה וְאַחַת לְדַם כִּסּוּי, וְזֶה טַעְמָם לַכְּרֵיתוֹת, אֲבָל הַטַּעַם בְּשִׁנּוּי הַלָּשׁוֹן בַּנֶּפֶשׁ וּבַדָּם כַּאֲשֶׁר פֵּרַשְׁתִּי:
@52 אָמַר בָּעֲרָיוֹת **דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל** בִּלְבַד, בַּעֲבוּר הֱיוֹת אַזְהָרַת הָעֲרָיוֹת שָׁוָה בְּכָל יִשְׂרָאֵל, לֹא יִתְיַחֲדוּ בָּהּ הַכֹּהֲנִים, וְלָכֵן כְּלָלָם כְּאֶחָד. וְאָמַר בַּתְּחִלָּה "אֲנִי ה' אֱלֹהֵיכֶם" כַּטַּעַם בַּעֲשֶׂרֶת הַדִּבְּרוֹת (שמות כ ב). וְטַעַם "דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵיהֶם אֲנִי ה' אֱלֹהֵיכֶם", כְּאִלּוּ הוּא אוֹמֵר "וְאָמַרְתָּ אֲלֵיהֶם בִּשְׁמִי אֲנִי ה' אֱלֹהֵיכֶם". וְכֵן "קְדֹשִׁים תִּהְיוּ כִּי קָדוֹשׁ אֲנִי ה' אֱלֹהֵיכֶם" (ויקרא י"ט:ב'). וְאֶפְשָׁר כִּי הַטַּעַם כִּי בְּצֵאת מֹשֶׁה מִלִּפְנֵי הַשֵּׁם בְּלֹא מַסְוֶה וְיָצָא וְדִבֶּר אֶל בְּנֵי יִשְׂרָאֵל אֵת אֲשֶׁר יְצֻוֶּה, אֵינֶנּוּ צָרִיךְ לוֹמַר לָהֶם "כֹּה אָמַר ה'", כִּי יָדוּעַ לָהֶם כִּי רוּחוֹ יְדַבֵּר בּוֹ וּמִלָּתוֹ עַל לְשׁוֹנוֹ, לֹא יְדַבֵּר מֵעַצְמוֹ. וְכֵן בִּמְקוֹמוֹת רַבִּים בְּמִשְׁנֵה תּוֹרָה כָּךְ יְדַבֵּר, כְּמוֹ "וְהָיָה אִם שָׁמֹעַ תִּשְׁמְעוּ אֶל מִצְוֹתַי אֲשֶׁר אָנֹכִי מְצַוֶּה אֶתְכֶם הַיּוֹם וְנָתַתִּי מְטַר אַרְצְכֶם וְנָתַתִּי עֵשֶׂב בְּשָׂדְךָ" (דברים יא יג טו), וְאֵין מֹשֶׁה הַנֹּתֵן מָטָר עַל פְּנֵי אָרֶץ וְשֹׁלֵחַ מַיִם עַל פְּנֵי חוּצוֹת וּמַצְמִיחַ עֵשֶׂב בַּשָּׂדֶה, אֶלָּא ה' יִתְבָּרַךְ. וְכֵן "וְלֹא נָתַן ה' לָכֶם לֵב לָדַעַת וָאוֹלֵךְ אֶתְכֶם בַּמִּדְבָּר לֶחֶם לֹא אֲכַלְתֶּם וְיַיִן וְשֵׁכָר לֹא שְׁתִיתֶם לְמַעַן תֵּדְעוּ כִּי אֲנִי ה' אֱלֹהֵיכֶם" (שם כט ג-ה). וְטַעַם "לְאַהֲבָה אֶת ה' אֱלֹהֵיכֶם" כְּבָר נִתְפָּרֵשׁ (שמות כד א):
@53 וְעַל דַּעַת ר"א הִזְכִּיר **כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם** עַל הַשְּׂעִירִים הַנִּזְכָּרִים. "וּכְמַעֲשֵׂה אֶרֶץ כְּנַעַן" עַל הָעֲרָיוֹת, שֶׁהָיוּ הַכְּנַעֲנִים בָּהֶם רָעִים וְחַטָּאִים, כַּאֲשֶׁר אָמַר בַּסּוֹף (ויקרא י"ח:כ"ז), "כִּי אֶת כָּל הַתּוֹעֵבֹת הָאֵל עָשׂוּ אַנְשֵׁי הָאָרֶץ". וְעַל דַּעַת רַבּוֹתֵינוּ בְּתוֹרַת כֹּהֲנִים (אחרי ט ג), הָיוּ גַּם הַמִּצְרִים שְׁטוּפִים בְּזִמָּה, בְּכָל הָעֲרָיוֹת וּבְזָכוּר וּבִבְהֵמָה, וְהוּא הָאֱמֶת, כִּי גַּם קָדֵשׁ הָיָה בָּאָרֶץ בִּזְכוּר מֵאָז וְעַד עַתָּה, וְהַכָּתוּב מֵעִיד בָּהֶן "בְּנֵי מִצְרַיִם שְׁכֵנַיִךְ גִּדְלֵי בָשָׂר" (יחזקאל טז כו), וְאוֹמֵר "אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם וְזִרְמַת סוּסִים זִרְמָתָם" (שם כג כ), וְהַבָּשָׂר - כִּנּוּי, וְכֵן "זָב מִבְּשָׂרוֹ" (ויקרא ט"ו:ב') "דָּם יִהְיֶה זֹבָהּ בִּבְשָׂרָהּ" (שם פסוק יט):
@54 **אֶת מִשְׁפָּטַי תַּעֲשׂוּ** אֵלּוּ דְּבָרִים הָאֲמוּרִים בַּתּוֹרָה שֶׁאִלּוּ לֹא נֶאֶמְרוּ בַּדִּין הָיָה לְאָמְרָן, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ח:ד'). וּבְתוֹרַת כֹּהֲנִים (פרק יג ט), אֵלּוּ דְּבָרִים הַכְּתוּבִים בַּתּוֹרָה שֶׁאִלּוּלֵי לֹא נִכְתְּבוּ בַּדִּין הָיָה לְכָתְבָן, כְּגוֹן הַגְּזֵלוֹת וְהָעֲרָיוֹת וַעֲבוֹדָה זָרָה וּשְׁפִיכוּת דָּמִים וְקִלְלַת הַשֵּׁם. וְעַל דֶּרֶךְ הַפְּשָׁט "מִשְׁפָּטַי" כְּמַשְׁמָעָן, הַדִּינִין הָאֲמוּרִים בְּפָרָשַׁת וְאֵלֶּה הַמִּשְׁפָּטִים וּבְכָל הַתּוֹרָה, וּלְכָךְ יֹאמַר "אֲשֶׁר יַעֲשֶׂה אֹתָם הָאָדָם וָחַי בָּהֶם", כִּי הַדִּינִים נִתְּנוּ לְחַיֵּי הָאָדָם בְּיִשּׁוּב הַמְּדִינוֹת וּשְׁלוֹם הָאָדָם, וְשֶׁלֹּא יַזִּיק אִישׁ אֶת רֵעֵהוּ וְלֹא יְמִיתֶנּוּ. וְכֵן יְחֶזְקֵאל הִזְכִּיר פְּעָמִים רַבּוֹת בַּמִּשְׁפָּטִים "אֲשֶׁר יַעֲשֶׂה אֹתָם הָאָדָם וָחַי בָּהֶם" (יחזקאל כ יא יג כא), וּבַשַּׁבָּתוֹת אוֹמֵר (שם פסוק יב) "לִהְיוֹת לְאוֹת בֵּינִי וּבֵינֵיהֶם", וְכֵן בִּנְחֶמְיָה (ט כט) "וּבְמִשְׁפָּטֶיךָ חָטְאוּ בָם אֲשֶׁר יַעֲשֶׂה אָדָם וְחָיָה בָהֶם". וְרַבּוֹתֵינוּ אָמְרוּ (יומא פה) "וָחַי בָּהֶם" - וְלֹא שֶׁיָּמוּת בָּהֶם, לְלַמֵּד עַל פִּקּוּחַ נֶפֶשׁ שֶׁדּוֹחֶה אֶת הַשַּׁבָּת וְהַמִּצְוֹת. וּמִדְרָשׁוֹ (תו"כ פרשה ט י) "וָחַי בָּהֶם" - לָעוֹלָם הַבָּא, אִם תֹּאמַר בָּעוֹלָם הַזֶּה, וַהֲלֹא סוֹפוֹ הוּא מֵת. וְאִם כֵּן יַחְזֹר "אֲשֶׁר יַעֲשֶׂה אֹתָם הָאָדָם" גַּם עַל חֻקּוֹתַי. וְדַע כִּי חַיֵּי הָאָדָם בַּמִּצְוֹת כְּפִי הֲכָנָתוֹ לָהֶם, כִּי הָעוֹשֶׂה הַמִּצְוֹת שֶׁלֹּא לִשְׁמָן עַל מְנָת לְקַבֵּל פְּרָס יִחְיֶה בָּהֶן בָּעוֹלָם הַזֶּה יָמִים רַבִּים בְּעֹשֶׁר וּבִנְכָסִים וְכָבוֹד. וְעַל זֶה נֶאֱמַר (משלי ג טז) "בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד", וּפֵרְשׁוּ (שבת סג) לַמַּשְׂמְאִילִים בָּהּ עֹשֶׁר וְכָבוֹד. וְכֵן אוֹתָם אֲשֶׁר הֵם מִתְעַסְּקִין בַּמִּצְוֹת עַל מְנָת לִזְכּוֹת בָּהֶן לָעוֹלָם הַבָּא, שֶׁהֵם הָעוֹבְדִים מִיִּרְאָה, זוֹכִים בְּכַוָּנָתָם לְהִנָּצֵל מִמִּשְׁפְּטֵי הָרְשָׁעִים, וְנַפְשָׁם בְּטוֹב תָּלִין. וְהָעוֹסְקִין בַּמִּצְוֹת מֵאַהֲבָה כַּדִּין וְכָרָאוּי עִם עִסְקֵי הָעוֹלָם הַזֶּה, כָּעִנְיָן הַנִּזְכָּר בַּתּוֹרָה בְּפָרָשַׁת אִם בְּחֻקּוֹתַי (ויקרא כ"ו:ה') "וְהִשִּׂיג לָכֶם דַּיִשׁ אֶת בָּצִיר" וְגוֹ' - יִזְכּוּ בָּעוֹלָם הַזֶּה לְחַיִּים טוֹבִים כְּמִנְהַג הָעוֹלָם, וּלְחַיֵּי הָעוֹלָם הַבָּא זְכוּתָם שְׁלֵמָה שָׁם. וְהָעוֹזְבִים כָּל עִנְיְנֵי הָעוֹלָם הַזֶּה וְאֵינָם מַשְׁגִּיחִים עָלָיו, כְּאִלּוּ אֵינָם בַּעֲלֵי גּוּף, וְכָל מַחְשַׁבְתָּם וְכַוָּנָתָם בְּבוֹרְאָם בִּלְבַד, כַּאֲשֶׁר הָיָה הָעִנְיָן בְּאֵלִיָּהוּ, בְּהִדָּבֵק נַפְשָׁם בַּשֵּׁם הַנִּכְבָּד יִחְיוּ לָעַד בְּגוּפָם וּבְנַפְשָׁם, כַּנִּרְאֶה בַּכָּתוּב בְּאֵלִיָּהוּ וְכַיָּדוּעַ מִמֶּנּוּ בַּקַּבָּלָה, וּכְמוֹ שֶׁבָּא בַּמִּדְרָשִׁים בַּחֲנוֹךְ וּבִבְנֵי הָעוֹלָם הַבָּא הָעוֹמְדִים בִּתְחִיַּת הַמֵּתִים. וּלְכָךְ יֹאמְרוּ הַכְּתוּבִים בִּשְׂכַר הַמִּצְוֹת "לְמַעַן יַאֲרִיכוּן יָמֶיךָ" (שמות כ יב), "לְמַעַן תִּחְיֶה" (דברים טז כ), "וְהַאֲרַכְתָּ יָמִים" (שם כב ז), כִּי הַלָּשׁוֹן יִכְלֹל מִינֵי הַחַיִּים כֻּלָּם כְּפִי הָרָאוּי לְכָל אֶחָד:
@56 **אֶל כָּל שְׁאֵר בְּשָׂרוֹ לֹא תִקְרְבוּ לְגַלּוֹת עֶרְוָה** טַעַם אִסּוּר הָעֲרָיוֹת בִּשְׁאֵר הַבָּשָׂר אֵינֶנּוּ מְפֹרָשׁ. וְהָרַב אָמַר בְּמוֹרֶה הַנְּבֻכִים (ג מט) כִּי הוּא לְמַעֵט הַמִּשְׁגָּל וְלִמְאֹס אוֹתוֹ וּלְהִסְתַּפֵּק מִמֶּנּוּ בִּמְעַט. וְהַנָּשִׁים הָאֵלֶּה אֲשֶׁר אָסַר הַכָּתוּב בִּשְׁאֵר הָאִשָּׁה הֵן הַמְּצוּיוֹת עִמּוֹ תָּמִיד, וְכֵן בַּשְּׁאֵר עַצְמוֹ מְצוּיוֹת לוֹ וְהוּא נִסְתָּר עִמָּהֶן. וְכַטַּעַם הַזֶּה יַגִּיד הָרַב עַל כֻּלָּן. וּכְבָר כָּתַב ר"א (אבן עזרא על ויקרא י"ח:ו') גַּם כֵּן כִּי בַּעֲבוּר הֱיוֹת יֵצֶר לֵב הָאָדָם כַּבְּהֵמוֹת, לֹא יִתָּכֵן לֶאֱסֹר כָּל הַנְּקֵבוֹת, וְהִנֵּה אָסַר כָּל הַנִּמְצָאוֹת עִמּוֹ בְּכָל שָׁעָה. וְזֶה טַעַם חָלוּשׁ מְאֹד שֶׁיְּחַיֵּב הַכָּתוּב כָּרֵת עַל אֵלֶּה בַּעֲבוּר הִמָּצְאָן עִמּוֹ לִפְעָמִים, וּמַתִּיר שֶׁיִּשָּׂא אָדָם נָשִׁים רַבּוֹת לְמֵאוֹת וְלַאֲלָפִים, וּמַה יַזִּיק אִם יִשָּׂא אֶת בִּתּוֹ לְבַדָּהּ כַּמֻּתָּר לִבְנֵי נֹחַ (סנהדרין נח), וְיִשָּׂא שְׁתֵּי אֲחָיוֹת כְּיַעֲקֹב אָבִינוּ, וְאֵין לָאָדָם נִשּׂוּאִים הֲגוּנִים כְּמוֹ שֶׁיַּשִּׂיא אֶת בִּתּוֹ לִבְנוֹ הַגָּדוֹל מִמֶּנָּה וְיַנְחִילֵם בְּנַחֲלָתוֹ וְיִפְרוּ וְיִרְבּוּ בְּבֵיתוֹ, כִּי הָאָרֶץ לֹא תֹהוּ בְרָאָהּ לָשֶׁבֶת יְצָרָהּ. וְאֵין בְּיָדֵנוּ דָּבָר מְקֻבָּל בָּזֶה, אֲבָל כְּפִי הַסְּבָרָא יֵשׁ בָּעִנְיָן סוֹד מִסּוֹדוֹת הַיְּצִירָה דָּבֵק בַּנֶּפֶשׁ, וְהוּא מִכְּלַל סוֹד הָעִבּוּר שֶׁכְּבָר רָמַזְנוּ לוֹ. וְדַע כִּי הַמִּשְׁגָּל דָּבָר מְרֻחָק וְנִמְאָס בַּתּוֹרָה זוּלָתִי לְקִיּוּם הַמִּין, וַאֲשֶׁר לֹא יִוָּלֵד מִמֶּנּוּ הוּא אָסוּר, וְכֵן אֲשֶׁר אֵינֶנּוּ טוֹב בַּקִּיּוּם וְלֹא יִצְלַח בּוֹ, תֶּאֱסֹר אוֹתוֹ הַתּוֹרָה. זֶה טַעַם "אֶל כָּל שְׁאֵר בְּשָׂרוֹ" (כאן) "כִּי אֶת שְׁאֵרוֹ הֶעֱרָה" (ויקרא כ':י"ט), יַרְחִיק הַדָּבָר מִפְּנֵי הַשְּׁאֵר, וְהַלָּשׁוֹן נִגְזָר מִן "הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלִַם" (ישעיהו ד ג), וּלְכָךְ יֹאמַר "שַׁאֲרָה הֵנָּה זִמָּה הִיא" (ויקרא י"ח:י"ז), כְּלוֹמַר אֵינָם נִשּׂוּאִין וְאִישׁוּת כִּי לֹא יַצְלִיחַ, אֲבָל הִיא זִמָּה, מַחֲשֶׁבֶת תַּאֲוָה בִּלְבַד. וְהִנֵּה הָעֲרָיוֹת מִכְּלַל הַחֻקִּים, דְּבָרִים שֶׁהֵם גְּזֵרַת מֶלֶךְ, וְהַגְּזֵרָה הוּא הַדָּבָר הָעוֹלֶה עַל דַּעַת הַמֶּלֶךְ שֶׁהוּא הֶחָכָם בְּהַנְהָגַת מַלְכוּתוֹ, וְהוּא הַיּוֹדֵעַ הַצֹּרֶךְ וְהַתּוֹעֶלֶת בַּמִּצְוָה הַהִיא שֶׁיְּצַוֶּה בָּהּ, וְלֹא יַגִּיד אוֹתוֹ לָעָם זוּלָתִי לְחַכְמֵי יוֹעֲצָיו:
@57 **עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ** לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ח:ז'), "עֶרְוַת אָבִיךָ" זוֹ אֵשֶׁת אָבִיךָ. "וְעֶרְוַת אִמְּךָ" לְהָבִיא אִמּוֹ שֶׁאֵינָהּ אֵשֶׁת אָבִיו. "עֶרְוַת אֵשֶׁת אָבִיךָ" לְרַבּוֹת לְאַחַר מִיתָה. וְכֵן פֵּרֵשׁ "עֶרְוַת אֲחִי אָבִיךָ לֹא תְגַלֵּה" (ויקרא י"ח:י"ד), וּמַהוּ עֶרְוָתוֹ, אֶל אִשְׁתּוֹ לֹא תִקְרָב. וְכֵן הוּא בֶּאֱמֶת כְּפִי מַשְׁמָעוּתוֹ הַנָּכוֹן. אֲבָל בַּגְּמָרָא בְּמַסֶּכֶת סַנְהֶדְרִין (סנהדרין נ"ד) הֶעֱלוּ כִּי "עֶרְוַת אָבִיךָ" וְ"עֶרְוַת אֲחִי אָבִיךָ" עַל הַזְּכָרִים מַמָּשׁ, וּלְחַיְּבוֹ בְּשׁוֹגֵג שְׁתַּיִם. וַאֲנִי תָּמֵהַּ לְדַעְתָּם, לָמָּה לֹא יַזְהִיר כֵּן בְּבֵן וּבְאָח עִם עֶרְוַת נְשֵׁיהֶם, וְאוּלַי חָשְׁשָׁה הַתּוֹרָה בִּכְבוֹד הַזְּקֵנִים יוֹתֵר. אֲבָל כָּל פָּסוּק וּפָסוּק בַּפָּרָשָׁה אַזְהָרָה אַחַת, לֹא בָּאוּ בַּפָּרָשָׁה שְׁתֵּי אַזְהָרוֹת בְּלָאו אֶחָד, כִּי הַלָּאו בָּאֲחָיוֹת כֻּלָּן וְכֵן הַבָּנוֹת אַחַת הֵנָּה. וְהַנָּכוֹן בְּעֵינַי עַל דֶּרֶךְ הַפְּשָׁט, כִּי עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לָאו אֶחָד הוּא וְאַזְהָרָה אַחַת, יִמְנַע שֶׁלֹּא יָבֹא עַל אִמּוֹ, כִּי בְּבוֹאוֹ עָלֶיהָ יְגַלֶּה עֶרְוַת אָבִיו וְעֶרְוַת אִמּוֹ. וְזֶהוּ שֶׁאָמַר (כאן) "אִמְּךָ הִיא", כִּי עָשִׂיתָ בָּהּ שְׁתַּיִם רָעוֹת, שֶׁגִּלִּיתָ עֶרְוַת אֵם וְעֶרְוַת אָב. וְאַחֲרֵי שֶׁהִזְהִיר עַל עֶרְוַת אָבִיו שֶׁהִיא אִמּוֹ, חָזַר וְהִזְהִיר עַל עֶרְוַת אֵשֶׁת אָבִיו שֶׁאֵינָהּ אִמּוֹ, וְאָמַר (ויקרא י"ח:ח') "עֶרְוַת אֵשֶׁת אָבִיךָ לֹא תְגַלֵּה עֶרְוַת אָבִיךָ הִיא". וְכֵן "עֶרְוַת אֲחִי אָבִיךָ לֹא תְגַלֵּה" פֵּרוּשׁוֹ "אֶל אִשְׁתּוֹ לֹא תִקְרָב", וּלְכָךְ לֹא אָמַר "וְאֶל":
@59 **מוֹלֶדֶת בַּיִת אוֹ מוֹלֶדֶת חוּץ** בֵּין שֶׁאוֹמְרִים לְאָבִיךָ קַיֵּם אֶת אִמָּהּ, בֵּין שֶׁאוֹמְרִים לְאָבִיךָ הוֹצֵא אֶת אִמָּהּ, כְּגוֹן מַמְזֶרֶת אוֹ נְתִינָה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ח:ט'). וְאֵינוֹ נָכוֹן, כִּי יֵצֵא מִזֶּה שֶׁאֲחוֹתוֹ מִן הָעֲרָיוֹת לֹא תִּהְיֶה בִּכְלַל הָאִסּוּר הַזֶּה, וְהֵן כֻּלָּן בְּכָרֵת חוּץ מִן הַנּוֹלֶדֶת מִשִּׁפְחָה וְנָכְרִית. וַאֲנִי תָּמֵהַּ עַל הָרַב, שֶׁהֲרֵי בַּגְּמָרָא בְּמַסֶּכֶת יְבָמוֹת בְּפֶרֶק שֵׁנִי (כג) מְפֹרָשׁ, וְאֵימָא פְּרָט לַאֲחוֹתוֹ מֵחַיָּבֵי לָאוִין, אָמַר רַב פַּפָּא, חַיָּבֵי לָאוִין תָּפְסֵי בְּהוּ קִדּוּשִׁין, דִּכְתִיב (דברים כא טו) "כִּי תִהְיֶיןָ לְאִישׁ שְׁתֵּי נָשִׁים הָאַחַת אֲהוּבָה וְהָאַחַת שְׂנוּאָה", וְכִי יֵשׁ אֲהוּבָה לִפְנֵי הַמָּקוֹם וְיֵשׁ שְׂנוּאָה לִפְנֵי הַמָּקוֹם, אֶלָּא אֲהוּבָה - אֲהוּבָה בְּנִשּׂוּאֶיהָ, שְׂנוּאָה - שְׂנוּאָה בְּנִשּׂוּאֶיהָ, וְאָמַר רַחֲמָנָא "כִּי תִהְיֶיןָ לְאִישׁ". וְאֵימָא, פְּרָט לַאֲחוֹתוֹ מֵחַיָּבֵי כְּרֵיתוֹת, אָמַר רָבָא, אֲמַר קְרָא (כאן) "עֶרְוַת אֲחוֹתְךָ בַת אָבִיךָ אוֹ בַת אִמֶּךָ מוֹלֶדֶת בַּיִת אוֹ מוֹלֶדֶת חוּץ" - בֵּין שֶׁאוֹמְרִין לְאָבִיךָ קַיָּם בֵּין שֶׁאוֹמְרִין לְאָבִיךָ הוֹצֵא, וְאָמַר רַחֲמָנָא "אֲחוֹתְךָ הִיא". וְהִנֵּה פֵּרוּשׁוֹ שֶׁאוֹמְרִים לוֹ הוֹצֵא - שֶׁתּוֹצִיאֶנָּה מִבֵּיתְךָ, שֶׁאֵינָהּ אִשְׁתְּךָ וְאֵין קִדּוּשִׁין תּוֹפְסִין בָּהּ, שֶׁהֵם חַיָּבֵי כְּרֵיתוֹת וּמִיתוֹת בֵּית דִּין, וְאע"פ כֵּן חַיָּב עָלֶיהָ מִשּׁוּם אֲחוֹתוֹ. אֲבָל אֲחוֹתוֹ מִן הַשִּׁפְחָה וּמִן הַנָּכְרִית אֵינָהּ בִּכְלַל הָאִסּוּר הַזֶּה, מִפְּנֵי שֶׁהַוָּלָד כָּמוֹהָ. וְעַל דֶּרֶךְ הַפְּשָׁט יֹאמַר, עֶרְוַת אֲחוֹתְךָ בַת אָבִיךָ אוֹ בַת אִמֶּךָ מוֹלֶדֶת מִן הַנִּשּׂוּאִין, שֶׁהִכְנִיסָהּ הָאִישׁ לוֹ לַבַּיִת, אוֹ מוֹלֶדֶת חוּץ, שֶׁמָּצָא אִישׁ אוֹתָהּ בַּחוּץ וּתְפָשָׂהּ וְשָׁכַב עִמָּהּ וְיָלְדָה לוֹ - לֹא תְגַלֶּה עֶרְוָתָהּ. הִזְכִּיר בְּבַת אִמּוֹ בֵּין שֶׁתִּוָּלֵד מִן הַנִּשּׂוּאִין אוֹ מִן הַזְּנוּת, כִּי אע"פ שֶׁכָּל אַחַת מִשְּׁתֵּיהֶן בַּת אִמּוֹ וְלֹא בַּת אָבִיו, יַעֲלֶה עַל הַדַּעַת שֶׁרָאוּי לִנְהֹג כְּבוֹד הָאַחְוָה בַּמּוֹלֶדֶת מִן הַנִּשּׂוּאִין וְלֹא בַּבָּאִין מִן הַזְּנוּת, שֶׁהַכֹּל הֶפְקֵר. וּלְכָךְ הֻצְרַךְ הַכָּתוּב לְהַזְהִיר עַל הַכֹּל. וְעוֹד הִזְכִּיר בַּאֲחוֹתוֹ מִן הָאָב כָּתוּב אַחֵר (ויקרא י"ח:י"א) "עֶרְוַת בַּת אֵשֶׁת אָבִיךָ מוֹלֶדֶת אָבִיךָ", וְהִיא אֲחוֹתוֹ בַּת אָבִיו מִן הַנִּשּׂוּאִין, וְהֻצְרַךְ לְהַזְכִּיר זֶה בַּעֲבוּר שֶׁהִזְכִּיר "עֶרְוַת אֲחוֹתְךָ בַת אָבִיךָ" סְתָם, וּפֵרֵשׁ בְּבַת אִמּוֹ "מוֹלֶדֶת בַּיִת" בְּנִשּׂוּאִין "אוֹ מוֹלֶדֶת חוּץ" בִּזְנוּת, וְיֵחָשֵׁב מִזֶּה בְּבַת הָאָב מִן הַזְּנוּת שֶׁתִּהְיֶה מֻתֶּרֶת, כִּי אוּלַי לֹא תָּחוּשׁ הַתּוֹרָה לִשְׁאֵר הָאִישׁ הַבָּא מִן הַזְּנוּת, בַּעֲבוּר שֶׁאֵין הַנּוֹלָדִים יְדוּעִים לוֹ. וּלְכָךְ בֵּאֵר וְאָמַר "עֶרְוַת בַּת אֵשֶׁת אָבִיךָ מוֹלֶדֶת אָבִיךָ", לְהַגִּיד כִּי בַּת אָבִיו הַנִּזְכֶּרֶת בַּתְּחִלָּה אֵינָהּ בַּת אֵשֶׁת אָבִיו. וּבַעֲבוּר שֶׁהָיָה בִּבְנֵי נֹחַ אִסּוּר בָּאַחְוָה מִן הָאֵם וְלֹא מִן הָאָב (סנהדרין נח), יְפָרֵשׁ הַכָּתוּב כִּי בְּיִשְׂרָאֵל כֻּלָּן שָׁווֹת בָּאִסּוּר. וְהַנָּכוֹן בִּפְשַׁט הַכָּתוּב הַזֶּה מַה שֶׁאָמְרוּ חֲכָמִים בַּגְּמָרָא בְּמַסֶּכֶת יְבָמוֹת (יבמות כ"ב), הַבָּא עַל אֲחוֹתוֹ וְהִיא בַּת אֵשֶׁת אָבִיו שֶׁאֵינָהּ אִמּוֹ, חַיָּב מִשּׁוּם אֲחוֹתוֹ וּמִשּׁוּם בַּת אֵשֶׁת אָבִיו. וּמְפָרֵשׁ שָׁם, מִכְּדֵי כְּתִיב כָּאן "עֶרְוַת אֲחוֹתְךָ בַת אָבִיךָ", "בַּת אֵשֶׁת אָבִיךָ מוֹלֶדֶת אָבִיךָ" לָמָּה לִי, שְׁמַע מִנָּה לְחַיְּבָן מִשּׁוּם אֲחוֹתוֹ וּמִשּׁוּם בַּת אֵשֶׁת אָבִיו. וְיִכְפֹּל הַכָּתוּב בְּלָאוִין לְחַיֵּב עַל כָּל שֵׁם וָשֵׁם, כִּי אֲפִלּוּ בִּשְׁרָצִים יִכְפֹּל לָאוִין רַבִּים בְּשֵׁם אֶחָד לִלְקוֹת עֲלֵיהֶם:
@67 **זִמָּה הִיא** תִּרְגֵּם אוּנְקְלוֹס (תרגום אונקלוס על ויקרא י"ח:י"ז) "עֵצַת חֶטְאִין הִיא". וְכָתַב רַשִׁ"י (רש"י על ויקרא י"ח:י"ז), שֶׁיִּצְרְךָ יוֹעַצְךָ לַחְטֹא. וְלֹא יָדַעְתִּי טַעַם לָזֶה, שֶׁכָּל הָעֲרָיוֹת, גַּם הָעֲבֵרוֹת הָאֲחֵרוֹת, הַיֵּצֶר יוֹעֲצוֹ לַחְטֹא. אֲבָל הָעִנְיָן הוּא כִּי שֵׁם "זִמָּה" גָּזְרוּ מִן "כַּאֲשֶׁר זָמַם לַעֲשׂוֹת לְאָחִיו" (דברים יט יט), וְלַמַּחְשָׁבָה הַהֲגוּנָה יִקְרְאוּ "מְזִמָּה", "וְלֹא יִבָּצֵר מִמְּךָ מְזִמָּה" (איוב מב ב), וְלַזְּנוּת הֶעָשׂוּי בְּמַחְשָׁבָה בַּסֵּתֶר יִקָּרֵא "זִמָּה", כְּעִנְיַן "אִם נִפְתָּה לִבִּי עַל אִשָּׁה" (שם לא ט) וּכְתִיב (שם פסוק יא) "כִּי הִיא זִמָּה וְהוּא עָוֹן פְּלִילִים". וְכֵן "וְזִמָּתֵךְ וְתַזְנוּתָיִךְ" (יחזקאל כג כט), "וְזִמַּת זְנוּתֵךְ" (ירמיהו יג כז), הַנִּאוּף בַּסֵּתֶר וּבַגָּלוּי. וּלְפִי דַּעְתִּי אָמַר הַכָּתוּב "זִמָּה" בְּאִשָּׁה וּבְבִתָּהּ (כאן) וְאִשָּׁה וְאִמָּהּ (ויקרא כ':י"ד), לְגַנּוֹת הָעִנְיָן, לוֹמַר כִּי כְּשֶׁיִּשְׁכַּב עִם אַחַת שֶׁהִיא אִשְׁתּוֹ יַחְשֹׁב בָּאַחֶרֶת בַּעֲבוּר קִרְבָתָם וְדִמְיוֹנָם, וְהִנֵּה תִּהְיֶה שְׁכִיבַת שְׁתֵּיהֶן לוֹ זִמָּה. וְהוּא הָעִנְיָן שֶׁהִזְכִּירוּ רַבּוֹתֵינוּ (נדרים כ) "וּבָרוֹתִי מִכֶּם הַמֹּרְדִים וְהַפּוֹשְׁעִים בִּי" (יחזקאל כ לח), אֵלּוּ בְּנֵי תֵּשַׁע מִדּוֹת וכו'. וּלְכָךְ אָמַר הַכָּתוּב "עֶרְוַת אִשָּׁה וּבִתָּהּ", וְכֵן יֹאמַר "וְאִישׁ אֲשֶׁר יִקַּח אֶת אִשָּׁה וְאֶת אִמָּהּ זִמָּה הִיא" (ויקרא כ':י"ד), וְלֹא אָמַר עֶרְוַת בַּת אִשְׁתְּךָ לֹא תְגַלֵּה וְעֶרְוַת אֵם אִשְׁתְּךָ לֹא תְגַלֶּה. וְטַעַם הַכָּתוּב כִּי מִתְּחִלַּת הַפָּרָשָׁה (ויקרא י"ח:ו') אָמַר "אִישׁ אִישׁ אֶל כָּל שְׁאֵר בְּשָׂרוֹ לֹא תִקְרְבוּ", כִּי אָסַר הַקְּרוֹבוֹת לוֹ מִשּׁוּם שְׁאֵרוֹ וְנָתַן בָּהֶם טַעַם (ויקרא י"ח:י') "כִּי עֶרְוָתְךָ הֵנָּה", וְעַכְשָׁו (ויקרא י"ח:י"ז-י"ח) כְּשֶׁאָסַר קְרוֹבוֹת אִשְׁתּוֹ אָמַר "שַׁאֲרָה הֵנָּה" לוֹמַר שֶׁגַּם הֵמָּה אֲסוּרוֹת מִפְּנֵי שֶׁהֵן שְׁאֵר זוֹ לְזוֹ, וְתִהְיֶה מִשְׁכָּבָן בִּשְׁתֵּיהֶן זִמָּה כְּמוֹ שֶׁפֵּרַשְׁתִּי. וְכֵן אָמַר הַכָּתוּב (יחזקאל כב יא) "וְאִישׁ אֶת כַּלָּתוֹ טִמֵּא בְזִמָּה", שֶׁטִּמְּאָהּ לְבַעְלָהּ, כִּי גַּם בִּהְיוֹתָהּ עִמּוֹ תַּחְשֹׁב בְּאָבִיו בַּעֲבוּר דִּמְיוֹנָם. וְקָרָא הַכָּתוּב שְׁכִיבַת הַבְּהֵמָה "תֶּבֶל הוּא" (ויקרא י"ח:כ"ג), שֶׁיְּבַלְבֵּל זֶרַע אָדָם וְזֶרַע בְּהֵמָה, וְכֵן אָמַר (ויקרא כ':י"ב) בִּשְׁכִיבַת הַכַּלָּה "תֶּבֶל הוּא", שֶׁיִּתְעָרֵב הָאָב וְהַבֵּן לִהְיוֹת לָהּ כְּאִישׁ אֶחָד, תִּשְׁכַּב עִם שְׁנֵיהֶם יַחַד בַּמַּחְשָׁבָה:
@68 **לִצְרֹר לְגַלּוֹת עֶרְוָתָהּ עָלֶיהָ בְּחַיֶּיהָ** וּבְכָאן יְפָרֵשׁ הַכָּתוּב טַעַם הָאִסּוּר, יֹאמַר שֶׁאֵינוֹ רָאוּי שֶׁתִּקַּח אִשָּׁה אֶל אֲחוֹתָהּ לִצְרֹר אוֹתָן זוֹ לָזוֹ, כִּי הֵן רְאוּיוֹת שֶׁתִּהְיֶינָה אוֹהֲבוֹת זוֹ אֶת זוֹ, לֹא שֶׁתִּהְיֶינָה צָרוֹת. וְלֹא אָמַר כֵּן בְּאִשָּׁה וּבִתָּהּ (ויקרא י"ח:י"ז) וְאִשָּׁה וְאִמָּהּ (ויקרא כ':י"ד), כִּי הִנֵּה שְׁאֵר וַאֲסוּרוֹת אֲפִילּוּ לְאַחַר מִיתָה:
@69 **וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ** אָסַר הַכָּתוּב הַנִּדָּה מִפְּנֵי טַעַם שֶׁהִזְכַּרְתִּי (רמב"ן על ויקרא י"ח:ו'), שֶׁלֹּא הִתִּירָה הַתּוֹרָה הַמִּשְׁכָּב רַק לְקִיּוּם הַזֶּרַע, וְהִנֵּה הַוָּלָד נוֹצָר מִדַּם הָאִשָּׁה כֻּלּוֹ אוֹ רֻבּוֹ כַּאֲשֶׁר הִזְכַּרְתִּי כְּבָר (רמב"ן על ויקרא י"ב:ב'), וּמִדַּם הַנִּדּוּת לֹא יִהְיֶה נוֹצָר כְּלָל, וְאֵיךְ יַעֲשֶׂה מִמֶּנּוּ וָלָד וְהוּא סַם הַמָּוֶת יָמִית כָּל בַּעַל חַיִּים שֶׁיִּשְׁתֶּה אוֹתוֹ אוֹ יֹאכְלֶנּוּ. וְהִנֵּה בִּהְיוֹת בָּרֶחֶם דַּם נִדָּה הַרְבֵּה לֹא תִּתְעַבֵּר מִמֶּנּוּ, כִּי לֹא יוֹצֵר כְּלָל, וְאַף אִם תִּתְעַבֵּר מִדָּם אַחֵר וְיִהְיֶה נִזּוֹן מִזֶּה, הוּא יְמִיתֶנּוּ. וּכְבָר הִזְכִּירוּ הָרוֹפְאִים עוֹד שֶׁאִם יִהְיֶה נִזּוֹן מִדָּם מְשֻׁבָּח, וְכָל מְזוֹנוֹ מִדָּם טוֹב אֶלָּא שֶׁנִּשְׁתַּקַּע בְּתוֹכוֹ מִדַּם הַנִּדּוּת, יַחְמִיץ אוֹתוֹ וְיוֹלִיד בַּוָּלָד שְׁחִין וַאֲבַעְבּוּעוֹת לְמִינֵיהֶם. וְעַל דַּעַת רַבּוֹתֵינוּ (תנחומא מצורע א) אִם יִשָּׁאֵר מִמֶּנּוּ בְּגוּפוֹ קְצָת יִהְיֶה הַוָּלָד מְצֹרָע. וּמִכָּל הַפָּנִים הָאֵלּוּ רָאוּי שֶׁתַּרְחִיק הַתּוֹרָה מִשְׁכַּב הַנִּדָּה. וְעוֹד הִגִּידוּ בּוֹ נִסָּיוֹן אֲמִתִּי, וְהוּא מִמִּפְלְאוֹת תְּמִים דֵּעִים בַּתּוֹלָדָה, כִּי הַנִּדָּה בִּתְחִלַּת זֹבָהּ אִם תַּבִּיט בְּמַרְאָה שֶׁל בַּרְזֶל הַבָּהִיר וְתַאֲרִיךְ לִרְאוֹת בָּהּ, יֵרָאוּ בַּמַּרְאָה טִפּוֹת אֲדֻמּוֹת כְּטִפּוֹת דָּם, כִּי הַטֶּבַע הָרַע הַמַּזִּיק שֶׁבָּהּ תּוֹלִיד גְּנַאי, וְרֹעַ הָאֲוִיר יִדְבַּק בַּמַּרְאָה. וְהִנֵּה הִיא כְּאֶפְעֶה הַמֵּמִית בְּהַבָּטָתוֹ, וְכָל שֶׁכֵּן שֶׁתַּזִּיק לַשּׁוֹכֵב עִמָּהּ, אֲשֶׁר תְּדַבֵּק גּוּפָהּ וּמַחְשַׁבְתָּהּ בּוֹ וּבְמַחְשַׁבְתּוֹ, וּלְכָךְ גָּזַר עָלָיו הַכָּתוּב (ויקרא ט"ו:כ"ד) "וּתְהִי נִדָּתָהּ עָלָיו", כִּי רָעָתָהּ רֹעַ מִתְדַּבֵּק. וְהוּא שֶׁאָמַר "בְּנִדַּת טֻמְאָתָהּ", וְיֹאמַר "טֻמְאַת הַנִּדָּה" (יחזקאל לו יז), כִּי יַזְכִּיר בָּהּ לְעוֹלָם טֻמְאָה, שֶׁהִיא כַּשֶּׁרֶץ וְכָאִישׁ הַמְּצֹרָע שֶׁטֻּמְאָה לָהֶם בְּגוּפָם. וְיִתָּכֵן שֶׁזֶּהוּ טַעַם "אֶת מְקֹרָהּ הֶעֱרָה וְהִיא גִּלְּתָה אֶת מְקוֹר דָּמֶיהָ" (ויקרא כ':י"ח), כִּי הַמָּקוֹר הַמָּשְׁחָת הַהוּא רָאוּי לְהִסָּתֵם, לֹא שֶׁיִּגָּלֶה וְיִשְׁאֲבוּ מִמֶּנּוּ מַיִם הָרָעִים הַמַּזִּיקִים מְאֹד. וְהִנֵּה נֶאֱסַר לְזֶרַע הַקֹּדֶשׁ כָּל יְמֵי טֻמְאָתָהּ עַד שֶׁתִּטְבֹּל בַּמַּיִם, כִּי אָז תִּטְהַר גַּם בְּמַחְשַׁבְתָּהּ וְתִהְיֶה נְקִיָּה לְגַמְרֵי:
@70 **וְאֶל אֵשֶׁת עֲמִיתְךָ לֹא תִתֵּן שְׁכָבְתְּךָ לְזָרַע** אָמַר ר"א (אבן עזרא על ויקרא י"ח:כ') כִּי הַמִּשְׁגָּל לִשְׁלֹשָׁה חֲלָקִים נֶחְלָק: הָאֶחָד לִפְרִיָּה וּרְבִיָּה, וְהַשֵּׁנִי לְהָקֵל מִלֵּחוֹת הַגּוּף, וְהַשְּׁלִישִׁי לְתַאֲוָה הַנִּמְשֶׁלֶת לְתַאֲוַת הַבְּהֵמוֹת. וְאָמַר הַכָּתוּב "לְזָרַע", וְטַעְמוֹ אֲפִילּוּ לְזֶרַע, וְהִנֵּה הִיא אֲסוּרָה לְגַמְרֵי. וְאֶפְשָׁר שֶׁאָמַר "לְזָרַע", לְהַזְכִּיר טַעַם הָאִסּוּר, כִּי לֹא יִוָּדַע הַזֶּרַע לְמִי הוּא וְיָבֹאוּ מִזֶּה תּוֹעֵבוֹת גְּדוֹלוֹת וְרָעוֹת לִשְׁנֵיהֶם. וְלֹא הִזְכִּיר זֶה בָּעֹנֶשׁ (ויקרא כ':י"ח), כִּי אֲפִלּוּ הֶעֱרָה בָּהּ וְלֹא הוֹצִיא זֶרַע יִתְחַיֵּב. וּלְכָךְ אָמַר בְּסוֹטָה (במדבר ה יג) "וְשָׁכַב אִישׁ אֹתָהּ שִׁכְבַת זֶרַע", כִּי בַּעֲבוּר הַזֶּרַע תִּהְיֶה קִנְאָתוֹ. וְכֵן בְּשִׁפְחָה חֲרוּפָה (ויקרא י"ט:כ') הִזְכִּיר שִׁכְבַת זֶרַע, כִּי הָאִסּוּר בַּעֲבוּר שֶׁיּוֹלִיד זֶרַע מִן הַשִּׁפְחָה. וְהַנָּכוֹן בְּעֵינַי כִּי בַּעֲבוּר הֱיוֹת אֵשֶׁת עֲמִיתוֹ אֲסוּרָה לוֹ לְגַמְרֵי, לֹא יִנָּקֶה כָּל הַנֹּגֵעַ בָּהּ (משלי י כט), הֻצְרַךְ לוֹמַר "לְזָרַע", שֶׁאִם אָמַר "לֹא תִתֵּן שְׁכָבְתְּךָ" בִּלְבַד, הָיָה נִרְאֶה שֶׁיַּזְהִיר אֲפִילּוּ הַשּׁוֹכֵב עִמָּהּ לְחַבֵּק וּלְנַשֵּׁק, וְכָאן בְּחַיָּבֵי כְּרֵיתוֹת יַזְהִיר, עַל כֵּן הֻצְרַךְ לְהַזְכִּיר שְׁכִיבָה לְזֶרַע, לְפָרֵשׁ כִּי בַּמִּשְׁגָּל יַזְהִיר. וְהוּא הַטַּעַם בְּשִׁפְחָה חֲרוּפָה שֶׁהִיא כְּאֵשֶׁת אִישׁ. וְכֵן יֹאמַר בְּאֵשֶׁת אִישׁ (ויקרא כ':י') "אֲשֶׁר יִנְאַף אֶת אֵשֶׁת רֵעֵהוּ", וְלֹא אָמַר "יִשְׁכַּב", כִּי לֹא בִּשְׁכִיבָה לְבַד יַזְהִיר. וְלֹא אָמַר בְּכָאן "לְגַלּוֹת עֶרְוָתָהּ", כִּי לֹא יַזְכִּיר כֵּן רַק בִּשְׁאֵר הַבָּשָׂר וּבְנִדָּה, וְשֶׁהָאִסּוּר בָּהֶן בַּעֲבוּר הַגִּלּוּי, כְּמוֹ שֶׁאָמַר (שם פסוק יט) "כִּי אֶת שְׁאֵרוֹ הֶעֱרָה". וְרַבּוֹתֵינוּ דָּרְשׁוּ בְּאֵשֶׁת אִישׁ לְמַעֵט מְשַׁמֵּשׁ בְּאֵבֶר מֵת, וְאָמְרוּ בְּשִׁפְחָה חֲרוּפָה שֶׁאֵינוֹ חַיָּב אֶלָּא בְּגוֹמֵר בִּיאָתוֹ כְּמוֹ שֶׁמְּפֹרָשׁ בִּיבָמוֹת (נה):
@71 **לַמֹּלֶךְ** עֲבוֹדָה זָרָה שֶׁשְּׁמָהּ מֹלֶךְ. וְהִזְכִּירוֹ הַכָּתוּב בְּשֵׁם הַיְּדִיעָה, כִּי הָיָה בְּמִצְרַיִם יָדוּעַ לָהֶם. וְרַבִּי אַבְרָהָם אָמַר (אבן עזרא על ויקרא י"ח:כ"א) כִּי יִתָּכֵן שֶׁהוּא מִלְכֹּם תּוֹעֲבַת בְּנֵי עַמּוֹן (מלכים ב כג יג). וְכֵן נִרְאֶה, כִּי כָּתוּב (מלכים א יא ז) "אָז יִבְנֶה שְׁלֹמֹה בָּמָה לִכְמוֹשׁ שִׁקֻּץ מוֹאָב וּלְמֹלֶךְ שִׁקֻּץ בְּנֵי עַמּוֹן", וְגַם הוּא הָיָה יָדוּעַ לָהֶם. וְכָתַב רַשִׁ"י (רש"י על ויקרא י"ח:כ"א), וְזוֹ הִיא עֲבוֹדָתָהּ, שֶׁמּוֹסֵר בְּנוֹ לַכּוֹמָרִים וְהַכּוֹמָרִים עוֹשִׂין שְׁתֵּי מְדוּרוֹת גְּדוֹלוֹת וּמַעֲבִירִין אֶת הַבֵּן בְּרַגְלָיו בֵּין שְׁתֵּי מְדוּרוֹת הָאֵשׁ. "לֹא תִתֵּן" - זֶהוּ מְסִירָתוֹ לַכּוֹמָרִים, "לְהַעֲבִיר לַמֹּלֶךְ" - זֶהוּ הַעֲבָרַת מְדוּרַת הָאֵשׁ. וְזֶה אֵינוֹ נָכוֹן, שֶׁהֲרֵי אָמְרוּ בִּגְמָרָא סַנְהֶדְרִין (סד), הֶעֱבִירוֹ בָּרֶגֶל פָּטוּר, אֶלָּא כְּמַשְׁוַורְתָּא דְּפוּרַיָּא, שֶׁהוּא מַעֲבִירוֹ בְּתוֹךְ הָאֵשׁ מַמָּשׁ. וְהִזְכִּיר בּוֹ הַכָּתוּב נְתִינָה וְהַעֲבָרָה בָּאֵשׁ, שֶׁאֵינוֹ חַיָּב עַד שֶׁיִּמְסְרֶנּוּ לַכּוֹמָרִים וְהֶעֱבִירוֹ בָּאֵשׁ, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסַנְהֶדְרִין. וְכֵן מַה שֶׁאָמַר הָרַב שֶׁמּוֹסְרוֹ לַכּוֹמָרִים וְהֵם מַעֲבִירִין אוֹתוֹ, וְכָךְ כָּתַב אַף בְּפֵרוּשָׁיו בְּמַסֶּכֶת סַנְהֶדְרִין (שם סד), וְאֵינוֹ נִרְאֶה כֵן מִלְּשׁוֹנָם שָׁם בַּגְּמָרָא, וְעוֹד אֵיךְ יִתְחַיֵּב הוּא מִיתָה בַּעֲבוֹדַת אֲחֵרִים, וּלְשׁוֹן הַכָּתוּב עַצְמוֹ "מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ" (דברים יח י) כָּךְ נִדְרָשׁ, שֶׁהָאָב בְּעַצְמוֹ מַעֲבִירוֹ. אֲבָל הָעִנְיָן כָּךְ הוּא, שֶׁהָאָב עַצְמוֹ מוֹסְרוֹ לַכּוֹמָרִים לְשֵׁם שִׁקּוּצָם, וְזֶהוּ שֶׁכָּתוּב "נָתַן לַמֹּלֶךְ" (ויקרא כ':ג'), כְּעֵין שֶׁעוֹשִׂים בִּפְנִים, כְּדִכְתִיב "וּנְתָנָם אֶל הַכֹּהֵן" (ויקרא ט"ו:י"ד). וְאוּלַי הַכּוֹמָרִים עוֹשִׂין בּוֹ תְּנוּפָה אוֹ הַגָּשָׁה לִפְנֵי הַמֹּלֶךְ וְהֵם מַחְזִירִין אוֹתוֹ לִידֵי הָאָב, וְהוּא לוֹקְחוֹ וּמַעֲבִירוֹ בְּלַהַב הָאֵשׁ, וְזֶהוּ "מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ". וְכָךְ אָמְרוּ בַּיְּרוּשַׁלְמִי (סנהדרין פ"ז ה"י), לְעוֹלָם אֵינוֹ חַיָּב עַד שֶׁיִּמְסְרֶנּוּ לַכּוֹמָרִים וְיִטְּלֶנּוּ וְיַעֲבִירֶנּוּ. כְּלוֹמַר, שֶׁיִּטְּלֶנּוּ מֵהֶם וְיַעֲבִירֶנּוּ הוּא. אֲבָל לֹא הָיָה שׂוֹרְפוֹ, שֶׁהֲרֵי אָמְרוּ (סנהדרין סד), הַמַּעֲבִיר אֶת עַצְמוֹ פָּטוּר, שֶׁהוּא חַי אַף לְאַחַר הַעֲבָרָה, וְכָךְ פֵּרֵשׁ רַשִׁ"י. וְעִם כָּל זֶה הַנִּרְאֶה בְּעֵינַי מֵהֶכְרֵעַ הַפְּסוּקִים כִּי הָיָה הַבֵּן לְמַאֲכֹלֶת הָאֵשׁ, שֶׁהַכָּתוּב אוֹמֵר (יחזקאל כג לז) "וְגַם אֶת בְּנֵיהֶן אֲשֶׁר יָלְדוּ לִי הֶעֱבִירוּ לָהֶם לְאָכְלָה", וְשָׁם (ויקרא י"ח:ל"ט) נֶאֱמַר "וּבְשַׁחֲטָם אֶת בְּנֵיהֶם לְגִלּוּלֵיהֶם", שֶׁהָיוּ מַעֲבִירִין אוֹתוֹ בָּאֵשׁ עַד שֶׁיִּשָּׂרֵף אוֹ שֶׁיָּמוּת בָּאֵשׁ, וְהִיא שְׁחִיטָתוֹ, כִּי הַלָּשׁוֹן הַזֶּה "הֶעֱבִירוּ לָהֶם" בַּמֹּלֶךְ הוּא, וְאָמַר בּוֹ הַכָּתוּב "לְאָכְלָה", וְהִזְכִּיר בּוֹ שְׁחִיטָה, אִם כֵּן מַה שֶׁאָמַר "כְּמַשְׁוַורְתָּא דְּפוּרַיָּא" לוֹמַר שֶׁהָיוּ מַעֲבִירִין אוֹתוֹ עַל הַשַּׁלְהֶבֶת פְּעָמִים רַבּוֹת וְהוּא מֵת בְּלַהַב הָאֵשׁ. וְהִנֵּה הוּא חַיָּב בְּדִין הַתּוֹרָה מִשְּׁעַת הַעֲבָרָה הָרִאשׁוֹנָה, מִשֶּׁתִּמְשֹׁל בּוֹ הָאוּר, כְּגוֹן שֶׁנִּתְפַּס הָאֵשׁ בְּאֶחָד מֵאֵיבָרָיו, וּלְכָךְ הֻצְרְכוּ לוֹמַר שֶׁהַמַּעֲבִיר עַצְמוֹ פָּטוּר, אֲבָל הָיָה הָאֵשׁ אוֹכֶלֶת בּוֹ כִּי זֶה הָיָה קָרְבָּנָם לַמֹּלֶךְ. וּלְשׁוֹן "מַעֲבִיר בָּאֵשׁ" יֵאָמֵר בְּכָל מָקוֹם עַל הַדָּבָר שֶׁהוּא בּוֹעֵר בָּאֵשׁ וְאֵינֶנּוּ אֻכָּל, מִפְּנֵי שֶׁנּוֹתְנִים אוֹתוֹ בָּאֵשׁ וּמַעֲבִירִים אוֹתוֹ מִמֶּנּוּ וְאֵינוֹ נַעֲשֶׂה אֵפֶר כַּנִּשְׂרָפִים, כְּעִנְיַן כְּלֵי הַגּוֹיִם שֶׁמְּלַבְּנִין אוֹתָן בָּאֵשׁ, שֶׁנֶּאֱמַר בָּהֶן (במדבר לא כג) "תַּעֲבִירוּ בָּאֵשׁ וְטָהֵר". וְאָמַר בִּבְנֵי עַמּוֹן (יב לא) "וְהֶעֱבִיר אוֹתָם בַּמַּלְבֵּן", לוֹמַר שֶׁשָּׂרַף אוֹתָן כַּאֲשֶׁר יַעֲשׂוּ הַלְּבֵנִים בַּמַּלְבֵּן, אִם כֵּן "מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ" (דברים יח י) הִיא נְתִינָתוֹ בָּאֵשׁ שֶׁתִּמְשֹׁל בּוֹ הָאוּר, לֹא הַעֲבָרָה בְּעָלְמָא, וְהִיא הַעֲבָרָה הַנִּזְכֶּרֶת בַּמֹּלֶךְ שֶׁהִיא בָּאֵשׁ עַל דַּעַת רַבּוֹתֵינוּ (סנהדרין סד) שֶׁלָּמְדוּ בִּגְזֵרָה שָׁוָה הַעֲבָרָה הַעֲבָרָה, מַה לְהַלָּן (דברים יח י) בָּאֵשׁ אַף כָּאן בָּאֵשׁ, מַה כָּאן לַמֹּלֶךְ אַף לְהַלָּן לַמֹּלֶךְ. וּרְאָיָה לְדִבְרֵיהֶם שֶׁכָּתוּב בְּיֹאשִׁיָּהוּ (מלכים ב כג י) "וְטִמֵּא אֶת הַתֹּפֶת אֲשֶׁר בְּגֵּיא בֶן הִנֹּם לְבִלְתִּי לְהַעֲבִיר אִישׁ אֶת בְּנוֹ וְאֶת בִּתּוֹ בָּאֵשׁ לַמֹּלֶךְ", אִם כֵּן הַעֲבָרָה הַנִּזְכֶּרֶת בַּמֹּלֶךְ הִיא בָּאֵשׁ. וְכֵן כָּתוּב בִּמְנַשֶּׁה (דהי"ב לג ו) "וְהוּא הֶעֱבִיר אֶת בָּנָיו בָּאֵשׁ בְּגֵיא בֶן הִנֹּם". וּמָצָאתִי שֶׁכָּתוּב בְּאָחָז (מלכים ב טז ג) "וְגַם אֶת בְּנוֹ הֶעֱבִיר בָּאֵשׁ כְּתֹעֲבוֹת הַגּוֹיִם אֲשֶׁר הוֹרִישׁ ה' אֹתָם מִפְּנֵי בְּנֵי יִשְׂרָאֵל", וּבְדִבְרֵי הַיָּמִים (ב כח ג) נֶאֱמַר "וַיַּבְעֵר אֶת בָּנָיו בָּאֵשׁ כְּתֹעֲבוֹת הַגּוֹיִם אֲשֶׁר הוֹרִישׁ", אִם כֵּן הַהַעֲבָרָה הִיא הַבְעָרָה בָּאֵשׁ מַמָּשׁ. וּמַה שֶׁאָמַר הַכָּתוּב (מלכים ב יז לא) "וְהַסְפַרְוִים שֹׂרְפִים אֶת בְּנֵיהֶם בָּאֵשׁ לְאַדְרַמֶּלֶךְ וַעֲנַמֶּלֶךְ אֱלֹהֵי סְפַרְוָיִם", הִיא עֲבוֹדָה זָרָה אַחֶרֶת, שֶׁעֲבוֹדָתָהּ לִשְׂרֹף אוֹתָם לְגַמְרֵי כְּעוֹלָה, וְכֵן הָיוּ עוֹשִׂין לַבַּעַל, כְּמוֹ שֶׁכָּתוּב בְּיִרְמְיָהוּ (יט ב) "וְיָצָאתָ אֶל גֵּיא בֶן הִנֹּם" וְשָׁם (ויקרא י"ח:ד'-ה') כְּתִיב, "וּמָלְאוּ אֶת הַמָּקוֹם הַזֶּה דַּם נְקִיִּים וּבָנוּ אֶת בָּמוֹת הַבַּעַל לִשְׂרֹף אֶת בְּנֵיהֶם בָּאֵשׁ עֹלוֹת לַבָּעַל אֲשֶׁר לֹא צִוִּיתִי וְלֹא דִבַּרְתִּי וְלֹא עָלְתָה עַל לִבִּי", וְעוֹד כְּתִיב (שם לב לה) "וַיִּבְנוּ אֶת בָּמוֹת הַבַּעַל אֲשֶׁר בְּגֵיא בֶן הִנֹּם לְהַעֲבִיר אֶת בְּנֵיהֶם וְאֶת בְּנוֹתֵיהֶם לַמֹּלֶךְ אֲשֶׁר לֹא צִוִּיתִים וְלֹא עָלְתָה עַל לִבִּי לַעֲשׂוֹת הַתּוֹעֵבָה הַזֹּאת". אֲבָל מִפְּנֵי שֶׁשְּׁנֵי הַפְּסוּקִים הָאֵלֶּה בְּבָמוֹת הַבַּעַל וּשְׁנֵיהֶם בְּגֵיא בֶּן הִנֹּם, וְהָאַזְהָרָה בִּשְׁנֵיהֶם "אֲשֶׁר לֹא צִוִּיתִי וְלֹא דִבַּרְתִּי וְלֹא עָלְתָה עַל לִבִּי", וְשָׁם בַּמָּקוֹם הַהוּא הַטָּמֵא הָיָה שָׁם מֹלֶךְ, כְּמוֹ שֶׁכָּתוּב בְּיֹאשִׁיָּהוּ, נִרְאֶה מִכָּל זֶה שֶׁהָיוּ שׂוֹרְפִין אֶת בְּנֵיהֶם עוֹלוֹת לַמֹּלֶךְ וְהוּא הַבַּעַל, וּשְׁנֵיהֶם לָשׁוֹן קָרוֹב כְּמַלְכוּת וְאַדְנוּת, וְאֵינֶנּוּ בַּעַל פְּעוֹר וּבַעַל זְבוּב כִּי זֶה יִקָּרֵא הַבַּעַל סְתָם כַּאֲשֶׁר יִקָּרֵא הַמֹּלֶךְ, אֲבָל הִזְכִּיר בּוֹ הַכָּתוּב הַעֲבָרָה כִּי עִקַּר עֲבוֹדָתוֹ בְּהַעֲבָרָה מִשֶּׁתִּמְשֹׁל בּוֹ הָאוּר, וְתִקָּרֵא שְׂרֵפָה כִּי יָמוּתוּ שָׁם, וּלְכָךְ יִקָּרְאוּ עוֹלוֹת. וְכֵן אֲנִי סוֹבֵר כִּי "אֱלֹהֵי סְפַרְוַיִם" (מלכים ב יז לא) הוּא הַמֹּלֶךְ, כִּי הַכִּנּוּי בָּהֶם מֶלֶךְ אֲבָל הָיוּ שְׁנֵיהֶם נֶעֱבָדִים, כִּנּוּ לְאֶחָד אֲדָר בִּלְשׁוֹן כָּבוֹד וְלַשֵּׁנִי עַן מִלְּשׁוֹן עוֹנָה, וְשִׁתְּפוּ בִּשְׁנֵיהֶם מֶלֶךְ וְהוּא כְּמוֹ מֹלֶךְ, וְהַשְּׂרֵפָה הִיא מִיתָתָם בָּאֵשׁ כַּאֲשֶׁר פֵּרַשְׁתִּי. וְאִם נֹאמַר שֶׁהַשִּׁקּוּצִים הָאֵלֶּה אֵינָם הַמֹּלֶךְ, יִתָּכֵן כִּי בַּעֲבוּר הֱיוֹת עֲבוֹדָתָם בְּבָנִים וּבְבָנוֹת לַהֲבִיאָם בָּאֵשׁ כָּעִנְיָן שֶׁאָמַר בְּמֹלֶךְ, יְשַׁתְּפוּ בָּהֶם שְׁמוֹ מֶלֶךְ וּבַעַל, וְאֵין עֲבוֹדָתָם שָׁוָה, כִּי הַמֹּלֶךְ בְּהַעֲבָרָה וֵאלֹהֵי סְפַרְוַיִם בִּשְׂרֵפָה וְהַבַּעַל בִּשְׁחִיטָה וּשְׂרֵפָה כְּעוֹלוֹת, וְנֶאֱמַר שֶׁהָיוּ בִּמְקוֹם הַתֹּפֶת אֲשֶׁר בְּגֵיא בֶּן הִנֹּם בָּמוֹת לַבַּעַל, וְשָׁם עוֹד מֹלֶךְ, וּמַה שֶׁאָמַר הַכָּתוּב (ירמיהו לב לד) "וַיִּבְנוּ אֶת בָּמוֹת הַבַּעַל אֲשֶׁר בְּגֵיא בֶן הִנֹּם לְהַעֲבִיר אֶת בְּנֵיהֶם לַמֹּלֶךְ", יִהְיֶה פֵּרוּשׁוֹ וּלְהַעֲבִיר אֶת בְּנֵיהֶם לַמֹּלֶךְ. וְרַבּוֹתֵינוּ אָמְרוּ (סנהדרין סג), אַף חִזְקִיָּה מֶלֶךְ יְהוּדָה בִּקֵּשׁ אָבִיו לַעֲשׂוֹת לוֹ כֵן, שֶׁיִּשְׂרֹף אוֹתוֹ בָּאֵשׁ, אֶלָּא שֶׁסָּכַתּוּ אִמּוֹ בְּשֶׁמֶן סָלָמַנְדְּרָא. וְהִנֵּה אָחָז לַמֹּלֶךְ הֶעֱבִיר אוֹתוֹ, כְּדִכְתִיב "וְגַם אֶת בְּנוֹ הֶעֱבִיר בָּאֵשׁ כְּתֹעֲבוֹת הַגּוֹיִם אֲשֶׁר הוֹרִישׁ ה' מִפְּנֵי בְּנֵי יִשְׂרָאֵל", וְזֶהוּ הַלָּשׁוֹן הַכָּתוּב בְּמֹלֶךְ, אִם כֵּן הִיא הַבְעָרָה שֶׁתִּמְשׁוֹל בּוֹ הָאוּר וְיָמוּת, וְנִצַּל הַצַּדִּיק בַּסָּלָמְנַדְרָא הַזּוֹ שֶׁבְּרָאָהּ הקב"ה בַּעֲבוּרוֹ. וְעַל דֶּרֶךְ הַפְּשָׁט אָמְרוּ, כִּי מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ מִין מִמִּינֵי הַכְּשָׁפִים, כִּי בְּעִנְיַן הַכִּשּׁוּף נֶאֱמַר (דברים יח י) "לֹא יִמָּצֵא בְךָ מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ קֹסֵם קְסָמִים מְעוֹנֵן וּמְנַחֵשׁ וּמְכַשֵּׁף", וְאָמַר בִּמְנַשֶּׁה (דהי"ב לג ו) "וְהוּא הֶעֱבִיר אֶת בָּנָיו בָּאֵשׁ בְּגֵּיא בֶן הִנֹּם וְעוֹנֵן וְנִחֵשׁ וְכִשֵּׁף וְעָשָׂה אוֹב וְיִדְּעוֹנִי", וּכְתִיב (מלכים ב יז יז) "וַיַּעֲבִירוּ אֶת בְּנֵיהֶם וְאֶת בְּנוֹתֵיהֶם בָּאֵשׁ וַיִּקְסְמוּ קְסָמִים וַיְנַחֵשׁוּ", וְהַמֹּלֶךְ הִיא עֲבוֹדָה זָרָה שֶׁמַּקְרִיבִין לוֹ הַקְּטַנִּים, אֲבָל אַחַר שֶׁמָּצָאנוּ כָּתוּב (שם כג י) "לְבִלְתִּי לְהַעֲבִיר אִישׁ אֶת בְּנוֹ וְאֶת בִּתּוֹ בָּאֵשׁ לַמֹּלֶךְ" נֶאֶמְנוּ דִּבְרֵי רַבּוֹתֵינוּ שֶׁהַכֹּל לַמֹּלֶךְ בָּאֵשׁ. אֲבָל יִתָּכֵן שֶׁהָיְתָה הָעֲבוֹדָה הַהִיא לָהֶם לִקְסֹם שָׁוְא, וְהָיוּ מִתְנַבְּאִים בָּהּ כְּפִי סִכְלוּתָם, וְהֵם נְבִיאֵי הַבַּעַל הַמַּקְרִיבִים לוֹ הַבָּנִים וְהַבָּנוֹת וְיֵרָאוּ לָהֶם חֲלוֹמוֹת שָׁוְא וּמִקְסַם כָּזָב, וְלָכֵן תְּיַחֵס הַתּוֹרָה עִנְיַן הַמֹּלֶךְ בְּעִנְיַן הַקְּסָמִים, כִּי בְּכָאן (ויקרא כ':ו') סָמַךְ אֶל "הַנֶּפֶשׁ אֲשֶׁר תִּפְנֶה אֶל הָאֹבֹת וְאֶל הַיִּדְּעֹנִים", וּבְמִשְׁנֵה תּוֹרָה כָּל הַפָּרָשָׁה בַּמִּתְנַבְּאִים לָדַעַת הָעֲתִידוֹת בְּשֶׁקֶר. וְהִנֵּה הִזְכִּיר הַכָּתוּב כִּי הַעֲבָרַת הַזֶּרַע לַמֹּלֶךְ הוּא חִלּוּל הַשֵּׁם, וּבַפָּרָשָׁה הָאַחֶרֶת (ויקרא כ':ג') מוֹסִיף "לְמַעַן טַמֵּא אֶת מִקְדָּשִׁי וּלְחַלֵּל אֶת שֵׁם קָדְשִׁי", וְאוּלַי טַעְמוֹ לְמַעַן טַמֵּא אֶת הָעָם הַמְקֻדָּשׁ לִשְׁמִי, שֶׁצִּוִּיתִי (ויקרא י"א:מ"ד) "וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדֹשִׁים כִּי קָדוֹשׁ אֲנִי ה' מְקַדִּשְׁכֶם" (ויקרא כ"א:ח'), וּלְחַלֵּל אֶת שֵׁם קָדְשִׁי בְּעָבְרָם עַל הָעֲבֵרָה הַחֲמוּרָה לְפָנַי, כִּי כֵן יֹאמַר בַּעֲבֵרוֹת הַחֲמוּרוֹת "וְאִישׁ וְאָבִיו יֵלְכוּ אֶל הַנַּעֲרָה לְמַעַן חַלֵּל אֶת שֵׁם קָדְשִׁי" (עמוס ב ז). וְיִתָּכֵן שֶׁיֹּאמַר כֵּן מִפְּנֵי שֶׁהַמַּקְרִיב מִזַּרְעוֹ לַמֹּלֶךְ וְאַחַר כֵּן יָבֹא אֶל מִקְדַּשׁ ה' לְהַקְרִיב קָרְבָּן, מְטַמֵּא אֶת הַמִּקְדָּשׁ, כִּי קָרְבְּנוֹתָיו טְמֵאִים וְתוֹעֵבָה לַשֵּׁם, וְהוּא עַצְמוֹ טָמֵא לְעוֹלָם, שֶׁנִּטְמָא בָּרָעָה שֶׁעָשָׂה, כְּמוֹ שֶׁאָמַר בְּאוֹב וְיִדְּעוֹנִי "לְטָמְאָה בָהֶם" (ויקרא י"ט:ל"א), וּכְתִיב "וּבְגִלּוּלֵיהֶם טִמְּאוּהָ" (יחזקאל לו יח), וְהִזְכִּיר בּוֹ חִלּוּל הַשֵּׁם, כִּי כַּאֲשֶׁר יִשְׁמְעוּ הַגּוֹיִם שֶׁכִּבֵּד אֶת הַמֹּלֶךְ בְּזַרְעוֹ וְיַקְרִיב מִבְּהֶמְתּוֹ קָרְבָּן לַשֵּׁם הוּא חִלּוּל הַשֵּׁם, וְזֶהוּ שֶׁאָמַר הַנָּבִיא (שם כג לז לח) "וְגַם אֶת בְּנֵיהֶן אֲשֶׁר יָלְדוּ לִי הֶעֱבִירוּ לָהֶם לְאָכְלָה עוֹד זֹאת עָשׂוּ לִי טִמְּאוּ אֶת מִקְדָּשִׁי בַּיּוֹם הַהוּא", וְאָמַר (שם פסוק לט) "וּבְשַׁחֲטָם אֶת בְּנֵיהֶם לְגִלּוּלֵיהֶם וַיָּבֹאוּ אֶל מִקְדָּשִׁי בַּיּוֹם הַהוּא לְחַלְּלוֹ וְהִנֵּה כֹה עָשׂוּ בְּתוֹךְ בֵּיתִי". וְעַל דֶּרֶךְ הָאֱמֶת, יִשְׂרָאֵל זֶרַע הַקֹּדֶשׁ נוֹלָדִים בְּבֵית ה', וְזֶה טַעַם "אֲשֶׁר יָלְדוּ לִי", וְהִנֵּה הַמַּקְרִיב אוֹתוֹ לַמֹּלֶךְ מְטַמֵּא מִקְדָּשׁוֹ וּמְחַלֵּל שְׁמוֹ הַגָּדוֹל, כִּלְשׁוֹן "וְלֹא יְחַלֵּל זַרְעוֹ בְּעַמָּיו" (ויקרא כ"א:ט"ו), וּלְכָךְ אָמַר בּוֹ "וַאֲנִי אֶתֵּן אֶת פָּנַי בָּאִישׁ הַהוּא" (שם כ ג), "וְשַׂמְתִּי אֲנִי אֶת פָּנַי בָּאִישׁ הַהוּא" (שם פסוק ה), וְהַמַּשְׂכִּיל יָבִין:
@72 וְטַעַם הַזְּכוּר וְהַבְּהֵמָה מְפֻרְסָם, כִּי הוּא דָּבָר נִתְעָב וְאֵינֶנּוּ בְּקִיּוּם הַמִּינִין, כִּי אָדָם וּבְהֵמָה לֹא יוֹלִידוּ. וְכָתַב ר' אַבְרָהָם (אבן עזרא על ויקרא י"ח:כ"ב) אַחַר שֶׁמָּצָאנוּ "הֵן שָׁכַבְתִּי אֶמֶשׁ אֶת אָבִי" (בראשית יט לד), הִנֵּה **לֹא תִשְׁכַּב** אַזְהָרָה לַשּׁוֹכֵב וְלַנִּשְׁכָּב. וְאִם כִּדְבָרָיו, לָמָּה לֹא הָיְתָה הָאִשָּׁה בִּכְלַל "וּבְכָל בְּהֵמָה לֹא תִתֵּן שְׁכָבְתְּךָ", כִּי הַנָּשִׁים בִּכְלַל הָאַזְהָרוֹת שֶׁבְּכָל הַתּוֹרָה. אֲבָל טַעַם "שָׁכַבְתִּי אֶמֶשׁ אֶת אָבִי" בַּעֲבוּר שֶׁהֵן הַשּׁוֹכְבוֹת כְּדֵי שֶׁיֵּצֵא מִמֶּנּוּ הַזֶּרַע, כַּיָּדוּעַ שֶׁהַזֶּרַע יָבֹא מִן הַתְּנוּעָה אוֹ מִן הַגּוּף כֻּלּוֹ כְּמוֹ שֶׁיִּתְהַוֶּה הַקֶּצֶף בְּפִיּוֹת הַסּוּסִים בִּמְרוּצָתָם, אוֹ שֶׁיִּתְיַלֵּד בַּגִּידִים הַקְּרוֹבִים מִשָּׁם וְיֵאָסֵף שָׁם בְּסִבּוּב הַתְּנוּעָה וְיֵצֵא, וְאִם לֹא שָׁכְבוּ אוֹתוֹ לֹא יֵצֵא מִמֶּנּוּ זֶרַע, כִּי הָיָה כְּאֶבֶן דּוּמָם בְּשִׁכְרוּתוֹ:
@75 **וַתִּטְמָא הָאָרֶץ וָאֶפְקֹד עֲוֹנָהּ עָלֶיהָ וַתָּקִא הָאָרֶץ** הֶחְמִיר הַכָּתוּב בָּעֲרָיוֹת, בַּעֲבוּר הָאָרֶץ שֶׁתִּטְמָא בָּהֶן וְתָקִיא הַנְּפָשׁוֹת הָעוֹשׂוֹת. וְהִנֵּה הָעֲרָיוֹת חוֹבַת הַגּוּף וְאֵינָן תְּלוּיוֹת בָּאָרֶץ, אֲבָל סוֹד הַדָּבָר בַּכָּתוּב שֶׁאָמַר (דברים לב ח ט) "בְּהַנְחֵל עֶלְיוֹן גּוֹיִם בְּהַפְרִידוֹ בְּנֵי אָדָם יַצֵּב גְּבֻלֹת עַמִּים וְגוֹ' כִּי חֵלֶק ה' עַמּוֹ" וְגוֹ'. וְהָעִנְיָן כִּי הַשֵּׁם הַנִּכְבָּד בָּרָא הַכֹּל, וְשָׂם כֹּחַ הַתַּחְתּוֹנִים בָּעֶלְיוֹנִים, וְנָתַן עַל כָּל עַם וְעַם בְּאַרְצֹתָם לְגוֹיֵיהֶם כּוֹכָב וּמַזָּל יָדוּעַ, כַּאֲשֶׁר נוֹדַע בָּאִצְטַגְנִינוּת. וְזֶהוּ שֶׁנֶּאֱמַר (דברים ד יט) "אֲשֶׁר חָלַק ה' אֱלֹהֶיךָ אֹתָם לְכֹל הָעַמִּים", כִּי חִלֵּק לְכֻלָּם מַזָּלוֹת בַּשָּׁמַיִם, וּגְבוֹהִים עֲלֵיהֶם מַלְאֲכֵי עֶלְיוֹן נְתָנָם לִהְיוֹתָם שָׂרִים עֲלֵיהֶם, כְּעִנְיָן שֶׁכָּתוּב (דניאל י יג) "וְשַׂר מַלְכוּת פָּרַס עֹמֵד לְנֶגְדִּי", וּכְתִיב (שם פסוק כ) "וְהִנֵּה שַׂר יָוָן בָּא", וְנִקְרָאִים "מְלָכִים", כְּדִכְתִיב (שם פסוק יג) "וַאֲנִי נוֹתַרְתִּי שָׁם אֵצֶל מַלְכֵי פָרָס". וְהִנֵּה הַשֵּׁם הַנִּכְבָּד הוּא אֱלֹהֵי הָאֱלֹהִים וַאֲדֹנֵי הָאֲדֹנִים לְכָל הָעוֹלָם, אֲבָל אֶרֶץ יִשְׂרָאֵל, אֶמְצָעוּת הַיִּשּׁוּב, הִיא נַחֲלַת ה' מְיֻחֶדֶת לִשְׁמוֹ, לֹא נָתַן עָלֶיהָ מִן הַמַּלְאָכִים קָצִין שׁוֹטֵר וּמוֹשֵׁל בְּהַנְחִילוֹ אוֹתָהּ לְעַמּוֹ הַמְּיַחֵד שְׁמוֹ זֶרַע אוֹהֲבָיו. וְזֶהוּ שֶׁאָמַר (שמות יט ה) "וִהְיִיתֶם לִי סְגֻלָּה מִכָּל הָעַמִּים כִּי לִי כָּל הָאָרֶץ", וּכְתִיב (ירמיהו יא ד) "וִהְיִיתֶם לִי לְעָם וְאָנֹכִי אֶהְיֶה לָכֶם לֵאלֹהִים", לֹא שֶׁתִּהְיוּ אַתֶּם אֶל אֱלֹהִים אֲחֵרִים כְּלָל. וְהִנֵּה קִדֵּשׁ הָעָם הַיּוֹשֵׁב בְּאַרְצוֹ בִּקְדֻשַּׁת הָעֲרָיוֹת וּבְרֻבֵּי הַמִּצְוֹת, לִהְיוֹתָם לִשְׁמוֹ. וּלְכָךְ אָמַר (ויקרא כ':כ"ב) "וּשְׁמַרְתֶּם אֶת כָּל חֻקֹּתַי וְאֶת כָּל מִשְׁפָּטַי וַעֲשִׂיתֶם אֹתָם וְלֹא תָקִיא אֶתְכֶם הָאָרֶץ", וּכְתִיב (שם פסוק כד) "וָאֹמַר לָכֶם אַתֶּם תִּירְשׁוּ אֶת אַדְמָתָם וַאֲנִי אֶתְּנֶנָּה לָכֶם לָרֶשֶׁת אֹתָהּ אֲנִי ה' אֱלֹהֵיכֶם אֲשֶׁר הִבְדַּלְתִּי אֶתְכֶם מִן הָעַמִּים", יֹאמַר כִּי הִבְדִּיל אוֹתָנוּ מִכָּל הָעַמִּים אֲשֶׁר נָתַן עֲלֵיהֶם שָׂרִים וֵאלֹהִים אֲחֵרִים, בְּתִתּוֹ לָנוּ אֶת הָאָרֶץ שֶׁיִּהְיֶה הוּא יִתְבָּרַךְ לָנוּ לֵאלֹהִים וְנִהְיֶה מְיֻחָדִים לִשְׁמוֹ. וְהִנֵּה הָאָרֶץ שֶׁהִיא נַחֲלַת הַשֵּׁם הַנִּכְבָּד תָּקִיא כָּל מְטַמֵּא אוֹתָהּ, וְלֹא תִּסְבֹּל עוֹבְדֵי ע"ז וּמְגַלִּים עֲרָיוֹת. וְהַפָּרָשָׁה הַזֹּאת הִזְכִּירָה הַמֹּלֶךְ, לִכְלֹל עֲבוֹדָה זָרָה עִם זִכְרוֹן הָעֲרָיוֹת, וְעַל כֻּלָּם אָמַר (כאן) "אַל תִּטַּמְּאוּ בְּכָל אֵלֶּה כִּי בְכָל אֵלֶּה נִטְמְאוּ הַגּוֹיִם וַתָּקִא הָאָרֶץ אֶת יֹשְׁבֶיהָ". וְכֵן אָמַר בַּפָּרָשָׁה הַשְּׁנִיָּה (ויקרא כ':כ"ו) "וָאַבְדִּל אֶתְכֶם מִן הָעַמִּים לִהְיוֹת לִי", שֶׁהוּא חֹמֶר אִסּוּר עֲבוֹדָה זָרָה. וּלְכָךְ אָמַר כִּי מִפְּנֵי שֶׁהֵם מְיֻחָדִים לִשְׁמוֹ בַּעֲבוּר כֵּן נָתַן לָהֶם הָאָרֶץ, שֶׁנֶּאֱמַר (שם פסוק כד) "וָאֹמַר לָכֶם אַתֶּם תִּירְשׁוּ אֶת אַדְמָתָם וַאֲנִי אֶתְּנֶנָּה לָכֶם לָרֶשֶׁת אֹתָהּ אֲנִי ה' אֱלֹהֵיכֶם אֲשֶׁר הִבְדַּלְתִּי אֶתְכֶם מִן הָעַמִּים". וְהִנֵּה בְּחוּצָה לָאָרֶץ אע"פ שֶׁהַכֹּל לַשֵּׁם הַנִּכְבָּד אֵין הַטַּהֲרָה בָּהּ שְׁלֵמָה, בַּעֲבוּר הַמְשָׁרְתִים הַמּוֹשְׁלִים עָלֶיהָ, וְהָעַמִּים תּוֹעִים אַחֲרֵי שָׂרֵיהֶם לַעֲבֹד גַּם אוֹתָם. וּלְכָךְ יֹאמַר הַכָּתוּב (ישעיהו נד ה) "אֱלֹהֵי כָל הָאָרֶץ יִקָּרֵא", כִּי הוּא אֱלֹהֵי הָאֱלֹהִים הַמּוֹשֵׁל עַל הַכֹּל, וְהוּא יִפְקֹד בַּסּוֹף עַל צְבָא הַמָּרוֹם בַּמָּרוֹם (שם כד כא) לְהָסִיר מֶמְשֶׁלֶת הָעֶלְיוֹנִים וְלַהֲרֹס מַעֲרֶכֶת הַמְשָׁרְתִים, וְאַחֲרֵי כֵּן יִפְקֹד עַל מַלְכֵי הָאֲדָמָה בָּאֲדָמָה (שם). וְזֶהוּ עִנְיַן הַכָּתוּב שֶׁאָמַר (דניאל ד יד) "בִּגְזֵרַת עִירִין פִּתְגָמָא וּמֵאמַר קַדִּישִׁין שְׁאֵלְתָא", יֹאמַר כִּי הַדָּבָר הַהוּא הַנִּגְזָר עַל נְבוּכַדְנֶצַּר הִיא גְּזֵרַת עִירִין (פתגמא ומאמר קדישין שאלתא) שֶׁגָּזְרוּ עַל הַכּוֹחוֹת הַנֶּאֱצָלִין מֵהֶן לַעֲשׂוֹת כָּךְ, וְיִקָּרְאוּ "עִירִין" כִּי מֵאֲצִילוּתָן יִתְעוֹרְרוּ הַכֹּחוֹת בְּכָל הַפְּעֻלּוֹת, כְּמוֹ שֶׁאָמַר (שם שם י יא) "וַאֲלוּ עִיר וְקַדִּישׁ מִן שְׁמַיָּא נָחִת קָרֵא בְחַיִל וְכֵן אָמַר גֹּדּוּ אִילָנָא" וְגוֹ'. "וּמֵאמַר קַדִּישִׁין שְׁאֵלְתָא", כְּלוֹמַר שֶׁשָּׁאֲלוּ מַה הָרָצוֹן הָעֶלְיוֹן עָלָיו, וְאַחֲרֵי כֵן גָּזְרוּ לְהֵעָשׂוֹת כֵּן. וְזֶהוּ שֶׁאָמַר לוֹ דָּנִיֵּאל (שם פסוק כא) "וּגְזֵרַת עִלָּאָה הִיא", כִּי הַכֹּל מֵאִתּוֹ יִתְבָּרַךְ. וְהִנֵּה הַשֵּׁם הַנִּכְבָּד יִתְבָּרַךְ אֱלֹהֵי הָאֱלֹהִים בְּחוּץ לָאָרֶץ, וֵאלֹהֵי אֶרֶץ יִשְׂרָאֵל שֶׁהִיא נַחֲלַת ה', וְזֶהוּ טַעַם "וְזָנָה אַחֲרֵי אֱלֹהֵי נֵכַר הָאָרֶץ" (דברים לא טז) כִּי הָאֱלוֹהוֹת נָכְרִים בְּאֶרֶץ הַשֵּׁם וּבְנַחֲלָתוֹ. וְזֶהוּ שֶׁנֶּאֱמַר (מלכים ב יז כו) "לֹא יָדְעוּ אֶת מִשְׁפַּט אֱלֹהֵי הָאָרֶץ וַיְשַׁלַּח בָּם אֶת הָאֲרָיוֹת וְהִנָּם מְמִיתִים אוֹתָם כַּאֲשֶׁר אֵינָם יֹדְעִים אֶת מִשְׁפַּט אֱלֹהֵי הָאָרֶץ". וְהִנֵּה הַכּוּתִיִּים לֹא הָיוּ נֶעֱנָשִׁים בְּאַרְצָם בְּעָבְדָם אֶת אֱלֹהֵיהֶם לְשַׁלַּח בָּהֶם אֶת הָאֲרָיוֹת, וּבְבוֹאָם בְּאֶרֶץ הַשֵּׁם וְעָשׂוּ שָׁם כְּמַעֲשֵׂיהֶם הָרִאשׁוֹנִים שָׁלַח בָּהֶם הָאֲרָיוֹת הַמְּמִיתִים אוֹתָם. וְכֵן שָׁנוּ בְּסִפְרָא (קדושים יא יד) "וְלֹא תָקִיא הָאָרֶץ אֶתְכֶם" וְגוֹ', אֶרֶץ יִשְׂרָאֵל אֵינָהּ כִּשְׁאָר אֲרָצוֹת, אֵינָהּ מְקַיֶּמֶת עוֹבְרֵי עֲבֵרָה. וּבְסִפְרֵי (האזינו שטו) "וְאֵין עִמּוֹ אֵל נֵכָר" (דברים לב יב), שֶׁלֹּא תְּהֵא רְשׁוּת לְאֶחָד מִשָּׂרֵי הָאֻמּוֹת לָבֹא לִשְׁלֹט בָּכֶם, כְּעִנְיָן שֶׁנֶּאֱמַר "וַאֲנִי יוֹצֵא וְהִנֵּה שַׂר יָוָן" וְגוֹ', וְהוּא מַאֲמָרָם (כתובות קי), כָּל הַדָּר בְּחוּצָה לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ, שֶׁנֶּאֱמַר (ויקרא כ"ה:ל"ח) "לָתֵת לָכֶם אֶת אֶרֶץ כְּנַעַן לִהְיוֹת לָכֶם לֵאלֹהִים", וְאוֹמֵר (שמואל א כו יט) "כִּי גֵרְשׁוּנִי הַיּוֹם מֵהִסְתַּפֵּחַ בְּנַחֲלַת ה' לֵאמֹר לֵךְ עֲבֹד אֱלֹהִים אֲחֵרִים". וְאָמְרוּ בְּתוֹסֶפְתָּא דע"ז (פ"ה ה"ה), הֲרֵי הוּא אוֹמֵר (בראשית כח כא) "וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי וְהָיָה ה' לִי לֵאלֹהִים", וְאוֹמֵר "לָתֵת לָכֶם אֶת אֶרֶץ כְּנַעַן" (ויקרא כ"ה:ל"ח), כָּל זְמַן שֶׁאַתֶּם בְּאֶרֶץ כְּנַעַן הָיִיתִי לָכֶם לֵאלֹהִים, אֵין אַתֶּם בְּאֶרֶץ כְּנַעַן כִּבְיָכוֹל אֵין אֲנִי לָכֶם לֵאלֹהִים. וְכֵן הוּא אוֹמֵר (יהושע ד יג) "כְּאַרְבָּעִים אֶלֶף חֲלוּצֵי צָבָא עָבְרוּ לִפְנֵי ה'", וְאוֹמֵר (דהי"א כב יח) "וְנִכְבְּשָׁה הָאָרֶץ לִפְנֵי הַשֵּׁם וְלִפְנֵי עַמּוֹ", וְכִי תַּעֲלֶה עַל דַּעְתְּךָ שֶׁיִּשְׂרָאֵל מְכַבְּשִׁין אֶת הָאָרֶץ לִפְנֵי הַמָּקוֹם, אֶלָּא כָּל זְמַן שֶׁהֵן עָלֶיהָ כְּאִלּוּ הִיא מְכֻבֶּשֶׁת, הָא אֵינָם עָלֶיהָ אֵינָהּ מְכֻבֶּשֶׁת. וּמִן הָעִנְיָן הַזֶּה אָמְרוּ בְּסִפְרֵי (עקב מג), "וַאֲבַדְתֶּם מְהֵרָה" (דברים יא יז), אַף עַל פִּי שֶׁאֲנִי מַגְלֶה אֶתְכֶם מִן הָאָרֶץ לְחוּצָה לָאָרֶץ הֱיוּ מְצֻיָּנִין בַּמִּצְוֹת, שֶׁכְּשֶׁתַּחְזְרוּ לֹא יְהוּ עֲלֵיכֶם חֲדָשִׁים. מָשָׁל לְאָדוֹן שֶׁכָּעַס עַל אִשְׁתּוֹ וְשִׁלְּחָהּ לְבֵית אָבִיהָ, אָמַר לָהּ, הֱוִי מִתְקַשֶּׁטֶת תַּכְשִׁיטִים, שֶׁכְּשֶׁתַּחְזְרִי לֹא יִהְיוּ עָלַיִךְ חֲדָשִׁים. וְכֵן אָמַר יִרְמְיָה (לא כ), "הַצִּיבִי לָךְ צִיּוּנִים" אֵלּוּ הַמִּצְוֹת שֶׁיִּשְׂרָאֵל מְצֻיָּנִין בָּהֶם. וְהִנֵּה הַכָּתוּב שֶׁאָמַר (דברים יא יז-יח) "וַאֲבַדְתֶּם מְהֵרָה וְשַׂמְתֶּם אֶת דְּבָרַי אֵלֶּה" וְגוֹ' אֵינוֹ מְחַיֵּב בַּגָּלוּת אֶלָּא בְּחוֹבַת הַגּוּף, כִּתְפִלִּין וּמְזוּזוֹת, וּפֵרְשׁוּ בָּהֶן כְּדֵי שֶׁלֹּא יְהוּ חֲדָשִׁים עָלֵינוּ כְּשֶׁנַּחְזֹר לָאָרֶץ, כִּי עִקַּר כָּל הַמִּצְוֹת לַיּוֹשְׁבִים בְּאֶרֶץ ה'. וּלְפִיכָךְ אָמְרוּ בְּסִפְרֵי (ראה פ) "וִירִשְׁתֶּם אֹתָהּ וִישַׁבְתֶּם בָּהּ וּשְׁמַרְתֶּם לַעֲשׂוֹת" (דברים יא לא-לב), יְשִׁיבַת אֶרֶץ יִשְׂרָאֵל שְׁקוּלָה כְּנֶגֶד כָּל הַמִּצְוֹת שֶׁבַּתּוֹרָה. וְכָךְ הוּא בְּתוֹסֶפְתָּא דע"ז (פ"ה ה"ב). וְזוֹ הִיא מַחְשֶׁבֶת הָרְשָׁעִים (סנהדרין קה) שֶׁהָיוּ אוֹמְרִים לִיחֶזְקֵאל, רַבֵּינוּ יְחֶזְקֵאל, עֶבֶד שֶׁמְּכָרוֹ רַבּוֹ, יֵשׁ עָלָיו כְּלוּם, שֶׁנֶּאֱמַר (יחזקאל כ לב) "וְהָעֹלָה עַל רוּחֲכֶם הָיוֹ לֹא תִהְיֶה אֲשֶׁר אַתֶּם אֹמְרִים נִהְיֶה כַגּוֹיִם כְּמִשְׁפְּחוֹת הָאֲדָמָה לְשָׁרֵת עֵץ וָאָבֶן". וְזוֹ הִיא מִצְוַת יַעֲקֹב אָבִינוּ לְבֵיתוֹ וּלְכָל אֲשֶׁר עִמּוֹ בִּשְׁעַת בִּיאָתָם לָאָרֶץ (בראשית לה ב) "הָסִירוּ אֶת אֱלֹהֵי הַנֵּכָר אֲשֶׁר בְּתֹכְכֶם וְהִטַּהֲרוּ". וְהַשֵּׁם לוֹ לְבַדּוֹ נִתְכְּנוּ עֲלִילוֹת, שֶׁמֵּתָה רָחֵל בַּדֶּרֶךְ בִּתְחִלַּת בּוֹאָם בָּאָרֶץ, כִּי בִּזְכוּתָהּ לֹא מֵתָה בְּחוּצָה לָאָרֶץ, וּבִזְכוּתוֹ לֹא יָשַׁב בָּאָרֶץ עִם שְׁתֵּי אֲחָיוֹת, וְהִיא הָיְתָה הַנִּשֵּׂאת בְּאִסּוּר הָאַחְוָה. וְנִרְאֶה שֶׁנִּתְעַבְּרָה מִבִּנְיָמִין קֹדֶם בּוֹאָם בִּשְׁכֶם, וְלֹא נָגַע בָּהּ בָּאָרֶץ כְּלָל מִפְּנֵי הָעִנְיָן שֶׁהִזְכַּרְנוּ. וְאָמַר הַנָּבִיא (ירמיהו טז יח) "וְשִׁלַּמְתִּי רִאשׁוֹנָה מִשְׁנֵה עֲוֹנָם וְחַטָּאתָם עַל חַלְּלָם אֶת אַרְצִי בְּנִבְלַת שִׁקּוּצֵיהֶם וְתוֹעֲבוֹתֵיהֶם מָלְאוּ אֶת נַחֲלָתִי". וְהָעִנְיָן הַזֶּה הוּא בִּמְקוֹמוֹת רַבִּים בַּכְּתוּבִים, וְתִרְאֶנּוּ מְפֹרָשׁ בָּהֶם אַחַר שֶׁפָּקַחְתִּי בּוֹ עֵינֶיךָ. וְכָתַב ר"א בְּפָרָשַׁת וַיֵּלֶךְ (דברים לא טז), יָדַעְנוּ כִּי הַשֵּׁם אֶחָד, וְהַשִּׁנּוּי יָבֹא מֵהַמְּקַבְּלִים, וְהַשֵּׁם לֹא יְשַׁנֶּה מַעֲשָׂיו כִּי כֻלָּם הֵם בְּחָכְמָה, וּמֵעֲבוֹדַת הַשֵּׁם לִשְׁמֹר כֹּחַ הַקִּבּוּל כְּפִי הַמָּקוֹם, עַל כֵּן כָּתוּב "אֶת מִשְׁפַּט אֱלֹהֵי הָאָרֶץ", וְאָמַר בְּיַעֲקֹב "הָסִרוּ אֶת אֱלֹהֵי הַנֵּכָר", וְהֵפֶךְ הַמָּקוֹם הִדָּבֵק בָּעֲרָיוֹת שֶׁהֵם שְׁאֵר, וְהַמַּשְׂכִּיל יָבִין. אֵלּוּ דְּבָרָיו זַ"ל. וְאַל תָּשִׁיב עָלַי מִפָּסוּק "מִיכָאֵל שַׂרְכֶם" (דניאל י כא), כִּי הוּא שַׂר מְשָׁרֵת לְבַקֵּשׁ רַחֲמִים עַל יִשְׂרָאֵל, לֹא שַׂר מַלְכוּת וּמֶמְשָׁלָה. וְכֵן הָיָה שַׂר צָבָא הַנִּרְאֶה לִיהוֹשֻׁעַ בִּירִיחוֹ (יהושע ה יג), הֶרְאָה לוֹ כִּי הַשֵּׁם שְׁלָחוֹ לִלְחֹם מִלְחֲמוֹתֵיהֶם, כָּעִנְיָן בְּחִזְקִיָּהוּ (מלכים ב יט לה), וְגַם שֶׁהָיָה זֶה בִּהְיוֹתֵנוּ בְּחוּצָה לָאָרֶץ. וְאֵין רְשׁוּת לְפָרֵשׁ בְּעִנְיָן הָאָרֶץ יוֹתֵר מִזֶּה, אֲבָל אִם תִּזְכֶּה לְהָבִין הָאָרֶץ הָרִאשׁוֹנָה הַנִּזְכֶּרֶת בְּפָסוּק בְּרֵאשִׁית, וְהַנִּזְכֶּרֶת בְּפָרָשַׁת אִם בְּחֻקּוֹתַי, (ויקרא כ"ו:מ"ב) תֵּדַע סוֹד נִשְׂגָּב וְנֶעְלָם, וְתָבִין מַה שֶׁאָמְרוּ רַבּוֹתֵינוּ (תנחומא ויקהל ז), בֵּית הַמִּקְדָּשׁ שֶׁל מַעְלָה מְכֻוָּן כְּנֶגֶד בֵּית הַמִּקְדָשׁ שֶׁל מַטָּה. וּכְבָר רָמַזְתִּי לְךָ בַּפָּסוּק "כִּי לִי הָאָרֶץ" (שמות יט ה). וְהִנֵּה הִזְכִּיר הַכָּתוּב כִּי אַנְשֵׁי אֶרֶץ כְּנַעַן נֶעֶנְשׁוּ בַּעֲבוּר הָעֲרָיוֹת, וְרַבּוֹתֵינוּ אָמְרוּ (סנהדרין נו) שֶׁהֻזְהֲרוּ עֲלֵיהֶן מֵעֵת הַיְּצִירָה לְאָדָם וּלְנֹחַ, שֶׁלֹּא עָנַשׁ אֶלָּא אִם כֵּן הִזְהִיר, אֲבָל הַכָּתוּב לֹא יַזְכִּיר הָאַזְהָרָה, אֲבָל יֹאמַר כִּי הָאָרֶץ תָּקִיא אוֹתָם כִּי הָאָרֶץ תְּתַעֵב כָּל הַתּוֹעֵבוֹת הָאֵל. וְהִנֵּה לֹא אַנְשֵׁי אֶרֶץ כְּנַעַן בִּלְבַד הָיוּ מִן הַמֻּזְהָרִים. וְהַפָּרָשָׁה הִזְכִּירָה "כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם" (ויקרא י"ח:ג'), שֶׁהָיוּ גַּם הֵם עוֹשִׂים כְּכָל הַתּוֹעֵבוֹת הָאֵלֶּה וְלֹא תָּקִיא אוֹתָם אֶרֶץ מִצְרַיִם וְלֹא שְׁאָר אַרְצוֹת הַגּוֹיִם אֶת גּוֹיֵיהֶם, אֲבָל הָעִנְיָן כֻּלּוֹ לְמַעֲלַת הָאָרֶץ וּקְדֻשָּׁתָהּ. וְאָמַר הַכָּתוּב (כאן) "וַתָּקִא הָאָרֶץ", כִּי מֵעֵת שֶׁפָּקַד עֲוֹנָהּ עָלֶיהָ, שֶׁנִּגְזַר עַל הַכְּנַעֲנִים לְהִכָּרֵת, כְּאִלּוּ כְּבָר הֵקִיאָה אוֹתָם. אוֹ "וַתָּקִא" - לְמַעְלָה, כְּעִנְיַן "סָר צִלָּם מֵעֲלֵיהֶם" (במדבר יד ט):
@79 **וְנִכְרְתוּ הַנְּפָשׁוֹת הָעֹשֹׂת מִקֶּרֶב עַמָּם** זַרְעוֹ נִכְרָת וְיָמָיו נִכְרָתִים, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ז:ט'). וְהִנֵּה בַּכְּרֵיתוֹת בַּתּוֹרָה שְׁלֹשָׁה עִנְיָנִים, הָאֶחָד שֶׁנֶּאֱמַר בּוֹ "וְנִכְרַת הָאִישׁ הַהוּא" (שם שם ד ט), וְהַשֵּׁנִי שֶׁנֶּאֱמַר בָּהֶן "וְנִכְרְתוּ הַנְּפָשׁוֹת הָעוֹשׂוֹת" (כאן), "וְנִכְרְתָה הַנֶּפֶשׁ הַהִוא מִלְּפָנַי" (ויקרא כ"ב:ג'), וְהַשְּׁלִישִׁי שֶׁנֶּאֱמַר בָּהֶן "הִכָּרֵת תִּכָּרֵת הַנֶּפֶשׁ הַהִוא עֲוֹנָה בָהּ" (במדבר טו לא), וְאָמַר בְּיוֹם הַכִּפּוּרִים (להלן כג ל) "וְהַאֲבַדְתִּי אֶת הַנֶּפֶשׁ הַהִוא מִקֶּרֶב עַמָּהּ", וְאָמְרוּ בְּסִפְרָא (אמור פרק יד ד), לְפִי שֶׁהוּא אוֹמֵר כָּרֵת בְּכָל מָקוֹם וְאֵינִי יוֹדֵעַ מַה הוּא, כְּשֶׁהוּא אוֹמֵר "וְהַאֲבַדְתִּי" לִמֵּד עַל הַכָּרֵת שֶׁאֵינוֹ אֶלָּא אָבְדָן. וּבֵאוּר הָעִנְיָן, כִּי הָאוֹכֵל חֵלֶב אוֹ דָּם וְהוּא צַדִּיק וְרֻבּוֹ זְכוּיוֹת אֲבָל גָּבְרָה תַּאֲוָתוֹ עָלָיו וְנִכְשַׁל בָּעֲבֵרָה הַהִיא, יִכָּרְתוּ יָמָיו וְיָמוּת בַּנְּעוּרִים קֹדֶם שֶׁיַּגִּיעַ לִימֵי זִקְנָה, וְהֵם שִׁשִּׁים שָׁנָה, וְאֵין נַפְשׁוֹ בְּהִכָּרֵת, אֲבָל יִהְיֶה לוֹ חֵלֶק בְּעוֹלָם הַנְּשָׁמוֹת כְּפִי הָרָאוּי לְמַעֲשָׂיו הַטּוֹבִים, כִּי צַדִּיק הָיָה, וְיִהְיֶה לוֹ עוֹד חֵלֶק לָעוֹלָם הַבָּא, הוּא הָעוֹלָם שֶׁאַחֲרֵי הַתְּחִיָּה. וּבָזֶה אָמַר "וְנִכְרַת הָאִישׁ הַהוּא". וַאֲשֶׁר עִם הַחֵטְא הֶחָמוּר הַהוּא יִהְיוּ עֲוֹנֹתָיו מְרֻבִּין מִזְּכוּיוֹתָיו, עֹנֶשׁ הַכָּרֵת שֶׁבָּעֲבֵרָה הַחֲמוּרָה מַגִּיעַ לַנֶּפֶשׁ הַחוֹטֵאת לְאַחַר שֶׁתִּפָּרֵד מִן הַגּוּף, וְהִיא נִכְרֶתֶת מֵחַיֵּי עוֹלַם הַנְּשָׁמוֹת. וּבִמְחֻיְּבֵי הַכָּרֵת הַזֶּה רוֹמֵז הַכָּתוּב בְּאָמְרוֹ "וְנִכְרְתָה הַנֶּפֶשׁ הַהִוא מִלְּפָנַי", וּכְתִיב "וְהַאֲבַדְתִּי אֶת הַנֶּפֶשׁ הַהִוא מִקֶּרֶב עַמָּהּ". וְאֵלּוּ אֵין לָהֶם כָּרֵת בְּגוּפָם, אֶלָּא פְּעָמִים שֶׁיִּחְיוּ וְיַגִּיעוּ לְיָמִים רַבִּים וְגַם עַד זִקְנָה וְשֵׂיבָה, כְּעִנְיָן שֶׁכָּתוּב (קהלת ז טו) "וְיֵשׁ רָשָׁע מַאֲרִיךְ בְּרָעָתוֹ". וְזֶהוּ מַה שֶׁאָמְרוּ רַבּוֹתֵינוּ (עיין ר"ה יז), אֲבָל מִי שֶׁעֲוֹנֹתָיו מְרֻבִּין מִזְּכוּיוֹתָיו, וּבִכְלָלָן עֲוֹן פּוֹשְׁעֵי אֻמּוֹת הָעוֹלָם בְּגוּפָן, וְאָמַר רַב פַּפָּא, בַּעֲבֵרָה, כְּלוֹמַר בְּעֶרְוָה מִן הָעֲרָיוֹת, יוֹרְדִים לְגֵיהִנָּם וְנִדּוֹנִין שְׁנֵים עָשָׂר חֹדֶשׁ, לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ גּוּפָן כָּלֶה וְנִשְׁמָתָן נִשְׂרֶפֶת וְרוּחַ מְפַזַּרְתָּן תַּחַת כַּפּוֹת רַגְלֵי הַצַּדִּיקִים וכו'. וְיֵשׁ כָּרֵת חָמוּר, שֶׁנִּכְרַת גּוּפוֹ וְנַפְשׁוֹ, וְהוּא הַנֶּאֱמָר בּוֹ (במדבר טו לא) "כִּי דְבַר ה' בָּזָה וְאֶת מִצְוָתוֹ הֵפַר הִכָּרֵת תִּכָּרֵת הַנֶּפֶשׁ הַהִוא עֲוֹנָה בָהּ", וְדָרְשׁוּ (שבועות יג), "הִכָּרֵת" - בָּעוֹלָם הַזֶּה, "תִּכָּרֵת" - לָעוֹלָם הַבָּא, לוֹמַר שֶׁהוּא יָמוּת בַּנֹּעַר וְחַיָּתוֹ בַּקְּדֵשִׁים, שֶׁלֹּא תִּחְיֶה נַפְשׁוֹ בִּתְחִיַּת הַמֵּתִים וְאֵין לָהּ חֵלֶק לָעוֹלָם הַבָּא. וְאֵין כֶּפֶל הַכָּרֵת הַזֶּה הַנֶּאֱמָר בַּתּוֹרָה אֶלָּא בְּעִנְיְנֵי עֲבוֹדָה זָרָה וּמְגַדֵּף. וְרַבּוֹתֵינוּ דָּרְשׁוּ בּוֹ עוֹד בְּמַסֶּכֶת שְׁבוּעוֹת (שם), "כִּי דְבַר ה' בָּזָה" - זֶה הַפּוֹרֵק עֹל וּמְגַלֶּה פָּנִים בַּתּוֹרָה, "וְאֶת מִצְוָתוֹ הֵפַר" - זֶה הַמֵּפֵר בְּרִית בָּשָׂר. אֲבָל אֵינוֹ בְּכָל הַכְּרֵיתוֹת. וְשָׁם מְבֹאָר זֶה בַּגְּמָרָא שֶׁאֵין הַכֶּפֶל שֶׁל "הִכָּרֵת תִּכָּרֵת" בִּשְׁאָר חַיָּבֵי כְּרֵיתוֹת שֶׁבַּתּוֹרָה אֶלָּא בְּאֵלּוּ הַנִּדְרָשִׁים מִן הַכָּתוּב הַזֶּה, כִּי הַכָּתוּב הוּא בִּמְגַדֵּף וְעוֹבֵד ע"ז, וְהֵם הוֹסִיפוּ בַּמִּדְרָשִׁים הַכּוֹפְרִים בָּעִקָּר וְהָרְשָׁעִים הַמֻּחְלָטִים, וּכְמוֹ שֶׁנֶּאֱמַר בָּהֶם בַּקַּבָּלָה (ישעיהו סו כד), "כִּי תוֹלַעְתָּם לֹא תָמוּת וְאִשָּׁם לֹא תִכְבֶּה", וְהֵם אוֹתָם שֶׁמָּנוּ בַּמִּשְׁנָה (סנהדרין צ) וּבַבָּרַיְתָא (שם קח) וְאֵלּוּ שֶׁאֵין לָהֶם חֵלֶק לָעוֹלָם הַבָּא. וְכֵן נִרְאֶה שֶׁאֵין כָּל חַיָּבֵי כְּרֵיתוֹת בַּעֲרִירוּת וְאֵין כָּרֵת לְזַרְעָם אֶלָּא בְּאוֹתָן שֶׁכָּתוּב בָּהֶן "עֲרִירִים". וְיִתָּכֵן שֶׁהֻקְשׁוּ כָּל הָעֲרָיוֹת זוֹ לָזוֹ. אֲבָל בִּשְׁאָר הַכְּרֵיתוֹת, כְּגוֹן חֵלֶב וָדָם, אֵין לָנוּ. כָּתַב ר"א (להלן כג ל), יֵשׁ הֶפְרֵשׁ בֵּין "וְהַאֲבַדְתִּי" וּבֵין "וְנִכְרְתָה", וְלֹא אוּכַל לְפָרֵשׁ. יַחְשֹׁב הֶחָכָם כִּי הָאוֹבֶדֶת תֹּאבַד וְהַנִּכְרֶתֶת תִּכָּחֵד, וְלֹא יִשָּׂא אֱלֹהִים נֶפֶשׁ. וְתֵדַע וְתַשְׂכִּיל כִּי הַכְּרֵיתוֹת הַנִּזְכָּרוֹת בַּנֶּפֶשׁ, בִּטָּחוֹן גָּדוֹל בְּקִיּוּם הַנְּפָשׁוֹת אַחֲרֵי הַמִּיתָה וּבְמַתַּן הַשָּׂכָר בְּעוֹלַם הַנְּשָׁמוֹת, כִּי בְּאָמְרוֹ יִתְבָּרַךְ "וְנִכְרְתָה הַנֶּפֶשׁ הַהִוא מִקֶּרֶב עַמָּהּ", "וְנִכְרְתָה הַנֶּפֶשׁ הַהִוא מִלְּפָנַי", יוֹרֶה כִּי הַנֶּפֶשׁ הַחוֹטֵאת הִיא תִּכָּרֵת בַּעֲוֹנָהּ, וּשְׁאָר הַנְּפָשׁוֹת אֲשֶׁר לֹא חָטְאוּ תִּהְיֶינָה קַיָּמוֹת לְפָנָיו בַּזִּיו הָעֶלְיוֹן. וּלְכָךְ הוּא מְפָרֵשׁ "הַנֶּפֶשׁ הַהִוא עֲוֹנָה בָהּ", כִּי הֶעָוֹן אֲשֶׁר בָּהּ הוּא יַכְרִיתֶנָּה. וְטַעַם הָעִנְיָן, כִּי נִשְׁמַת הָאָדָם נֵר ה' אֲשֶׁר נֻפְּחָה בְּאַפֵּינוּ מִפִּי עֶלְיוֹן וְנִשְׁמַת שַׁדַּי, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב ז) "וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים", וְהִנֵּה הִיא בְּעִנְיָנָהּ וְלֹא תָּמוּת, וְאֵינֶנָּה מֻרְכֶּבֶת שֶׁתִּפָּרֵד הַרְכָּבָתָהּ וְתִהְיֶה לָהּ סִבַּת הֲוָיָה וְהֶפְסֵד כַּמֻּרְכָּבִים, אֲבָל קִיּוּמָהּ רָאוּי וְהוּא עוֹמֵד לָעַד כְּקִיּוּם הַשְּׂכָלִים הַנִּבְדָּלִים. וּלְכָךְ לֹא יִצְטָרֵךְ הַכָּתוּב לוֹמַר כִּי בִּזְכוּת הַמִּצְוֹת יִהְיֶה קִיּוּמָהּ, אֲבָל יֹאמַר כִּי בְּעֹנֶשׁ הָעֲבֵרוֹת תִּתְגָּאֵל וְתִטַּמֵּא וְתִכָּרֵת מִן הַקִּיּוּם הָרָאוּי, וְהוּא הַלָּשׁוֹן שֶׁתָּפְסָה בָּהֶן הַתּוֹרָה "כָּרֵת", כְּעָנָף הַנִּכְרָת מִן הָאִילָן שֶׁמִּמֶּנּוּ יִחְיֶה שָׁרְשׁוֹ. וְהוּא מַה שֶׁאָמְרוּ רַבּוֹתֵינוּ (ספרי שלח קיב), "מִקֶּרֶב עַמָּהּ" וְעַמָּהּ שָׁלוֹם, כִּי הַכָּרֵת שֶׁל הַנֶּפֶשׁ הַחוֹטֵאת יוֹרֶה עַל קִיּוּם שְׁאָר הַנְּפָשׁוֹת שֶׁלֹּא חָטְאוּ, וְהֵן עַמָּהּ שֶׁהֵן בְּשָׁלוֹם. וּכְבָר פֵּרַשְׁנוּ (שמות ו ב) כִּי כָל הַיִּעוּדִים שֶׁבַּתּוֹרָה בְּהַבְטָחוֹת אוֹ בְּהַתְרָאוֹת כֻּלָּם מוֹפְתִיִּים מִן הַנִּסִּים הַנִּסְתָּרִים, שֶׁבְּדָבָר מוֹפְתִי תַּבְטִיחַ וְתַזְהִיר הַתּוֹרָה לְעוֹלָם. וְלָכֵן הִזְהִיר בְּכָאן בַּכָּרֵת שֶׁהוּא עִנְיָן נִסִּי, וְלֹא תַּבְטִיחַ בַּקִּיּוּם שֶׁהוּא רָאוּי. וְהִנֵּה הַכְּרֵיתוֹת שֶׁבַּתּוֹרָה הֵם שְׁלֹשִׁים וְשֵׁשׁ (כריתות ב), וּמֵהֶם רַבִּים בְּאִסּוּרֵי הָעֶרְוָה, רְצוֹנִי לוֹמַר עַל בְּעִילָה הָאֲסוּרָה, וְכֵן מִיתוֹת בֵּית דִּין בְּעִנְיַן הַבְּעִילָה שֵׁשׁ עֶשְׂרֵה, וְאֵין בְּאִסּוּר הַמַּאֲכָלִים מִיתָה כְּלָל. וְהַטַּעַם בִּהְיוֹת הָעֳנָשִׁין הַגְּדוֹלִים כְּמִיתַת בֵּית דִּין וְהַכָּרֵת בְּעִנְיְנֵי הַבְּעִילָה, מִפְּנֵי שֶׁגִּלּוּי הָעֲרָיוֹת דָּבָר נִמְאָס מְאֹד אֵצֶל הַתּוֹרָה, כַּנִּזְכָּר בְּזֹאת הַפָּרָשָׁה וּבִמְקוֹמוֹת רַבִּים בַּכָּתוּב, וַחֲכָמִים מַזְכִּירִין לְעוֹלָם (סנהדרין עד ועוד), עֲבוֹדָה זָרָה וְגִלּוּי עֲרָיוֹת וּשְׁפִיכוּת דָּמִים, יַזְכִּירוּ אוֹתָהּ אַחַר עֲבוֹדָה זָרָה וְקֹדֶם שְׁפִיכוּת דָּמִים, וּכְמוֹ שֶׁאָמְרוּ (סנהדרין קו), אֱלֹהֵיהֶם שֶׁל אֵלּוּ שׂוֹנֵא זִמָּה הוּא. וְיֵשׁ לָעִנְיָן סוֹד גָּדוֹל בְּסוֹד הַיְּצִירָה. וְהָרַב אָמַר בְּמוֹרֶה הַנְּבֻכִים (ג מא), בַּעֲבוּר הֱיוֹת יֵצֶר הָאָדָם גָּדוֹל בְּעִנְיַן הַמִּשְׁגָּל, וְהַתַּאֲוָה בּוֹ רַבָּה, וְהַדְּבָרִים שֶׁהֵם רַבֵּי הַמִּכְשׁוֹלוֹת צְרִיכִים עֹנֶשׁ גָּדוֹל לְיַסֵּר אוֹתָם. וְגַם זֶה אֱמֶת:
